window.ETSDATA=window.ETSDATA||{};window.ETSDATA[1]={"lc":{"p1":[{"n":1,"opts":["The woman is carrying a tray of food.","The woman is wearing a jacket.","The woman is tying up her hair.","The woman is removing her hat."],"vi":["Người phụ nữ đang bưng một khay thức ăn.","Người phụ nữ đang mặc một chiếc áo khoác.","Người phụ nữ đang buộc tóc.","Người phụ nữ đang cởi mũ."],"ans":"B","a":"E26-T01-01.mp3","img":"q1.jpg"},{"n":2,"opts":["Some people are standing next to a filing cabinet.","Some people are searching through a desk.","Some people are watching a presentation.","Some people are looking at a book."],"vi":["Một số người đang đứng cạnh tủ đựng hồ sơ.","Một số người đang tìm kiếm đồ trong bàn làm việc.","Một số người đang xem một bài thuyết trình.","Một số người đang nhìn vào một cuốn sách."],"ans":"D","a":"E26-T01-02.mp3","img":"q2.jpg"},{"n":3,"opts":["A woman is holding a phone up to her ear.","A woman is pouring a beverage into a glass.","Some light fixtures are hanging from the ceiling.","Some tiles are being installed in a hallway."],"vi":["Một người phụ nữ đang áp điện thoại vào tai.","Một người phụ nữ đang rót đồ uống vào ly.","Một số đèn chiếu sáng đang treo trên trần nhà.","Một số viên gạch đang được lắp đặt ở hành lang."],"ans":"C","a":"E26-T01-03.mp3","img":"q3.jpg"},{"n":4,"opts":["A wooden crate is filled with vegetables.","One of the men is putting vegetables into a shopping bag.","A backpack has been set on the ground.","One of the men is reaching into a bucket."],"vi":["Một chiếc thùng gỗ chứa đầy rau củ.","Một trong những người đàn ông đang cho rau vào túi mua hàng.","Một chiếc ba lô đã được đặt trên mặt đất.","Một trong những người đàn ông đang thò tay vào một cái xô."],"ans":"A","a":"E26-T01-04.mp3","img":"q4.jpg"},{"n":5,"opts":["Painting supplies have been laid out on the floor.","He's laying a brush down on a windowsill.","He's lifting a can of paint by its handle.","Cans of paint have been placed on a step stool."],"vi":["Các dụng cụ sơn đã được bày ra trên sàn nhà.","Anh ấy đang đặt một chiếc chổi sơn xuống bậu cửa sổ.","Anh ấy đang nhấc một lon sơn bằng tay cầm.","Những lon sơn đã được đặt trên một cái ghế bậc thang."],"ans":"A","a":"E26-T01-05.mp3","img":"q5.jpg"},{"n":6,"opts":["A path is covered with fallen branches.","A tree is lying across a grassy area.","Some water has pooled on a path.","Some cyclists are riding through a field."],"vi":["Con đường bị bao phủ bởi những cành cây gãy.","Một cái cây đang nằm ngang qua một bãi cỏ.","Có nước đọng thành vũng trên đường.","Một số người đi xe đạp đang đi qua một cánh đồng."],"ans":"C","a":"E26-T01-06.mp3","img":"q6.jpg"}],"p2":[{"n":7,"q":"Where is the conference being held?","qvi":"Hội nghị được tổ chức ở đâu?","opts":["A three-day vacation.","At the Riverview Hotel.","In the supply cabinet."],"vi":["Một kỳ nghỉ ba ngày.","Tại khách sạn Riverview.","Trong tủ vật tư."],"ans":"B","a":"E26-T01-07.mp3"},{"n":8,"q":"When does the warehouse manager arrive?","qvi":"Khi nào quản lý kho hàng đến?","opts":["Sure, no problem.","About twelve shipping boxes.","Not until this afternoon."],"vi":["Chắc chắn rồi, không vấn đề gì.","Khoảng 12 thùng hàng.","Phải đến chiều nay."],"ans":"C","a":"E26-T01-08.mp3"},{"n":9,"q":"There's a nice park nearby, right?","qvi":"Có một công viên đẹp ở gần đây, đúng không?","opts":["Did you order paper for the copier?","Yes—it's next to Greendale Lake.","They're in the parking garage."],"vi":["Bạn đã đặt giấy cho máy photocopy chưa?","Đúng vậy - nó nằm cạnh hồ Greendale.","Họ đang ở trong nhà để xe."],"ans":"B","a":"E26-T01-09.mp3"},{"n":10,"q":"Who sent the meeting minutes to the accounting department?","qvi":"Ai đã gửi biên bản cuộc họp cho bộ phận kế toán?","opts":["Our office assistant.","They have a savings account.","Cash and credit cards."],"vi":["Trợ lý văn phòng của chúng tôi.","Họ có một tài khoản tiết kiệm.","Tiền mặt và thẻ tín dụng."],"ans":"A","a":"E26-T01-10.mp3"},{"n":11,"q":"I'd like to know what you think of our new finance analyst.","qvi":"Tôi muốn biết bạn nghĩ gì về nhà phân tích tài chính mới.","opts":["I've prepared the decorations for tomorrow.","He seems very competent.","It's finally stopped raining."],"vi":["Tôi đã chuẩn bị đồ trang trí cho ngày mai.","Anh ấy có vẻ rất có năng lực.","Cuối cùng trời cũng tạnh mưa."],"ans":"B","a":"E26-T01-11.mp3"},{"n":12,"q":"Let's go on the company retreat.","qvi":"Chúng ta hãy đi dã ngoại công ty đi.","opts":["Oh, did he?","Yes, that's a good idea.","He tried to solve that problem."],"vi":["Ồ, anh ấy đã làm vậy sao?","Vâng, đó là một ý kiến hay.","Anh ấy đã cố gắng giải quyết vấn đề đó."],"ans":"B","a":"E26-T01-12.mp3"},{"n":13,"q":"What time can I pick up my glasses?","qvi":"Mấy giờ tôi có thể lấy kính của mình?","opts":["No, it's not very heavy.","About twenty meters.","We close at six o'clock."],"vi":["Không, nó không nặng lắm.","Khoảng 20 mét.","Chúng tôi đóng cửa lúc 6 giờ."],"ans":"C","a":"E26-T01-13.mp3"},{"n":14,"q":"The sales team knows how to use the tracking software, don't they?","qvi":"Nhóm bán hàng biết cách sử dụng phần mềm theo dõi, đúng không?","opts":["It's on the lower shelf.","A twelve-thirty departure.","I haven't seen them using it yet."],"vi":["Nó ở ngăn dưới.","Chuyến khởi hành lúc 12:30.","Tôi vẫn chưa thấy họ sử dụng nó."],"ans":"C","a":"E26-T01-14.mp3"},{"n":15,"q":"Are you going to the hardware store on Mill Street?","qvi":"Bạn có định đến cửa hàng ngũ kim trên phố Mill không?","opts":["That store hasn't opened yet.","The blue package you sent me.","Some nails and a hammer."],"vi":["Cửa hàng đó vẫn chưa mở cửa.","Gói hàng màu xanh bạn gửi cho tôi.","Một vài chiếc đinh và một cái búa."],"ans":"A","a":"E26-T01-15.mp3"},{"n":16,"q":"Would you be able to write the introduction for the workshop?","qvi":"Bạn có thể viết lời giới thiệu cho hội thảo được không?","opts":["That was a great book.","OK, I'd be happy to.","He doesn't have any more."],"vi":["Đó là một cuốn sách tuyệt vời.","Được chứ, tôi rất sẵn lòng.","Anh ấy không còn cái nào nữa."],"ans":"B","a":"E26-T01-16.mp3"},{"n":17,"q":"I picked up some flowers for Tunji's retirement party.","qvi":"Tôi đã mua một ít hoa cho tiệc nghỉ hưu của Tunji.","opts":["No, pick any day.","That was thoughtful.","A delivery driver."],"vi":["Không, hãy chọn bất kỳ ngày nào.","Thật là chu đáo.","Một tài xế giao hàng."],"ans":"B","a":"E26-T01-17.mp3"},{"n":18,"q":"Which meeting room did you tell the interns to go to?","qvi":"Bạn đã bảo các thực tập sinh đi đến phòng họp nào?","opts":["The Jefferson Room.","The meeting was fun, thanks.","Yes, it's a conference call."],"vi":["Phòng Jefferson.","Cuộc họp rất vui, cảm ơn.","Vâng, đó là một cuộc họp qua điện thoại."],"ans":"A","a":"E26-T01-18.mp3"},{"n":19,"q":"Is your dental appointment next Tuesday?","qvi":"Cuộc hẹn nha khoa của bạn là vào thứ Ba tới phải không?","opts":["You can borrow mine.","I'll have to check my calendar.","Yes, it was a good meeting."],"vi":["Bạn có thể mượn cái của tôi.","Tôi sẽ phải kiểm tra lịch của mình.","Vâng, đó là một cuộc họp tốt."],"ans":"B","a":"E26-T01-19.mp3"},{"n":20,"q":"Why aren't there any brochures in the lobby?","qvi":"Tại sao không có bất kỳ tập quảng cáo nào ở sảnh?","opts":["No, I haven't received my confirmation e-mail yet.","My winter coat.","Because someone just took the last one."],"vi":["Không, tôi vẫn chưa nhận được email xác nhận.","Áo khoác mùa đông của tôi.","Vì ai đó vừa mới lấy cái cuối cùng rồi."],"ans":"C","a":"E26-T01-20.mp3"},{"n":21,"q":"What's the process for submitting my expense report?","qvi":"Quy trình nộp báo cáo chi phí của tôi là gì?","opts":["You send it to the finance department.","The end of the day.","That's correct."],"vi":["Bạn gửi nó cho bộ phận tài chính.","Cuối ngày.","Đúng vậy."],"ans":"A","a":"E26-T01-21.mp3"},{"n":22,"q":"Do you sell your products online or in stores?","qvi":"Bạn bán sản phẩm trực tuyến hay tại cửa hàng?","opts":["About twenty percent off.","A product demonstration.","Only online."],"vi":["Giảm giá khoảng 20%.","Một buổi trình diễn sản phẩm.","Chỉ bán trực tuyến."],"ans":"C","a":"E26-T01-22.mp3"},{"n":23,"q":"How often do you charge this device?","qvi":"Bạn có thường xuyên sạc thiết bị này không?","opts":["Whenever the light turns red.","A wireless one.","At the hardware store."],"vi":["Bất cứ khi nào đèn chuyển sang màu đỏ.","Một cái không dây.","Tại cửa hàng ngũ kim."],"ans":"A","a":"E26-T01-23.mp3"},{"n":24,"q":"The tickets to Friday night's concert cost ten dollars each.","qvi":"Vé xem buổi hòa nhạc tối thứ Sáu giá 10 đô la mỗi vé.","opts":["Actually, they're fifteen.","No, I can't play the guitar.","It's in aisle five."],"vi":["Thực ra, chúng có giá 15 đô la.","Không, tôi không biết chơi ghi-ta.","Nó ở lối đi số 5."],"ans":"A","a":"E26-T01-24.mp3"},{"n":25,"q":"Can't you update the database today?","qvi":"Bạn không thể cập nhật cơ sở dữ liệu hôm nay sao?","opts":["I did it yesterday.","That's an interesting movie.","No, just me."],"vi":["Tôi đã làm việc đó hôm qua rồi.","Đó là một bộ phim thú vị.","Không, chỉ có tôi thôi."],"ans":"A","a":"E26-T01-25.mp3"},{"n":26,"q":"How are we going to fit the extra supplies in that closet?","qvi":"Làm thế nào để chúng ta xếp thêm vật tư vào cái tủ đó?","opts":["I've already read them.","Natalie's in charge of supplies.","It's the door at the end of the hallway."],"vi":["Tôi đã đọc chúng rồi.","Natalie phụ trách vật tư.","Đó là cánh cửa ở cuối hành lang."],"ans":"B","a":"E26-T01-26.mp3"},{"n":27,"q":"Have all the new windows been installed?","qvi":"Tất cả các cửa sổ mới đã được lắp đặt xong chưa?","opts":["Sure, I'll close the blinds.","The construction crew is almost finished.","This isn't the tallest ladder available."],"vi":["Chắc chắn rồi, tôi sẽ đóng rèm.","Đội thi công gần như đã hoàn thành.","Đây không phải là cái thang cao nhất hiện có."],"ans":"B","a":"E26-T01-27.mp3"},{"n":28,"q":"Would you rather go to lunch now or at noon?","qvi":"Bạn muốn đi ăn trưa bây giờ hay vào buổi trưa?","opts":["I'm taking a client to lunch.","On the corner of Fourth and Main.","The daily special is soup and a sandwich."],"vi":["Tôi đang đưa một khách hàng đi ăn trưa.","Ở góc đường số 4 và phố Main.","Món đặc biệt hàng ngày là súp và bánh mì kẹp."],"ans":"A","a":"E26-T01-28.mp3"},{"n":29,"q":"You're taking the training in the afternoon, aren't you?","qvi":"Bạn sẽ tham gia đào tạo vào buổi chiều, đúng không?","opts":["The new head of the accounting department.","No, I take my coffee black.","Well, it depends on my schedule."],"vi":["Trưởng bộ phận kế toán mới.","Không, tôi uống cà phê đen.","Chà, nó còn tùy thuộc vào lịch trình của tôi."],"ans":"C","a":"E26-T01-29.mp3"},{"n":30,"q":"Shouldn't Ms. Ishida look over the financial projections?","qvi":"Chẳng phải bà Ishida nên xem qua các dự báo tài chính sao?","opts":["I just got this monitor.","To the south entrance.","I'm meeting with her at ten."],"vi":["Tôi vừa mới nhận được cái màn hình này.","Đến lối vào phía Nam.","Tôi sẽ họp với bà ấy lúc 10 giờ."],"ans":"C","a":"E26-T01-30.mp3"},{"n":31,"q":"When are you going to choose a new project manager?","qvi":"Khi nào bạn định chọn quản lý dự án mới?","opts":["The projector's not working correctly.","Next to the front entrance.","I'm really busy this week."],"vi":["Máy chiếu hoạt động không đúng cách.","Cạnh lối vào phía trước.","Tuần này tôi thực sự rất bận."],"ans":"C","a":"E26-T01-31.mp3"}],"p3":[{"ns":[32,34],"script":[["W","Hey, Oliver. Did you see the focus group results for our new spicy cheddar cheese? Everyone really liked it.","Này Oliver. Anh đã thấy kết quả khảo sát nhóm khách hàng mục tiêu cho loại phô mai cheddar cay mới của chúng ta chưa? Mọi người thực sự rất thích nó."],["M","Yes. It should be a great addition to our company's line of cheeses.","Vâng. Nó sẽ là một sự bổ sung tuyệt vời cho dòng phô mai của công ty chúng ta."],["W","Several people mentioned that they'd like to use it in recipes-to add to sauces, for example.","Một vài người đề cập rằng họ muốn sử dụng nó trong các công thức nấu ăn - ví dụ như thêm vào nước sốt."],["M","So maybe we should consider selling a shredded version that would melt easily when cooked.","Vậy có lẽ chúng ta nên cân nhắc bán phiên bản dạng bào sợi để nó có thể tan chảy dễ dàng khi nấu."],["W","I'm sure we could do that. I'll get in touch with the production manager with that request.","Tôi chắc chắn chúng ta có thể làm được. Tôi sẽ liên lạc với quản lý sản xuất về yêu cầu đó."]],"qs":[{"n":32,"q":"What type of food product does the speakers' company sell?","qvi":"Công ty của những người nói bán loại thực phẩm nào?","opts":["Candy","Cheese","Bread","Pasta"],"vi":["Kẹo","Phô mai","Bánh mì","Mì Ý"],"ans":"B"},{"n":33,"q":"What does the man suggest?","qvi":"Người đàn ông đề xuất điều gì?","opts":["Lowering prices","Hiring more workers","Publishing a recipe","Offering additional options"],"vi":["Giảm giá","Thuê thêm nhân công","Công bố một công thức nấu ăn","Cung cấp thêm các lựa chọn bổ sung"],"ans":"D"},{"n":34,"q":"What does the woman say she will do?","qvi":"Người phụ nữ nói cô ấy sẽ làm gì?","opts":["Send a schedule update","Contact a production manager","Visit the company headquarters","Plan an advertising campaign"],"vi":["Gửi cập nhật lịch trình","Liên lạc với quản lý sản xuất","Thăm trụ sở chính của công ty","Lập kế hoạch cho một chiến dịch quảng cáo"],"ans":"B"}],"a":"E26-T01-32-34.mp3"},{"ns":[35,37],"script":[["M","Hi. I'm calling to book three tickets for this Thursday's tennis match. Are there any seats left?","Xin chào. Tôi gọi điện để đặt ba vé cho trận đấu quần vợt vào thứ Năm này. Còn chỗ trống nào không?"],["W","Just a few! Tickets for Thursday's match have been selling quickly.","Chỉ còn vài chỗ thôi! Vé cho trận đấu thứ Năm đang bán rất nhanh."],["M","I'm not surprised! After all, Ife Rotimi won the regional championship tournament last month. Everyone wants to see her play after her incredible performance.","Tôi không ngạc nhiên đâu! Suy cho cùng, Ife Rotimi đã giành chức vô địch giải đấu khu vực vào tháng trước. Mọi người đều muốn xem cô ấy thi đấu sau màn trình diễn đáng kinh ngạc đó."],["W","Well, there's only one group of three seats together. Advance payment is required to hold them.","Chà, chỉ còn duy nhất một cụm ba ghế cạnh nhau. Cần phải thanh toán trước để giữ chỗ."]],"qs":[{"n":35,"q":"Why is the man calling?","qvi":"Tại sao người đàn ông gọi điện?","opts":["To sign up for lessons","To enter a competition","To buy tickets to an event","To ask about branded merchandise"],"vi":["Để đăng ký các bài học","Để tham gia một cuộc thi","Để mua vé xem một sự kiện","Để hỏi về hàng hóa có thương hiệu"],"ans":"C"},{"n":36,"q":"What did Ife Rotimi do last month?","qvi":"Ife Rotimi đã làm gì vào tháng trước?","opts":["She won a regional tournament.","She gave a television interview.","She started an institute.","She hired a new coach."],"vi":["Cô ấy đã thắng một giải đấu khu vực.","Cô ấy đã thực hiện một cuộc phỏng vấn truyền hình.","Cô ấy đã thành lập một học viện.","Cô ấy đã thuê một huấn luyện viên mới."],"ans":"A"},{"n":37,"q":"What does the woman say is required?","qvi":"Người phụ nữ nói điều gì là bắt buộc?","opts":["A parking permit","A photo ID","Contact information","Advance payment"],"vi":["Giấy phép đậu xe","Giấy tờ tùy thân có ảnh","Thông tin liên lạc","Thanh toán trước"],"ans":"D"}],"a":"E26-T01-35-37.mp3"},{"ns":[38,40],"script":[["W","Thanks for agreeing to help me organize the library's annual fund-raising dinner, Klaus. We hope the event brings in enough money to expand our children's book section.","Cảm ơn anh đã đồng ý giúp tôi tổ chức bữa tiệc tối gây quỹ thường niên của thư viện, Klaus. Chúng tôi hy vọng sự kiện sẽ mang lại đủ tiền để mở rộng phần sách dành cho thiếu nhi."],["M","What task would you like me to start with?","Tôi nên bắt đầu với công việc nào đây?"],["W","Well, I could use some help sending out the invitations.","Chà, tôi cần sự giúp đỡ trong việc gửi thư mời."],["M","OK, I can take care of that. Is there a list of attendees available?","Được rồi, tôi có thể đảm nhận việc đó. Có sẵn danh sách người tham dự không?"],["W","It's in my computer files. I'll e-mail it to you.","Nó nằm trong tệp máy tính của tôi. Tôi sẽ gửi email cho anh."]],"qs":[{"n":38,"q":"What event are the speakers planning?","qvi":"Các diễn giả đang lên kế hoạch cho sự kiện gì?","opts":["A fund-raising dinner","An art gallery opening","An awards ceremony","A children's book fair"],"vi":["Một bữa tối gây quỹ","Khai trương phòng trưng bày nghệ thuật","Một lễ trao giải","Một hội chợ sách thiếu nhi"],"ans":"A"},{"n":39,"q":"What task does the woman ask the man to help with?","qvi":"Người phụ nữ nhờ người đàn ông giúp đỡ việc gì?","opts":["Arranging a shuttle service","Choosing a catering firm","Preparing a speech","Sending out invitations"],"vi":["Sắp xếp dịch vụ xe đưa đón","Chọn một công ty cung cấp tiệc tận nơi","Chuẩn bị bài phát biểu","Gửi thiệp mời"],"ans":"D"},{"n":40,"q":"What does the woman say she will do?","qvi":"Người phụ nữ nói cô ấy sẽ làm gì?","opts":["E-mail a list","Speak with a colleague","Provide a password","Post a job opening"],"vi":["Gửi email một danh sách","Nói chuyện với một đồng nghiệp","Cung cấp mật khẩu","Đăng tin tuyển dụng"],"ans":"A"}],"a":"E26-T01-38-40.mp3"},{"ns":[41,43],"script":[["W","Hey, Brian and Matteo. I found some great pens to give away at the community festival to promote our business.","Chào Brian và Matteo. Tôi đã tìm thấy một số chiếc bút rất tuyệt để phát tặng tại lễ hội cộng đồng nhằm quảng bá doanh nghiệp của chúng ta."],["M1","Great. Can we put our cleaning service logo on them?","Tuyệt quá. Chúng ta có thể in logo dịch vụ vệ sinh của mình lên đó không?"],["W","Yes, for no extra charge. And they're biodegradable. They're made from paper.","Có chứ, không mất thêm phí đâu. Và chúng có thể phân hủy sinh học. Chúng được làm từ giấy."],["M2","So when we hand them out, we can mention that.","Vậy khi chúng ta phát bút, chúng ta có thể đề cập đến điều đó."],["M1","As well as talk about the organic cleaning supplies our company uses.","Cũng như nói về các vật dụng vệ sinh hữu cơ mà công ty chúng ta sử dụng."],["W","OK. I'll go ahead and order several cases.","Được rồi. Tôi sẽ tiến hành đặt hàng vài thùng."]],"qs":[{"n":41,"q":"What event are the speakers preparing for?","qvi":"Các diễn giả đang chuẩn bị cho sự kiện gì?","opts":["A new-employee orientation","A grand opening","A community festival","A trade show"],"vi":["Buổi định hướng nhân viên mới","Lễ khai trương","Một lễ hội cộng đồng","Một hội chợ triển lãm thương mại"],"ans":"C"},{"n":42,"q":"What is mentioned about some pens?","qvi":"Điều gì được đề cập về một số chiếc bút?","opts":["They are available in multiple colors.","They use permanent ink.","They are preferred by book authors.","They are made from paper."],"vi":["Chúng có nhiều màu sắc khác nhau.","Chúng sử dụng mực vĩnh cửu.","Chúng được các tác giả sách ưa chuộng.","Chúng được làm từ giấy."],"ans":"D"},{"n":43,"q":"What does the woman offer to do?","qvi":"Người phụ nữ đề nghị làm gì?","opts":["Reserve a booth","Place an order","Organize a focus group","Revise a budget"],"vi":["Đặt một gian hàng","Đặt hàng","Tổ chức một nhóm khảo sát tập trung","Xem xét lại ngân sách"],"ans":"B"}],"a":"E26-T01-41-43.mp3"},{"ns":[44,46],"script":[["W","Jamestown Recycling Facility. How can I help you?","Cơ sở tái chế Jamestown xin nghe. Tôi có thể giúp gì cho ông?"],["M","Hi. I'm preparing to move soon, and I have some electronics, such as televisions and computers, that I'd like to get rid of before I put my house on the market.","Chào cô. Tôi sắp chuyển nhà và tôi có một số thiết bị điện tử như tivi, máy tính muốn bỏ đi trước khi rao bán nhà."],["W","Yes, that's right. We'll take all electronics.","Vâng, đúng vậy. Chúng tôi nhận tất cả các thiết bị điện tử."],["M","Great. I just have one question. Do you provide a pickup service?","Tuyệt. Tôi chỉ có một câu hỏi. Các bạn có cung cấp dịch vụ đến tận nơi lấy hàng không?"],["W","No, unfortunately you'll have to bring everything here yourself. However, on our Web site we list a number of companies that can remove and dispose of the items for you.","Không, tiếc là ông sẽ phải tự mang mọi thứ đến đây. Tuy nhiên, trên trang web của chúng tôi có liệt kê một số công ty có thể đến dọn dẹp và xử lý các món đồ đó giúp ông."]],"qs":[{"n":44,"q":"Where does the woman work?","qvi":"Người phụ nữ làm việc ở đâu?","opts":["At a delivery service","At an electronics store","At a recycling facility","At a real estate agency"],"vi":["Tại một dịch vụ giao hàng","Tại một cửa hàng điện tử","Tại một cơ sở tái chế","Tại một công ty bất động sản"],"ans":"C"},{"n":45,"q":"What does the man want to dispose of?","qvi":"Người đàn ông muốn vứt bỏ cái gì?","opts":["Yard waste","Used furniture","Electronics","Books"],"vi":["Rác thải sân vườn","Đồ nội thất cũ","Đồ điện tử","Sách"],"ans":"C"},{"n":46,"q":"What does the woman say can be found on a Web site?","qvi":"Người phụ nữ nói rằng có thể tìm thấy gì trên một trang web?","opts":["A list of companies","Hours of operation","A permit application","Directions to a site"],"vi":["Danh sách các công ty","Giờ hoạt động","Đơn xin giấy phép","Hướng dẫn đến một địa điểm"],"ans":"A"}],"a":"E26-T01-44-46.mp3"},{"ns":[47,49],"script":[["M","Zaina! What a surprise! I haven't seen you since we took that class for business owners together last year.","Zaina! Thật bất ngờ quá! Tôi đã không gặp cô kể từ khi chúng ta cùng học lớp dành cho chủ doanh nghiệp vào năm ngoái."],["W","Great, thanks. I was just in the neighborhood and thought I'd stop in for a cookie or a piece of cake. You have so many delicious baked goods here.","Tôi vẫn khỏe, cảm ơn anh. Tôi vừa có việc ở khu này và nghĩ mình nên ghé vào mua một chiếc bánh quy hoặc một miếng bánh ngọt. Ở đây anh có nhiều đồ nướng ngon quá."],["M","Thank you! It's been a good year for business. I'm even considering opening a second location.","Cảm ơn cô! Năm nay việc kinh doanh rất thuận lợi. Tôi thậm chí đang cân nhắc mở cơ sở thứ hai."],["W","Really? Well, I noticed that Sunnyvale Restaurant went out of business, and the building's up for lease. It's very close to the local university.","Thật sao? Chà, tôi thấy nhà hàng Sunnyvale đã đóng cửa và tòa nhà đó đang cho thuê. Nó rất gần trường đại học địa phương."]],"qs":[{"n":47,"q":"How do the speakers know each other?","qvi":"Làm thế nào các diễn giả biết nhau?","opts":["They took a class together.","They used to work for the same company.","They grew up in the same neighborhood.","They met on a train."],"vi":["Họ đã học cùng lớp.","Họ từng làm việc cho cùng một công ty.","Họ lớn lên trong cùng một khu phố.","Họ gặp nhau trên tàu hỏa."],"ans":"A"},{"n":48,"q":"What type of business does the man most likely own?","qvi":"Người đàn ông có khả năng sở hữu loại hình kinh doanh nào nhất?","opts":["A fitness center","A real estate agency","A culinary school","A bakery"],"vi":["Trung tâm thể dục","Đại lý bất động sản","Trường dạy nấu ăn","Tiệm bánh"],"ans":"D"},{"n":49,"q":"What advantage does the woman point out about a rental space?","qvi":"Người phụ nữ chỉ ra ưu điểm nào về không gian cho thuê?","opts":["Its price","Its size","Its location","Its design"],"vi":["Giá cả","Kích thước","Vị trí","Thiết kế"],"ans":"C"}],"a":"E26-T01-47-49.mp3"},{"ns":[50,52],"script":[["W","Hi, Koji. I think our new video game is nearly ready to be released. Are you aware of any improvements that need to be made before then?","Chào Koji. Tôi nghĩ trò chơi điện tử mới của chúng ta gần như đã sẵn sàng để phát hành. Anh có biết có cải tiến nào cần thực hiện trước đó không?"],["M","Actually, I just finished testing the game this morning. I found a problem in the third stage of the game. There were a few times when my character couldn't move.","Thực ra, tôi vừa mới kiểm tra xong trò chơi sáng nay. Tôi đã tìm thấy một vấn đề ở màn thứ ba. Có vài lần nhân vật của tôi không thể di chuyển được."],["W","Oh, that's strange!","Ồ, lạ thật đấy!"],["M","I double-checked the problem using a different controller. The same issue came up.","Tôi đã kiểm tra lại vấn đề bằng cách sử dụng một bộ điều khiển khác. Vấn đề tương tự vẫn xảy ra."],["W","Oh. I think Pauline had a similar problem with a game she tested. Maybe you should ask her about it.","Ồ. Tôi nghĩ Pauline cũng gặp vấn đề tương tự với một trò chơi cô ấy đã kiểm tra. Có lẽ anh nên hỏi cô ấy về việc đó."]],"qs":[{"n":50,"q":"Who most likely are the speakers?","qvi":"Các diễn giả có khả năng cao là ai?","opts":["Film actors","Museum directors","Video game developers","Investigative journalists"],"vi":["Diễn viên điện ảnh","Giám đốc bảo tàng","Nhà phát triển trò chơi điện tử","Nhà báo điều tra"],"ans":"C"},{"n":51,"q":"What did the man recently do?","qvi":"Người đàn ông đã làm gì gần đây?","opts":["He secured some funding.","He tested a product.","He read a script.","He conducted an interview."],"vi":["Ông ấy đã đảm bảo được một số nguồn tài trợ.","Ông ấy đã thử nghiệm một sản phẩm.","Ông ấy đã đọc một kịch bản.","Ông ấy đã thực hiện một cuộc phỏng vấn."],"ans":"B"},{"n":52,"q":"What does the woman suggest?","qvi":"Người phụ nữ gợi ý điều gì?","opts":["Consulting a colleague","Planning an event","Negotiating a contract","Giving a client an update"],"vi":["Tham khảo ý kiến đồng nghiệp","Lên kế hoạch cho một sự kiện","Thương lượng một hợp đồng","Cập nhật thông tin cho khách hàng"],"ans":"A"}],"a":"E26-T01-50-52.mp3"},{"ns":[53,55],"script":[["M","You've reached the maintenance office at Hillview Apartment Complex.","Đây là văn phòng bảo trì tại khu chung cư Hillview."],["W","Hi. This is Palavi Sen from unit 35B. I'm calling because the new thermostat in my apartment isn't working. It keeps shutting off and turning on randomly, so my apartment is getting cold.","Xin chào. Tôi là Palavi Sen ở căn hộ 35B. Tôi gọi vì bộ điều chỉnh nhiệt mới trong căn hộ của tôi không hoạt động. Nó cứ tự tắt rồi bật ngẫu nhiên, khiến căn hộ của tôi trở nên rất lạnh."],["M","When did this issue start?","Vấn đề này bắt đầu từ khi nào?"],["W","A few hours ago. The thermostat was just installed yesterday.","Cách đây vài giờ. Bộ điều chỉnh nhiệt vừa mới được lắp đặt vào ngày hôm qua."],["M","OK. I can come and take a look at it tomorrow morning.","Được rồi. Tôi có thể ghé qua kiểm tra vào sáng mai."],["W","But it's supposed to be below freezing tonight!","Nhưng dự báo đêm nay nhiệt độ sẽ xuống dưới mức đóng băng đấy!"]],"qs":[{"n":53,"q":"Who most likely is the man?","qvi":"Người đàn ông có khả năng cao là ai?","opts":["A delivery driver","A security guard","A maintenance worker","A customer service representative"],"vi":["Một lái xe giao hàng","Một nhân viên bảo vệ","Một nhân viên bảo trì","Một đại diện dịch vụ khách hàng"],"ans":"C"},{"n":54,"q":"What problem does the woman describe?","qvi":"Người phụ nữ mô tả vấn đề gì?","opts":["A device is malfunctioning.","A key is missing.","A parking area is unavailable.","A package was not received."],"vi":["Một thiết bị đang bị hỏng.","Một chiếc chìa khóa bị mất.","Khu vực đỗ xe không có sẵn.","Một gói hàng chưa được nhận."],"ans":"A"},{"n":55,"q":"What does the woman mean when she says, \"it's supposed to be below freezing tonight\"?","qvi":"Người phụ nữ có ý gì khi nói \"trời dự kiến sẽ lạnh dưới mức đóng băng tối nay\"?","opts":["She is surprised by the weather forecast.","She wants a service to be completed sooner.","She will move some items indoors.","She would prefer to park near her apartment."],"vi":["Cô ấy ngạc nhiên về dự báo thời tiết.","Cô ấy muốn một dịch vụ được hoàn thành sớm hơn.","Cô ấy sẽ chuyển một số đồ vật vào trong nhà.","Cô ấy muốn đỗ xe gần căn hộ của mình hơn."],"ans":"B"}],"a":"E26-T01-53-55.mp3"},{"ns":[56,58],"script":[["W","Good morning! Welcome to Jasper Bank.","Chào buổi sáng! Chào mừng hai ông đến với ngân hàng Jasper."],["M1","Thanks for meeting with us to discuss a loan for our business.","Cảm ơn cô đã gặp chúng tôi để thảo luận về khoản vay cho doanh nghiệp của chúng tôi."],["W","Why don't you tell me more about your business? I understand it's a repair shop?","Hai ông có thể cho tôi biết thêm về doanh nghiệp của mình không? Tôi hiểu đó là một cửa hàng sửa chữa?"],["M2","Well, ten years ago, we opened as a snowmobile repair shop, but after a few years, we also started renting out snowmobiles and other sports equipment.","Chà, mười năm trước chúng tôi mở một cửa hàng sửa chữa xe trượt tuyết, nhưng sau vài năm, chúng tôi cũng bắt đầu cho thuê xe trượt tuyết và các thiết bị thể thao khác."],["M1","Yes, and because winter tourism has increased recently, we'd like to expand our space so that we can carry more inventory.","Vâng, và vì du lịch mùa đông tăng lên gần đây, chúng tôi muốn mở rộng không gian để có thể chứa được nhiều hàng tồn kho hơn."]],"qs":[{"n":56,"q":"Why do the men want to speak to the woman?","qvi":"Tại sao những người đàn ông muốn nói chuyện với người phụ nữ?","opts":["To review a building design","To discuss a loan","To develop an advertising plan","To purchase some supplies"],"vi":["Để xem xét một thiết kế tòa nhà","Để thảo luận về một khoản vay","Để phát triển một kế hoạch quảng cáo","Để mua một số vật tư"],"ans":"B"},{"n":57,"q":"What type of business do the men own?","qvi":"Những người đàn ông sở hữu loại hình kinh doanh nào?","opts":["A sports equipment store","A winter apparel store","An automobile dealership","A hotel chain"],"vi":["Cửa hàng thiết bị thể thao","Cửa hàng quần áo mùa đông","Đại lý ô tô","Chuỗi khách sạn"],"ans":"A"},{"n":58,"q":"According to the men, what has changed recently?","qvi":"Theo những người đàn ông, điều gì đã thay đổi gần đây?","opts":["Roads have become more accessible.","Costs have decreased.","Tourism has increased.","Weather patterns have shifted."],"vi":["Đường xá đã trở nên dễ tiếp cận hơn.","Chi phí đã giảm xuống.","Du lịch đã tăng lên.","Các hình thái thời tiết đã thay đổi."],"ans":"C"}],"a":"E26-T01-56-58.mp3"},{"ns":[59,61],"script":[["M","Many of our factory workers have expressed interest in upgrading their skills. I'd like to implement a peer-training program, where learners shadow more-experienced employees and observe how they do their jobs.","Nhiều công nhân nhà máy của chúng ta bày tỏ sự quan tâm đến việc nâng cao kỹ năng. Tôi muốn triển khai chương trình đào tạo chéo, nơi người học sẽ theo sát những nhân viên giàu kinh nghiệm để quan sát cách họ làm việc."],["W","I'm afraid that might become a burden for our long-time employees. They'll have to slow down their work to explain what they're doing.","Tôi e rằng điều đó có thể trở thành gánh nặng cho những nhân viên lâu năm. Họ sẽ phải làm chậm công việc của mình để giải thích những gì họ đang làm."],["M","What if we videotaped experienced employees doing specific tasks? High-quality video can be recorded and edited with a smartphone.","Nếu chúng ta quay video những nhân viên giàu kinh nghiệm thực hiện các nhiệm vụ cụ thể thì sao? Video chất lượng cao có thể được ghi lại và chỉnh sửa bằng điện thoại thông minh."],["W","I like that idea. It would allow us to capture our workers' expertise without slowing down the production line.","Tôi thích ý tưởng đó. Nó cho phép chúng ta ghi lại chuyên môn của công nhân mà không làm chậm dây chuyền sản xuất."]],"qs":[{"n":59,"q":"What does the man want to do?","qvi":"Người đàn ông muốn làm gì?","opts":["Provide training opportunities","Upgrade machinery","Hire additional employees","Reorganize the factory layout"],"vi":["Cung cấp các cơ hội đào tạo","Nâng cấp máy móc","Thuê thêm nhân viên","Tổ chức lại bố cục nhà máy"],"ans":"A"},{"n":60,"q":"What is the woman concerned about?","qvi":"Người phụ nữ lo lắng về điều gì?","opts":["Increasing expenses","Introducing errors","Reducing productivity","Causing confusion"],"vi":["Chi phí gia tăng","Gây ra lỗi","Giảm năng suất","Gây ra sự bối rối"],"ans":"C"},{"n":61,"q":"What does the man mean when he says, \"High-quality video can be recorded and edited with a smartphone\"?","qvi":"Người đàn ông có ý gì khi nói \"Video chất lượng cao có thể được quay và chỉnh sửa bằng điện thoại thông minh\"?","opts":["A new policy should be established.","An idea is easy to implement.","Data security is a concern.","Some information should be verified."],"vi":["Một chính sách mới nên được thiết lập.","Một ý tưởng rất dễ thực hiện.","Bảo mật dữ liệu là một mối lo ngại.","Một số thông tin cần được xác minh."],"ans":"B"}],"a":"E26-T01-59-61.mp3"},{"ns":[62,64],"script":[["W","Hi, Suresh, I'm at the airport waiting for my flight. I want to meet with a potential investor while I'm in Chicago. Her name's Marta Gomez.","Chào Suresh, tôi đang ở sân bay đợi chuyến bay. Tôi muốn gặp một nhà đầu tư tiềm năng trong khi ở Chicago. Tên cô ấy là Marta Gomez."],["M","OK. Which day would you prefer to meet with her?","Được rồi. Cô muốn gặp cô ấy vào ngày nào?"],["W","How about right after my meeting with the Chicago staff?","Ngay sau cuộc họp của tôi với nhân viên ở Chicago thì sao?"],["M","OK. By the way, did you see that our company won an award for our contributions to the community? It was just announced this morning.","Được thôi. Nhân tiện, cô có thấy công ty chúng ta vừa giành được giải thưởng vì những đóng góp cho cộng đồng không? Nó vừa được công bố sáng nay."]],"qs":[{"n":62,"q":"Where is the woman?","qvi":"Người phụ nữ đang ở đâu?","opts":["At a restaurant","At a travel agency","At an airport","At a warehouse"],"vi":["Tại một nhà hàng","Tại một đại lý du lịch","Tại sân bay","Tại một nhà kho"],"ans":"C"},{"n":63,"q":"Look at the graphic. When does the woman prefer to meet with an investor?","qvi":"Nhìn vào hình ảnh. Khi nào người phụ nữ muốn gặp nhà đầu tư?","opts":["On Monday","On Tuesday","On Wednesday","On Thursday"],"vi":["Thứ Hai","Thứ Ba","Thứ Tư","Thứ Năm"],"ans":"C"},{"n":64,"q":"What good news does the man share?","qvi":"Người đàn ông chia sẻ tin tốt nào?","opts":["A colleague received a promotion.","A conference proposal was accepted.","An airline ticket has been upgraded.","A company won an award."],"vi":["Một đồng nghiệp đã được thăng chức.","Đề xuất hội nghị đã được chấp nhận.","Vé máy bay đã được nâng hạng.","Một công ty đã giành được giải thưởng."],"ans":"D"}],"a":"E26-T01-62-64.mp3","img":"g62.png"},{"ns":[65,67],"script":[["M","Marion, we keep getting calls from people who want to visit the botanical garden but can't find parking information. Isn't it on our Web site?","Marion này, chúng ta liên tục nhận được cuộc gọi từ những người muốn tham quan vườn bách thảo nhưng không tìm thấy thông tin bãi đậu xe. Nó không có trên trang web của chúng ta sao?"],["W","It is, but you have to click on the \"About Us\" page and scroll to the bottom of that page. Maybe people don't see it.","Có chứ, nhưng anh phải nhấp vào trang \"Về chúng tôi\" và cuộn xuống cuối trang đó. Có lẽ mọi người không thấy nó."],["M","Oh, I think we should move that information from the \"About Us\" page and make a separate page for directions and parking information.","Ồ, tôi nghĩ chúng ta nên chuyển thông tin đó từ trang \"Về chúng tôi\" và tạo một trang riêng cho chỉ đường và thông tin đậu xe."],["W","I'd be happy to make that change. But we're in the middle of updating our software, so it'll have to wait until Monday.","Tôi rất sẵn lòng thực hiện thay đổi đó. Nhưng chúng ta đang trong quá trình cập nhật phần mềm, vì vậy việc này sẽ phải đợi đến thứ Hai."]],"qs":[{"n":65,"q":"Where do the speakers work?","qvi":"Các diễn giả làm việc ở đâu?","opts":["At an amusement park","At an art museum","At a concert hall","At a botanical garden"],"vi":["Tại một công viên giải trí","Tại một bảo tàng nghệ thuật","Tại một phòng hòa nhạc","Tại một vườn bách thảo"],"ans":"D"},{"n":66,"q":"Look at the graphic. Which page on the Web site does the man want to change?","qvi":"Nhìn vào hình ảnh. Trang nào trên trang web mà người đàn ông muốn thay đổi?","opts":["Page 1","Page 2","Page 3","Page 4"],"vi":["Trang 1","Trang 2","Trang 3","Trang 4"],"ans":"A"},{"n":67,"q":"Why does the woman say she cannot complete a task until Monday?","qvi":"Tại sao người phụ nữ nói cô ấy không thể hoàn thành công việc cho đến thứ Hai?","opts":["She requires approval from a manager.","She is attending a workshop.","Some software is being updated.","Some clients will be arriving soon."],"vi":["Cô ấy cần sự chấp thuận từ quản lý.","Cô ấy đang tham dự một buổi hội thảo.","Một số phần mềm đang được cập nhật.","Một số khách hàng sẽ sớm đến."],"ans":"C"}],"a":"E26-T01-65-67.mp3","img":"g65.png"},{"ns":[68,70],"script":[["M","Good news! We have finally received the go-ahead for our department's project to install bicycle racks at the train station downtown.","Tin tốt đây! Cuối cùng chúng ta đã nhận được sự đồng ý cho dự án của bộ phận mình về việc lắp đặt giá để xe đạp tại ga tàu trung tâm thành phố."],["W","At last! So, now we need to decide where to place the racks. How about by the station entrance?","Cuối cùng cũng được rồi! Vậy bây giờ chúng ta cần quyết định nơi đặt các giá để xe. Ngay cạnh lối vào nhà ga thì sao?"],["M","Hmm. If we asked riders, I bet they'd say that the most convenient spot is as close to the platform as possible.","Hừm. Nếu chúng ta hỏi những người đi xe, tôi cá là họ sẽ nói rằng vị trí thuận tiện nhất là càng gần sân ga càng tốt."],["W","Let's do that. I'll contact some companies for estimates.","Hãy làm như vậy đi. Tôi sẽ liên hệ với một số công ty để lấy báo giá."]],"qs":[{"n":68,"q":"What news does the man share?","qvi":"Người đàn ông chia sẻ tin tức gì?","opts":["A station road will be closed for repair.","A project has been approved.","A parking area has been expanded.","An office will relocate."],"vi":["Một con đường trạm sẽ bị đóng cửa để sửa chữa.","Một dự án đã được phê duyệt.","Một khu vực đỗ xe đã được mở rộng.","Một văn phòng sẽ chuyển địa điểm."],"ans":"B"},{"n":69,"q":"Look at the graphic. Where do the speakers decide to install some bicycle racks?","qvi":"Nhìn vào hình ảnh. Các diễn giả quyết định lắp đặt một số giá để xe đạp ở đâu?","opts":["Near the covered parking area","Near the long-term parking area","Near the short-term parking area","Near the overflow parking area"],"vi":["Gần khu vực đỗ xe có mái che","Gần khu vực đỗ xe dài hạn","Gần khu vực đỗ xe ngắn hạn","Gần khu vực đỗ xe dự phòng"],"ans":"A"},{"n":70,"q":"Why does the woman say she will contact some companies?","qvi":"Tại sao người phụ nữ nói cô ấy sẽ liên lạc với một số công ty?","opts":["To arrange a loan","To apply for a permit","To ask for estimates","To create a proposal"],"vi":["Để sắp xếp một khoản vay","Để nộp đơn xin giấy phép","Để yêu cầu báo giá/ước tính chi phí","Để tạo một bản đề xuất"],"ans":"C"}],"a":"E26-T01-68-70.mp3","img":"g68.png"}],"p4":[{"ns":[71,73],"script":[["","You've reached Select Repair Service. We specialize in all makes and models of automobiles. Our factory-trained specialists will keep your vehicle running in top condition. As an added benefit, we offer extended warranties on all vehicles we service. Please note that Select Repair Service will be closing on Friday, June 30, so we can complete our quarterly inventory of supplies.","Bạn đã gọi đến Dịch vụ Sửa chữa Select. Chúng tôi chuyên về tất cả các hãng và dòng xe ô tô. Các chuyên gia được đào tạo tại nhà máy của chúng tôi sẽ giữ cho xe của bạn hoạt động trong điều kiện tốt nhất. Như một lợi ích bổ sung, chúng tôi cung cấp gói bảo hành mở rộng cho tất cả các xe chúng tôi bảo dưỡng. Xin lưu ý rằng Dịch vụ Sửa chữa Select sẽ đóng cửa vào thứ Sáu, ngày 30 tháng 6, để chúng tôi có thể hoàn thành việc kiểm kê vật tư hàng quý."]],"qs":[{"n":71,"q":"What type of products does the business repair?","qvi":"Doanh nghiệp sửa chữa loại sản phẩm nào?","opts":["Computers","Vehicles","Light fixtures","Kitchen appliances"],"vi":["Máy tính","Xe cộ","Thiết bị chiếu sáng","Thiết bị nhà bếp"],"ans":"B"},{"n":72,"q":"What special benefit does the speaker mention?","qvi":"Người nói đề cập đến lợi ích đặc biệt nào?","opts":["Free pickup","Online scheduling","Extended warranties","A membership loyalty program"],"vi":["Lấy hàng miễn phí","Lên lịch trực tuyến","Gia hạn bảo hành","Chương trình khách hàng thân thiết"],"ans":"C"},{"n":73,"q":"Why will a business close on Friday?","qvi":"Tại sao doanh nghiệp sẽ đóng cửa vào thứ Sáu?","opts":["For an inventory count","For employee training","For a company celebration","For equipment installation"],"vi":["Để kiểm kê hàng hóa","Để đào tạo nhân viên","Để kỷ niệm công ty","Để lắp đặt thiết bị"],"ans":"A"}],"a":"E26-T01-71-73.mp3"},{"ns":[74,76],"script":[["","Welcome, new employees! My name is Diego, and I facilitate all orientation sessions. Before we start today, you will need to set up your employee account. If you look at the first page of your training binder, you'll see your username and a temporary password. Once that's complete, you'll have access to all your department's files. Please note that you can only access them from your company computer.","Chào mừng các nhân viên mới! Tôi tên là Diego, và tôi là người điều phối tất cả các buổi định hướng. Trước khi bắt đầu hôm nay, các bạn sẽ cần thiết lập tài khoản nhân viên của mình. Nếu các bạn nhìn vào trang đầu tiên của bìa hồ sơ đào tạo, các bạn sẽ thấy tên đăng nhập và mật khẩu tạm thời của mình. Sau khi hoàn tất, các bạn sẽ có quyền truy cập vào tất cả các tệp của bộ phận mình. Xin lưu ý rằng các bạn chỉ có thể truy cập chúng từ máy tính của công ty."]],"qs":[{"n":74,"q":"Who most likely is the speaker?","qvi":"Người nói có khả năng cao là ai?","opts":["A facilities manager","A human resources representative","A security officer","A corporate executive"],"vi":["Quản lý cơ sở vật chất","Đại diện nhân sự","Nhân viên an ninh","Giám đốc điều hành"],"ans":"B"},{"n":75,"q":"According to the speaker, what will the listeners find in a binder?","qvi":"Theo người nói, người nghe sẽ tìm thấy gì trong bìa kẹp hồ sơ?","opts":["A map of the building","An employment contract","An identification badge","Log-in credentials"],"vi":["Bản đồ tòa nhà","Hợp đồng lao động","Thẻ nhận dạng","Thông tin đăng nhập"],"ans":"D"},{"n":76,"q":"What does the speaker say about department files?","qvi":"Người nói nói gì về các tập tin của bộ phận?","opts":["They are only accessible from company computers.","They must be password protected.","They must follow a specific naming convention.","They must be archived annually."],"vi":["Chỉ có thể truy cập từ máy tính công ty.","Chúng phải được bảo vệ bằng mật khẩu.","Chúng phải tuân theo một quy ước đặt tên cụ thể.","Chúng phải được lưu trữ hàng năm."],"ans":"A"}],"a":"E26-T01-74-76.mp3"},{"ns":[77,79],"script":[["","Hello. This is Heather Ross calling from Denville Amusement Park. About a month ago, I ordered one of your new video-game machines, Space Defenders. I'm really happy with my purchase, since the game has been incredibly popular with our park guests! I heard you may be releasing a new game soon. Could you call me back and let me know if that's true?","Xin chào. Tôi là Heather Ross gọi từ Công viên Giải trí Denville. Khoảng một tháng trước, tôi đã đặt mua một trong những máy chơi game mới của các bạn, Space Defenders. Tôi thực sự hài lòng với đơn hàng này, vì trò chơi này cực kỳ phổ biến với khách ghé thăm công viên của chúng tôi! Tôi nghe nói các bạn sắp phát hành một trò chơi mới. Bạn có thể gọi lại và cho tôi biết điều đó có đúng không?"]],"qs":[{"n":77,"q":"Where does the speaker work?","qvi":"Người nói làm việc ở đâu?","opts":["At a laundry facility","At an amusement park","At a sports stadium","At a fitness center"],"vi":["Tại một cơ sở giặt ủi","Tại một công viên giải trí","Tại một sân vận động thể thao","Tại một trung tâm thể hình"],"ans":"B"},{"n":78,"q":"What does the speaker say about an item she ordered a month ago?","qvi":"Người nói nói gì về món đồ cô ấy đã đặt một tháng trước?","opts":["It arrived later than expected.","It was damaged during delivery.","She needs help assembling it.","She is pleased with it."],"vi":["Nó đến muộn hơn dự kiến.","Nó bị hỏng trong quá trình vận chuyển.","Cô ấy cần giúp đỡ để lắp ráp nó.","Cô ấy hài lòng với nó."],"ans":"D"},{"n":79,"q":"What does the speaker ask the listener to confirm?","qvi":"Người nói yêu cầu người nghe xác nhận điều gì?","opts":["Whether a new product will be available soon","When a replacement part will be shipped","How long a warranty lasts","Who to contact about future orders"],"vi":["Liệu sản phẩm mới có sớm ra mắt không","Khi nào bộ phận thay thế sẽ được gửi đi","Thời gian bảo hành kéo dài bao lâu","Ai là người liên hệ về các đơn hàng tương lai"],"ans":"A"}],"a":"E26-T01-77-79.mp3"},{"ns":[80,82],"script":[["","The first agenda item for our board meeting is the annual sales report. We're all disappointed by the drop in our clothing sales. So I'm recommending that we start manufacturing some clothing locally. I hired a consultant to put together a list of locations we could use. He'll be at our next board meeting to explain the pros and cons of each.","Mục đầu tiên trong chương trình nghị sự cho cuộc họp hội đồng quản trị của chúng ta là báo cáo doanh số hàng năm. Tất cả chúng ta đều thất vọng vì doanh số bán quần áo sụt giảm. Vì vậy, tôi đề xuất chúng ta bắt đầu sản xuất một số mặt hàng quần áo tại địa phương. Tôi đã thuê một tư vấn viên để lập danh sách các địa điểm chúng ta có thể sử dụng. Anh ấy sẽ có mặt trong cuộc họp tiếp theo để giải thích ưu và nhược điểm của từng nơi."]],"qs":[{"n":80,"q":"What type of product does the speaker's company make?","qvi":"Công ty của người nói sản xuất loại sản phẩm nào?","opts":["Furniture","Luggage","Bedding","Clothing"],"vi":["Nội thất","Hành lý/Van li","Đồ dùng phòng ngủ (chăn ga gối nệm)","Quần áo"],"ans":"D"},{"n":81,"q":"What does the speaker recommend doing?","qvi":"Người nói đề xuất làm điều gì?","opts":["Manufacturing some products locally","Offering free shipping","Participating in a trade show","Developing a new product line"],"vi":["Sản xuất một số sản phẩm tại địa phương","Cung cấp dịch vụ giao hàng miễn phí","Tham gia một hội chợ triển lãm thương mại","Phát triển một dòng sản phẩm mới"],"ans":"A"},{"n":82,"q":"What will happen at the next meeting?","qvi":"Điều gì sẽ xảy ra tại cuộc họp tiếp theo?","opts":["A vote will take place.","A consultant will give a presentation.","Some contracts will be updated.","Safety procedures will be reviewed."],"vi":["Một cuộc bỏ phiếu sẽ diễn ra.","Một cố vấn sẽ trình bày.","Một số hợp đồng sẽ được cập nhật.","Các quy trình an toàn sẽ được xem xét lại."],"ans":"B"}],"a":"E26-T01-80-82.mp3"},{"ns":[83,85],"script":[["","Attention, passengers. All trains to Midway Station are delayed for track repairs. They expect to complete the repair within the hour. A bus will be departing for that destination in fifteen minutes. Also, a reminder that the station café opens at eight A.M., and there are food kiosks on platform one.","Xin hành khách chú ý. Tất cả các đoàn tàu đến ga Midway đều bị hoãn để sửa chữa đường ray. Họ dự kiến sẽ hoàn thành việc sửa chữa trong vòng một giờ tới. Một chiếc xe buýt sẽ khởi hành đến điểm đến đó trong 15 phút nữa. Ngoài ra, xin nhắc lại rằng quán cà phê tại nhà ga mở cửa lúc 8 giờ sáng, và có các quầy thực phẩm tại sân ga số 1."]],"qs":[{"n":83,"q":"What is the announcement mainly about?","qvi":"Thông báo chủ yếu nói về điều gì?","opts":["A promotional event","A vacation package","A building renovation","A travel delay"],"vi":["Một sự kiện quảng cáo","Một gói kỳ nghỉ","Một cuộc cải tạo tòa nhà","Một sự trì hoãn chuyến đi"],"ans":"D"},{"n":84,"q":"Why does the speaker say, \"A bus will be departing for that destination in fifteen minutes\"?","qvi":"Tại sao người nói lại nói \"Một chiếc xe buýt sẽ khởi hành đến điểm đến đó trong 15 phút nữa\"?","opts":["To suggest an alternative arrangement","To explain an extended wait time","To recommend changing the travel date","To inform customers about a new destination"],"vi":["Để gợi ý một sự sắp xếp thay thế","Để giải thích thời gian chờ kéo dài","Để khuyên nên thay đổi ngày đi","Để thông báo cho khách hàng về điểm đến mới"],"ans":"A"},{"n":85,"q":"What does the speaker remind the listeners about?","qvi":"Người nói nhắc nhở người nghe về điều gì?","opts":["How to download a mobile application","Where a waiting area is located","How to reserve tickets","Where to buy food"],"vi":["Cách tải xuống một ứng dụng di động","Nơi đặt khu vực chờ","Cách đặt vé","Nơi mua thức ăn"],"ans":"D"}],"a":"E26-T01-83-85.mp3"},{"ns":[86,88],"script":[["","I'm calling about the work my design team's doing to update your company logo. I've just e-mailed two versions for you to review. Take your time to think about which one you'd like to choose. I'll be on vacation all next week, but if you call the office, my assistant will set up a meeting for when I get back.","Tôi gọi điện về công việc mà nhóm thiết kế của tôi đang thực hiện để cập nhật logo công ty bạn. Tôi vừa gửi email hai phiên bản để bạn xem xét. Hãy dành thời gian để suy nghĩ xem bạn muốn chọn cái nào. Tôi sẽ đi nghỉ suốt tuần tới, nhưng nếu bạn gọi đến văn phòng, trợ lý của tôi sẽ sắp xếp một cuộc họp khi tôi quay lại."]],"qs":[{"n":86,"q":"Where does the speaker most likely work?","qvi":"Người nói có khả năng cao là làm việc ở đâu?","opts":["At a graphic design company","At a law firm","At a photography studio","At a museum"],"vi":["Tại một công ty thiết kế đồ họa","Tại một văn phòng luật","Tại một studio chụp ảnh","Tại một bảo tàng"],"ans":"A"},{"n":87,"q":"What did the listener receive by e-mail?","qvi":"Người nghe đã nhận được gì qua email?","opts":["A newsletter","Some images","An invoice","Some contracts"],"vi":["Một bản tin","Một số hình ảnh","Một hóa đơn","Một số hợp đồng"],"ans":"B"},{"n":88,"q":"Why is the speaker unavailable next week?","qvi":"Tại sao người nói không có mặt vào tuần tới?","opts":["She will be working at another branch.","She will be with other clients.","She will be on vacation.","She will be at an industry conference."],"vi":["Cô ấy sẽ làm việc tại một chi nhánh khác.","Cô ấy sẽ bận với những khách hàng khác.","Cô ấy sẽ đi nghỉ mát.","Cô ấy sẽ tham dự một hội nghị ngành."],"ans":"C"}],"a":"E26-T01-86-88.mp3"},{"ns":[89,91],"script":[["","I've scheduled this press conference to officially respond to your inquiries regarding fuel-efficient engines. We hired a firm to determine if this upgrade would be feasible for our trains. It reported that the upgrade would be economical only for trains less than five years old. All of ours are at least ten years old. If you're interested in more details, e-mail our media relations department to receive a summary of the findings.","Tôi đã lên lịch cuộc họp báo này để phản hồi chính thức các thắc mắc của các bạn về động cơ tiết kiệm nhiên liệu. Chúng tôi đã thuê một công ty để xác định xem việc nâng cấp này có khả thi cho các đoàn tàu của chúng tôi không. Họ báo cáo rằng việc nâng cấp chỉ tiết kiệm cho các tàu có tuổi đời dưới 5 năm. Tất cả tàu của chúng tôi đều ít nhất 10 năm tuổi. Nếu bạn quan tâm đến chi tiết hơn, hãy gửi email cho bộ phận quan hệ truyền thông để nhận bản tóm tắt kết quả."]],"qs":[{"n":89,"q":"Who most likely are the listeners?","qvi":"Người nghe có khả năng cao là ai?","opts":["Investors","Government officials","Engineers","Journalists"],"vi":["Các nhà đầu tư","Các quan chức chính phủ","Các kỹ sư","Các nhà báo"],"ans":"D"},{"n":90,"q":"What does the speaker mean when she says, \"All of ours are at least ten years old\"?","qvi":"Người nói có ý gì khi nói \"Tất cả của chúng tôi đều ít nhất mười năm tuổi\"?","opts":["An event needs to be relocated.","An upgrade is not feasible.","A project team has a lot of experience.","Some company policies are outdated."],"vi":["Một sự kiện cần được chuyển địa điểm.","Việc nâng cấp là không khả thi.","Nhóm dự án có rất nhiều kinh nghiệm.","Một số chính sách của công ty đã lỗi thời."],"ans":"B"},{"n":91,"q":"According to the speaker, what can be requested by e-mail?","qvi":"Theo người nói, cái gì có thể được yêu cầu qua email?","opts":["Some presentation slides","Some product samples","A report summary","A discounted ticket"],"vi":["Một số trang thuyết trình","Một số mẫu sản phẩm","Bản tóm tắt báo cáo","Vé giảm giá"],"ans":"C"}],"a":"E26-T01-89-91.mp3"},{"ns":[92,94],"script":[["","I want to explore the use of a more modernized payment system in our cosmetics stores. This system would allow any sales associate to take customer payments from a tablet anywhere in the store. The main complaint about shopping at our stores is waiting in long lines to pay. I've decided to conduct a trial run at our store in the Center City Mall. That's our busiest location.","Tôi muốn tìm hiểu việc sử dụng hệ thống thanh toán hiện đại hơn trong các cửa hàng mỹ phẩm của chúng ta. Hệ thống này cho phép bất kỳ nhân viên bán hàng nào cũng có thể nhận thanh toán của khách từ máy tính bảng ở bất kỳ đâu trong cửa hàng. Lời phàn nàn chính về việc mua sắm tại cửa hàng là việc phải chờ đợi trong dòng người dài để thanh toán. Tôi đã quyết định thực hiện một đợt chạy thử tại cửa hàng ở Trung tâm thương mại Center City. Đó là địa điểm bận rộn nhất của chúng ta."]],"qs":[{"n":92,"q":"What does the speaker want to do?","qvi":"Người nói muốn làm gì?","opts":["Increase online sales","Upgrade a payment system","Create a new product line","Add store locations"],"vi":["Tăng doanh số bán hàng trực tuyến","Nâng cấp hệ thống thanh toán","Tạo ra một dòng sản phẩm mới","Thêm các địa điểm cửa hàng"],"ans":"B"},{"n":93,"q":"According to the speaker, what is the customers' main complaint?","qvi":"Theo người nói, lời phàn nàn chính của khách hàng là gì?","opts":["Long lines","High prices","Unavailable items","Unfriendly staff"],"vi":["Xếp hàng dài","Giá cao","Các món đồ không có sẵn","Nhân viên không thân thiện"],"ans":"A"},{"n":94,"q":"Why does the speaker say, \"that's our busiest location\"?","qvi":"Tại sao người nói lại nói \"đó là địa điểm bận rộn nhất của chúng tôi\"?","opts":["To request some feedback","To compliment some staff","To express frustration","To justify a choice"],"vi":["Để yêu cầu một số phản hồi","Để khen ngợi một số nhân viên","Để bày tỏ sự thất vọng","Để giải thích cho một sự lựa chọn"],"ans":"D"}],"a":"E26-T01-92-94.mp3"},{"ns":[95,97],"script":[["","The downtown Reston Office Tower is completed. The most extraordinary feature of the building is its beautiful garden, located in the lobby. We interviewed the CEO of Barnum Financial Services about its new offices. He said he and his team are excited to move in in January. A recording of the full interview is available on our Web site.","Tòa tháp văn phòng Reston ở trung tâm thành phố đã hoàn thành. Đặc điểm phi thường nhất của tòa nhà là khu vườn tuyệt đẹp nằm ở sảnh đợi. Chúng tôi đã phỏng vấn Giám đốc điều hành của Barnum Financial Services về các văn phòng mới của họ. Ông ấy nói ông và nhóm của mình rất hào hứng khi chuyển đến vào tháng Giêng. Bản ghi âm buổi phỏng vấn đầy đủ hiện có trên trang web của chúng tôi."]],"qs":[{"n":95,"q":"According to the speaker, what is special about the Reston Office Tower?","qvi":"Theo người nói, Tháp Văn phòng Reston có điểm gì đặc biệt?","opts":["It features an indoor garden.","It exhibits work from local artists.","It runs on solar power.","It has won many awards."],"vi":["Nó có một khu vườn trong nhà.","Nó trưng bày tác phẩm từ các nghệ sĩ địa phương.","Nó chạy bằng năng lượng mặt trời.","Nó đã giành được nhiều giải thưởng."],"ans":"A"},{"n":96,"q":"Look at the graphic. Which floors will be occupied in January?","qvi":"Nhìn vào đồ họa. Những tầng nào sẽ được sử dụng vào tháng Giêng?","opts":["Floors 1–5","Floors 6–10","Floors 11–14","Floors 15–17"],"vi":["Tầng 1-5","Tầng 6-10","Tầng 11-14","Tầng 15-17"],"ans":"C"},{"n":97,"q":"What does the speaker say is available on a Web site?","qvi":"Người nói nói rằng cái gì có sẵn trên một trang web?","opts":["Some photographs","An event schedule","A floor layout","A recorded interview"],"vi":["Một số bức ảnh","Lịch trình sự kiện","Sơ đồ mặt bằng tầng","Một cuộc phỏng vấn được ghi âm"],"ans":"D"}],"a":"E26-T01-95-97.mp3","img":"g95.png"},{"ns":[98,100],"script":[["","Thank you for attending this meeting for prospective investors. ZZ Mining has been planning to expand our operations by opening an additional silver mine. The site with 390 grams per ton has a larger deposit, so that's where we'll build the new mine. Our next step is to apply for the necessary permits. We'll do that next week.","Cảm ơn các bạn đã tham dự cuộc họp này dành cho các nhà đầu tư tiềm năng. ZZ Mining đã lên kế hoạch mở rộng hoạt động bằng cách mở thêm một mỏ bạc. Địa điểm có 390 gram bạc mỗi tấn có trữ lượng lớn hơn, vì vậy đó là nơi chúng tôi sẽ xây dựng mỏ mới. Bước tiếp theo của chúng tôi là xin các giấy phép cần thiết. Chúng tôi sẽ thực hiện việc đó vào tuần tới."]],"qs":[{"n":98,"q":"Who most likely are the listeners?","qvi":"Người nghe có khả năng cao là ai?","opts":["Safety engineers","Laboratory technicians","Legal consultants","Business investors"],"vi":["Các kỹ sư an toàn","Các kỹ thuật viên phòng thí nghiệm","Các tư vấn pháp lý","Các nhà đầu tư kinh doanh"],"ans":"D"},{"n":99,"q":"Look at the graphic. Where will a new mine be built?","qvi":"Nhìn vào đồ họa. Một mỏ mới sẽ được xây dựng ở đâu?","opts":["At site 1","At site 2","At site 3","At site 4"],"vi":["Tại vị trí 1","Tại vị trí 2","Tại vị trí 3","Tại vị trí 4"],"ans":"C"},{"n":100,"q":"What does the speaker say is the next step?","qvi":"Người nói nói bước tiếp theo là gì?","opts":["Applying for permits","Installing equipment","Hiring additional staff","Updating a manual"],"vi":["Đệ đơn xin giấy phép","Lắp đặt thiết bị","Thuê thêm nhân viên","Cập nhật một bản hướng dẫn"],"ans":"A"}],"a":"E26-T01-98-100.mp3","img":"g98.png"}]},"rc":{"p5":[{"n":101,"q":"The lecture will take place at 6:00 P.M., ------- which attendees may ask questions.","opts":["across","after","inside","among"],"ans":"B","xp":"Ta thấy Dấu phẩy + which → đây là mệnh đề quan hệ không xác định. Phía trước có 6 PM là thời gian nên cần giới từ chỉ thời gian, KHÔNG phải giới từ vị trí.\n=> Chọn (B). Cụm \"after which\" là một cấu trúc mệnh đề quan hệ trạng từ, có nghĩa là \"sau thời điểm đó/sau sự kiện đó\".\nDịch: Bài giảng sẽ diễn ra vào lúc 6 giờ tối, sau đó người tham dự có thể đặt câu hỏi."},{"n":102,"q":"The ------- antique shop in Pepper Valley will close down next month.","opts":["last","lasts","lasted","lasting"],"ans":"A","xp":"Chọn (A).\n(A) last (Tính từ): cuối cùng / duy nhất còn lại.\n(B) lasts (Động từ chia số ít): kéo dài.\n(C) lasted (Động từ quá khứ): đã kéo dài.\n(D) lasting (Tính từ): bền vững, lâu dài.\nChỗ trống nằm giữa mạo từ \"The\" và cụm danh từ \"antique shop\". Vị trí này chỉ có thể điền một Tính từ để bổ nghĩa cho danh từ phía sau. \"The last antique shop\" có nghĩa là \"Cửa hàng đồ cổ cuối cùng/duy nhất còn lại\", rất phù hợp với ngữ cảnh là nó sắp đóng cửa (\"close down\").\nDịch: Cửa hàng đồ cổ cuối cùng ở Thung lũng Pepper sẽ đóng cửa vào tháng tới."},{"n":103,"q":"Merryville residents will receive an online status ------- about the ongoing bridge construction project.","opts":["update","change","payment","request"],"ans":"A","xp":"Chọn (A). Câu hỏi về từ vựng.\n(A) update (n) bản cập nhật\n(B) change (n) sự thay đổi\n(C) payment (n) thanh toán\n(D) request (n) yêu cầu\n\"status\" thường đi với update. Cụm từ \"status update\" (cập nhật trạng thái/tình hình) là một \"collocation\" phổ biến trong môi trường làm việc và đề TOEIC.\nDịch: Người dân Merryville sẽ nhận được bản cập nhật trực tuyến về tình trạng dự án xây dựng cầu đang diễn ra."},{"n":104,"q":"As a result of ------- many years leading media organizations, Ms. Ayo was selected for the Dowel Journalism Prize.","opts":["she","her","hers","herself"],"ans":"B","xp":"Chọn (B).\n(A) she (Đại từ nhân xưng): cô ấy (làm chủ ngữ).\n(B) her (Tính từ sở hữu/Tân ngữ): của cô ấy/cô ấy.\n(C) hers (Đại từ sở hữu): cái của cô ấy.\n(D) herself (Đại từ phản thân): chính cô ấy.\nĐằng sau chỗ trống là một cụm danh từ bắt đầu bằng V-ing (many years leading media organizations) => Chúng ta cần một tính từ sở hữu để bổ nghĩa cho danh từ đó.\nUseful Structures: As a result of + N/V-ing\nDịch: Kết quả của nhiều năm dẫn dắt các tổ chức truyền thông, bà Ayo đã được chọn cho Giải thưởng Báo chí Dowel."},{"n":105,"q":"To stop the ------- of computer viruses, do not open suspicious e-mails.","opts":["break","spread","balance","surface"],"ans":"B","xp":"Chọn (B).\n(A) break (Danh từ): sự gãy vỡ, giờ nghỉ.\n(B) spread (Danh từ): sự lan truyền, sự phổ biến.\n(C) balance (Danh từ/Động từ): sự cân bằng, số dư tài khoản.\n(D) surface (Danh từ): bề mặt.\nDanh từ \"spread\" thường đi với virus, tin tức hoặc dịch bệnh.\nUseful Structures: the spread of + N (thường gặp trong các bài thông báo về an ninh mạng hoặc y tế)\nDịch: Để ngăn chặn sự lây lan của virus máy tính, đừng mở các email đáng ngờ."},{"n":106,"q":"The hiring manager ------- considered each applicant's résumé and qualifications.","opts":["caring","careful","carefully","carefulness"],"ans":"C","xp":"Chọn (C).\n(A) caring (Tính từ/Danh động từ): chu đáo, sự quan tâm.\n(B) careful (Tính từ): cẩn thận (bổ nghĩa cho danh từ).\n(C) carefully (Trạng từ): một cách cẩn thận.\n(D) carefulness (Danh từ): sự cẩn thận.\nChọn trạng từ cho chỗ trống để bổ nghĩa cho động từ \"considered\" (xem xét). (A), (B) tính từ không bổ nghĩa cho động từ thường; (D) danh từ không phù hợp cấu trúc.\nUseful Structures: consider + n/ Ving: cân nhắc/ xem xét cái gì, làm gì.\nDịch: Quản lý tuyển dụng đã xem xét hồ sơ và năng lực của từng ứng viên một cách cẩn thận."},{"n":107,"q":"In October, Mr. Sakamoto will leave for New Zealand ------- will oversee the opening of the new Auckland branch.","opts":["because","in addition","and","prior to"],"ans":"C","xp":"Chọn (C).\nCâu này có hai mệnh đề: (1) Mr. Sakamoto sẽ đi NZ và (2) [ông ấy] sẽ giám sát... Vì chủ ngữ \"Mr. Sakamoto\" được lược bỏ ở vế sau, ta dùng and để nối hai hành động của cùng một chủ ngữ.\n(A) because (Liên từ): bởi vì (theo sau là một mệnh đề S+V).\n(B) in addition (Trạng từ liên kết): ngoài ra (thường đứng đầu câu, có dấu phẩy).\n(C) and (Liên từ): và.\n(D) prior to (Giới từ): trước khi (theo sau là Danh từ/V-ing).\nUseful Structures: because / in addition là bẫy thói quen của TOEIC.\nDịch: Vào tháng 10, ông Sakamoto sẽ đến New Zealand và sẽ giám sát việc khai trương chi nhánh mới tại Auckland."},{"n":108,"q":"Tarateer Pharmaceuticals is varying its product ------- to include over-the-counter medications.","opts":["to line","lining","lined","line"],"ans":"D","xp":"Chọn (D).\nCụm danh từ ghép \"product line\" (dòng sản phẩm) là từ vựng cực kỳ \"kinh điển\" trong TOEIC.\n(A) to line (Động từ nguyên mẫu có 'to'): để xếp hàng.\n(B) lining (Danh từ/V-ing): lớp vải lót, việc lót.\n(C) lined (Tính từ/V-ed): có kẻ hàng, được lót.\n(D) line (Danh từ): dòng, hàng.\nUseful phrases: product line: dòng sản phẩm; over-the-counter (OTC) medications: thuốc không kê đơn\nDịch: Dược phẩm Tarateer Pharmaceuticals đang đa dạng hóa dòng sản phẩm để bao gồm cả thuốc không kê đơn."},{"n":109,"q":"Dynart, Inc., continuously ------- new ways to reduce its use of plastics.","opts":["seeks","seeker","to seek","seeking"],"ans":"A","xp":"Chọn (A).\n(A) seeks (Động từ chia số ít): tìm kiếm.\n(B) seeker (Danh từ): người tìm kiếm.\n(C) to seek (Động từ nguyên mẫu có 'to'): để tìm kiếm.\n(D) seeking (Phân từ/Danh động từ): đang tìm kiếm/việc tìm kiếm.\nCâu đã có chủ ngữ (Dynart, Inc.) và trạng từ (continuously), đang thiếu một động từ chính được chia thì (Finite Verb). Vì chủ ngữ số ít, ta chọn \"seeks\".\nDịch: Tập đoàn Dynart liên tục tìm kiếm những cách mới để giảm thiểu việc sử dụng nhựa của mình."},{"n":110,"q":"The cash registers at Pirkle Books automatically ------- the remaining inventory of books available.","opts":["calculate","calculator","calculating","calculation"],"ans":"A","xp":"Chọn (A).\n(A) calculate (Động từ nguyên thể): tính toán.\n(B) calculator (Danh từ): máy tính cầm tay (dụng cụ).\n(C) calculating (Phân từ/Danh động từ): đang tính toán/việc tính toán.\n(D) calculation (Danh từ): sự tính toán/phép tính.\nChủ ngữ là \"The cash registers\" (số nhiều). Trạng từ \"automatically\" bổ nghĩa cho động từ chính. Ta cần một động từ nguyên thể phù hợp với chủ ngữ số nhiều.\nUseful phrases: Inventory (hàng tồn kho) thường đi với các động từ: calculate, monitor, track, take.\nDịch: Các máy tính tiền tại Pirkle Books tự động tính toán lượng sách tồn kho còn lại hiện có."},{"n":111,"q":"The product team is designing mapping software that can ------- locate underground minerals.","opts":["infinitely","sincerely","precisely","greatly"],"ans":"C","xp":"Chọn (C).\n(A) infinitely (adv): vô tận, không giới hạn.\n(B) sincerely (adv): một cách chân thành (thường dùng kết thư).\n(C) precisely (adv): một cách chính xác.\n(D) greatly (adv): rất nhiều, tuyệt vời.\nCần tìm 1 trạng từ, và trạng từ này bổ nghĩa cho động từ \"locate\" (xác định vị trí). Trong kỹ thuật và phần mềm (\"software\"), việc xác định vị trí khoáng sản cần sự \"chính xác\".\nUseful phrases: \"precisely locate/identify\" (xác định vị trí/danh tính một cách chính xác)\nDịch: Nhóm sản phẩm đang thiết kế phần mềm lập bản đồ có thể xác định vị trí các khoáng sản dưới lòng đất một cách chính xác."},{"n":112,"q":"According to CEO Mayu Yamada, it would not be ------- responsible to expand the warehouse at this time.","opts":["finance","financials","financially","financing"],"ans":"C","xp":"Chọn (C).\n(A) finance (n/v): tài chính/cấp vốn.\n(B) financials (n): báo cáo tài chính.\n(C) financially (adv): về mặt tài chính.\n(D) financing (n/v-ing): sự cấp vốn/việc cấp vốn.\nChỗ trống đứng trước tính từ \"responsible\" (có trách nhiệm). Theo quy tắc: Adv + Adj. Ta chọn 1 Trạng từ bổ nghĩa cho tính từ để chỉ rõ trách nhiệm về phương diện nào.\nUseful phrases: \"financially + tính từ\" (financially sound, financially stable, financially responsible)\nDịch: Theo CEO Mayu Yamada, việc mở rộng kho hàng vào thời điểm này sẽ không có trách nhiệm về mặt tài chính (không khôn ngoan về mặt tiền bạc)."},{"n":113,"q":"Analysts cannot say with any ------- what the regional demand for electric trucks will be.","opts":["certainty","justice","excellence","denial"],"ans":"A","xp":"Chọn (A).\n(A) certainty (n): sự chắc chắn.\n(B) justice (n): sự công bằng, tư pháp.\n(C) excellence (n): sự xuất sắc.\n(D) denial (n): sự phủ nhận.\nCụm từ \"with certainty\" (một cách chắc chắn) là một cụm cố định. Kết hợp với \"cannot say\", câu này diễn tả việc các nhà phân tích không dám khẳng định chắc chắn về nhu cầu thị trường.\nDịch: Các nhà phân tích không thể khẳng định chắc chắn nhu cầu của khu vực đối với xe tải điện sẽ là bao nhiêu."},{"n":114,"q":"As part of its marketing campaign, Elegancia Dishware is ------- soliciting feedback from customers.","opts":["lightly","loyally","actively","cleanly"],"ans":"C","xp":"Chọn (C).\n(A) lightly (adv): nhẹ nhàng, sơ sài.\n(B) loyally (adv): một cách trung thành.\n(C) actively (adv): một cách chủ động/tích cực.\n(D) cleanly (adv): một cách sạch sẽ.\nĐộng từ \"solicit\" nghĩa là khẩn khoản, nài ép hoặc thu thập (ý kiến/vốn). Trong marketing, người ta thường \"chủ động thu thập\" (actively solicit) phản hồi khách hàng.\nUseful phrases: \"Actively\" thường đi với các động từ hành động như: seek, recruit, solicit, participate.\nDịch: Như một phần của chiến dịch tiếp thị, Elegancia Dishware đang chủ động thu thập phản hồi từ khách hàng."},{"n":115,"q":"Rain gardens are intended to ------- water to prevent flooding of local roads.","opts":["engage","undergo","absorb","overwhelm"],"ans":"C","xp":"Chọn (C).\n(A) engage (v): thuê, thu hút, tham gia.\n(B) undergo (v): trải qua (kiểm tra/phẫu thuật).\n(C) absorb (v): hấp thụ, hút (nước/kiến thức).\n(D) overwhelm (v): áp đảo, lấn át.\nDựa vào ngữ cảnh \"vườn mưa\" (rain gardens) và \"ngăn chặn ngập lụt\" (prevent flooding), động từ phù hợp nhất với tân ngữ \"water\" là \"hấp thụ/hút nước\" absorb.\nDịch: Các vườn mưa được thiết kế để hấp thụ nước nhằm ngăn chặn tình trạng ngập lụt các tuyến đường địa phương."},{"n":116,"q":"Theta Industries' training program aims to increase the ------- of its manufacturing systems.","opts":["producer","produced","productive","productivity"],"ans":"D","xp":"Chọn (D).\n(A) producer (n - chỉ người): nhà sản xuất.\n(B) produced (v-ed): đã sản xuất.\n(C) productive (adj): có năng suất.\n(D) productivity (n - chỉ sự vật): năng suất, hiệu suất.\nSau mạo từ \"the\" và trước giới từ \"of\" phải là một danh từ. Xét về nghĩa, tăng cường \"năng suất\" của hệ thống sản xuất là hợp lý nhất. (A) là người sản xuất, không thể là năng suất của hệ thống; (C) là tính từ; (B) là động từ.\nDịch: Chương trình đào tạo của Theta Industries nhằm mục đích tăng năng suất của các hệ thống sản xuất của mình."},{"n":117,"q":"The board of directors has voted to award Mr. Mitrakos a bonus for his role ------- obtaining the international contract.","opts":["in","at","except","apart"],"ans":"A","xp":"Chọn (A).\n(A) in (prep): trong.\n(B) at (prep): tại.\n(C) except (prep): ngoại trừ.\n(D) apart (adv): tách biệt.\nCấu trúc: \"one's role in doing something\" (vai trò của ai đó trong việc làm gì). Đây là cách dùng giới từ cố định sau danh từ \"role\".\nUseful phrases: Bonus for (tiền thưởng cho cái gì); Role in (vai trò trong việc gì)\nDịch: Ban giám đốc đã bỏ phiếu thưởng cho ông Mitrakos vì vai trò của ông trong việc giành được hợp đồng quốc tế."},{"n":118,"q":"The finance director gave his approval ------- the project can move forward.","opts":["along","furthermore","cautiously","so that"],"ans":"D","xp":"Chọn (D).\n(A) along (prep): dọc theo.\n(B) furthermore (adv): hơn nữa (dùng nối câu, sau có dấu phẩy).\n(C) cautiously (adv): một cách thận trọng.\n(D) so that (conj): để cho, nhằm mục đích.\nPhía sau chỗ trống là một mệnh đề hoàn chỉnh (S + V). \"So that\" đóng vai trò liên từ chỉ mục đích. Giám đốc phê duyệt \"để\" dự án có thể tiến triển.\nUseful phrases: \"Move forward\" (tiến triển/tiến về phía trước)\nDịch: Giám đốc tài chính đã đưa ra sự chấp thuận để dự án có thể tiếp tục triển khai."},{"n":119,"q":"The newspaper article describes ways job seekers can ------- for having little workplace experience.","opts":["reply","capture","compensate","accumulate"],"ans":"C","xp":"Chọn (C).\n(A) reply (v): phản hồi (thường đi với 'to').\n(B) capture (v): bắt giữ, chiếm lĩnh.\n(C) compensate (v): đền bù, bù đắp.\n(D) accumulate (v): tích lũy (kinh nghiệm/tiền bạc).\nĐộng từ compensate đi với giới từ for. Cấu trúc: \"compensate for something\" (bù đắp cho cái gì đó). Người tìm việc bù đắp cho việc thiếu kinh nghiệm bằng những cách thức khác. Câu D: mặc dù \"accumulate\" đi với experience nhưng ở đây experience là tân ngữ của \"having\", không phải tân ngữ của động từ chính.\nDịch: Bài báo mô tả những cách mà người tìm việc có thể bù đắp cho việc có ít kinh nghiệm làm việc."},{"n":120,"q":"Mr. Ellis and Ms. Barnes were both highly qualified, but ------- got the job.","opts":["myself","neither","anybody","whoever"],"ans":"B","xp":"Chọn (B).\n(A) myself (Đại từ phản thân): chính tôi.\n(B) neither (Đại từ): không ai trong cả hai.\n(C) anybody (Đại từ bất định): bất cứ ai (thường dùng trong câu phủ định/nghi vấn).\n(D) whoever (Đại từ quan hệ): bất cứ ai người mà.\nLiên từ \"but\" nối hai sự đối lập. Mặc dù cả hai (both) đều đủ năng lực, nhưng \"không ai\" trong số họ nhận được công việc. \"Neither\" dùng cho 2 đối tượng.\nUseful phrases: Phân biệt \"Neither\" (không ai trong 2), \"None\" (không ai trong 3 trở lên) và \"Either\" (1 trong 2)\nDịch: Ông Ellis và bà Barnes đều rất có năng lực, nhưng không ai trong hai người nhận được công việc."},{"n":121,"q":"Ennis Photography purchased all new lighting equipment ------- the high cost.","opts":["even though","however","until","despite"],"ans":"D","xp":"Chọn (D) despite.\n(A) even though (Liên từ): Mặc dù (+ Mệnh đề S+V).\n(B) however (Trạng từ liên kết): Tuy nhiên (Thường đứng đầu câu hoặc giữa 2 dấu phẩy).\n(C) until (Giới từ/Liên từ): Cho đến khi.\n(D) despite (Giới từ): Mặc dù (+ Cụm danh từ/V-ing).\nSau chỗ trống là \"the high cost\" (cụm danh từ). Even though (+ mệnh đề) và Despite (+ cụm danh từ) đều nghĩa là \"mặc dù\". Do đó chỉ có despite là đúng ngữ pháp.\nUseful phrases: Purchase equipment (Mua sắm thiết bị)\nDịch: Ennis Photography đã mua toàn bộ thiết bị chiếu sáng mới mặc dù chi phí cao."},{"n":122,"q":"Marburton residents who wish to ------- a home should contact the award-winning team at Kwan Real Estate.","opts":["seller","sold","sell","selling"],"ans":"C","xp":"Chọn (C) sell.\n(A) seller (Danh từ): Người bán.\n(B) sold (Động từ V2/V3): Đã bán.\n(C) sell (Động từ nguyên mẫu): Bán.\n(D) selling (V-ing): Việc bán/đang bán.\nCấu trúc \"wish to + V-bare\" (muốn làm gì). Sau \"to\" là một động từ nguyên mẫu để đóng vai trò hành động chính trong mệnh đề quan hệ.\nUseful phrases: Award-winning team (Đội ngũ từng đạt giải thưởng); Real Estate (Bất động sản)\nDịch: Cư dân Marburton, những người muốn bán nhà, nên liên hệ với đội ngũ chuyên nghiệp tại Bất động sản Kwan."},{"n":123,"q":"Maswa Bistro began a ------- agreement with local farmers to purchase a set amount of produce each week.","opts":["disruptive","cooperative","grateful","concerned"],"ans":"B","xp":"Chọn (B) cooperative.\n(A) disruptive (Tính từ): Gây gián đoạn, phiền phức.\n(B) cooperative (Tính từ): Có tính hợp tác.\n(C) grateful (Tính từ): Biết ơn.\n(D) concerned (Tính từ): Lo lắng, quan tâm.\nĐây là câu hỏi từ vựng. Chỗ trống bổ nghĩa cho danh từ \"agreement\" (thỏa thuận). Việc nhà hàng mua nông sản từ nông dân là một hành động hợp tác. Cụm \"cooperative agreement\" (thỏa thuận hợp tác) là một thuật ngữ phổ biến trong kinh doanh.\nUseful phrases: A set amount of produce (Một lượng nông sản cố định). Lưu ý: \"Produce\" ở đây là danh từ không đếm được nghĩa là nông sản, không phải động từ \"sản xuất\".\nDịch: Maswa Bistro đã bắt đầu một thỏa thuận hợp tác với các nông dân địa phương để mua một lượng nông sản cố định mỗi tuần."},{"n":124,"q":"The City of Doyle's new downtown parking ------- have been met with opposition by residents and visitors.","opts":["restricts","restricted","restrictions","restricting"],"ans":"C","xp":"Chọn (C) restrictions.\n(A) restricts (Động từ số ít): Hạn chế.\n(B) restricted (V-ed/Tính từ): Bị hạn chế.\n(C) restrictions (Danh từ số nhiều): Sự hạn chế/quy định hạn chế.\n(D) restricting (V-ing): Việc hạn chế.\nChỗ trống đóng vai trò là Chủ ngữ chính của câu, Động từ chính của câu là \"have been\" (số nhiều). Vì vậy, chủ ngữ của câu phải là một danh từ số nhiều -> restrictions.\nUseful phrases: Meet with opposition (Vấp phải sự phản đối)\nDịch: Những quy định hạn chế đậu xe mới ở trung tâm thành phố Doyle đã vấp phải sự phản đối của cư dân và du khách."},{"n":125,"q":"The plumbing position requires extensive training, even for those who studied ------- in technical school.","opts":["diligently","scientifically","objectively","decidedly"],"ans":"A","xp":"Chọn (A) diligently.\n(A) diligently (Trạng từ): Một cách chăm chỉ, cần mẫn.\n(B) scientifically (Trạng từ): Một cách khoa học.\n(C) objectively (Trạng từ): Một cách khách quan.\n(D) decidedly (Trạng từ): Một cách dứt khoát, rõ rệt.\nTrạng từ bổ nghĩa cho động từ \"studied\" (học tập). Trong giáo dục, ta dùng \"study diligently\" để chỉ việc học tập cần mẫn.\nUseful phrases: Extensive training (Đào tạo chuyên sâu/rộng rãi)\nDịch: Vị trí thợ ống nước yêu cầu đào tạo chuyên sâu, ngay cả với những người đã học tập chăm chỉ ở trường kỹ thuật."},{"n":126,"q":"With its fixed price -------, Omega Cellular guarantees no phone bill increases for three years.","opts":["assurance","assuredly","assuring","assures"],"ans":"A","xp":"Chọn (A) assurance.\n(A) assurance (Danh từ): Sự đảm bảo, sự cam đoan.\n(B) assuredly (Trạng từ): Một cách chắc chắn.\n(C) assuring (V-ing/Tính từ): Đảm bảo.\n(D) assures (Động từ): Cam đoan.\nSau \"fixed price\" (giá cố định) cần một danh từ để tạo thành cụm danh từ làm tân ngữ sau giới từ \"With\". \"Price assurance\" (Sự đảm bảo về giá) là một cụm danh từ hoàn chỉnh về nghĩa.\nUseful phrases: Fixed price (Giá cố định); Phone bill increases (Sự tăng hóa đơn điện thoại)\nDịch: Với sự đảm bảo về mức giá cố định, Omega Cellular cam kết không tăng hóa đơn điện thoại trong vòng ba năm."},{"n":127,"q":"As chief analytics officer, Mr. Ko has worked at Lochston Ltd. with great ------- for more than twenty years.","opts":["deduction","duplication","declaration","dedication"],"ans":"D","xp":"Chọn (D) dedication.\n(A) deduction (Danh từ): Sự khấu trừ/sự suy luận.\n(B) duplication (Danh từ): Sự sao chép, nhân bản.\n(C) declaration (Danh từ): Sự tuyên bố, tờ khai.\n(D) dedication (Danh từ): Sự tận tụy, cống hiến.\nCâu hỏi từ vựng. Dấu hiệu là cụm \"for more than twenty years\" (hơn 20 năm) -> thể hiện sự cống hiến/tận tụy (dedication) lâu dài.\nUseful phrases: Chief analytics officer (Giám đốc phân tích dữ liệu)\nDịch: Với tư cách là giám đốc phân tích, ông Ko đã làm việc tại Lochston Ltd. với sự tận tụy to lớn trong hơn hai mươi năm."},{"n":128,"q":"Milltown Hospital's cafeteria serves lunch seven days a week ------- only on weekdays.","opts":["up to","as though","each time","rather than"],"ans":"D","xp":"Chọn (D) rather than.\n(A) up to (Giới từ): Lên đến.\n(B) as though (Liên từ): Như thể là.\n(C) each time (Trạng từ): Mỗi lần.\n(D) rather than (Liên từ/Giới từ): Thay vì.\nCâu này so sánh sự ưu tiên/lựa chọn. \"7 ngày một tuần\" đối lập với \"chỉ ngày thường\" -> dùng rather than (thay vì) để nhấn mạnh sự thay đổi.\nUseful phrases: Weekdays (Ngày trong tuần - từ thứ 2 đến thứ 6)\nDịch: Nhà ăn của Bệnh viện Milltown phục vụ bữa trưa 7 ngày một tuần thay vì chỉ vào các ngày trong tuần."},{"n":129,"q":"The store's entire inventory of lumber comes from a nearby ------- supplier.","opts":["financial","promotional","chemical","commercial"],"ans":"D","xp":"Chọn (D) commercial.\n(A) financial (Tính từ): Thuộc về tài chính.\n(B) promotional (Tính từ): Thuộc về quảng cáo/khuyến mãi.\n(C) chemical (Tính từ): Thuộc về hóa học.\n(D) commercial (Tính từ): Thuộc về thương mại.\n\"Lumber\" (gỗ xẻ) là hàng hóa được mua bán số lượng lớn. \"Commercial supplier\" (nhà cung cấp thương mại) là cụm từ chỉ đơn vị cung ứng hàng hóa cho doanh nghiệp.\nUseful phrases: Entire inventory (Toàn bộ hàng tồn kho)\nDịch: Toàn bộ kho gỗ của cửa hàng đến từ một nhà cung cấp thương mại gần đó."},{"n":130,"q":"For a $95 ------- fee, our mechanics will determine what repairs are needed.","opts":["diagnosed","diagnostic","diagnosable","diagnose"],"ans":"B","xp":"Chọn (B) diagnostic.\n(A) diagnosed (V-ed): Đã được chẩn đoán.\n(B) diagnostic (Tính từ): Có tính chẩn đoán.\n(C) diagnosable (Tính từ): Có thể chẩn đoán được.\n(D) diagnose (Động từ): Chẩn đoán.\nCâu hỏi Từ loại (Tính từ đứng trước danh từ). Chỗ trống đứng trước danh từ \"fee\" (phí). Ta cần một tính từ để bổ nghĩa. \"Diagnostic fee\" là một thuật ngữ kỹ thuật chỉ \"phí kiểm tra/phí chẩn đoán bệnh/lỗi\".\nUseful phrases: Mechanics (Thợ cơ khí/thợ máy).\nDịch: Với mức phí chẩn đoán 95 đô la, thợ máy của chúng tôi sẽ xác định các hạng mục cần sửa chữa."}],"p6":[{"ns":[131,134],"head":"Questions 131-134 refer to the following flyer.","passage":"<h3><i>Look to Riessler Landscaping for your Garden Needs</i></h3><p>Riessler Landscaping has everything you need to create your dream garden. We will listen to your ideas and offer suggestions that match your gardening desires. <span class=\"blank\" data-n=\"131\">-------</span>. The nursery here at Riessler Landscaping includes plants of many varieties and sizes that burst with eye-catching colors year-round. You are guaranteed to find something that will add <span class=\"blank\" data-n=\"132\">-------</span> to your garden. We are <span class=\"blank\" data-n=\"133\">-------</span> equipped to construct small ponds or other water features. And as our name suggests, we can take on more ambitious landscaping projects—whatever you need! With more than 40 years in the landscape–design business, <span class=\"blank\" data-n=\"134\">-------</span> expertise is unmatched.</p>","vi":"Hãy đến với Riessler Landscaping cho mọi nhu cầu làm vườn của bạn\n\nRiessler Landscaping có mọi thứ bạn cần để tạo nên khu vườn mơ ước của mình. Chúng tôi sẽ lắng nghe ý tưởng của bạn và đưa ra những gợi ý phù hợp với mong muốn làm vườn của bạn. Mục tiêu của Riessler Landscaping là biến tầm nhìn của bạn thành hiện thực. Khu vườn ươm tại Riessler Landscaping có nhiều loại cây với đủ kích cỡ khác nhau, rực rỡ với những màu sắc bắt mắt quanh năm. Bạn chắc chắn sẽ tìm thấy thứ gì đó có thể tăng thêm vẻ đẹp cho khu vườn của mình. Chúng tôi cũng có đầy đủ năng lực để xây dựng các hồ nước nhỏ hoặc những hạng mục cảnh quan liên quan đến nước khác. Và đúng như tên gọi của mình, chúng tôi có thể đảm nhận những dự án cảnh quan quy mô lớn hơn—bất cứ điều gì bạn cần! Với hơn 40 năm hoạt động trong lĩnh vực thiết kế cảnh quan, chuyên môn của chúng tôi là vô song.","qs":[{"n":131,"opts":["Staff members have written articles for the local newspaper.","Installing lights can enhance the effect of a well-designed garden.","Local competitors cannot beat the prices we charge.","Riessler Landscaping's goal is to make your vision a reality."],"ans":"D","xp":"Chọn D.\nTrước chỗ trống: nói về lắng nghe & đưa ra gợi ý. Sau chỗ trống: chuyển sang giới thiệu dịch vụ cụ thể → Cần 1 câu kết nối, nói rõ mục tiêu của công ty -> Chọn D: Tổng kết ý trước, dẫn sang phần giới thiệu dịch vụ.\n(A) Các nhân viên đã viết bài cho báo địa phương. -> Lạc đề, không liên quan làm vườn.\n(B) Việc lắp đèn có thể làm tăng hiệu quả của một khu vườn được thiết kế tốt. -> Quá chi tiết, chưa được dẫn dắt.\n(C) Các đối thủ địa phương không thể cạnh tranh được với mức giá của chúng tôi. -> Quảng cáo giá – không phù hợp mạch.\n(D) Mục tiêu của Riessler Landscaping là biến tầm nhìn của bạn thành hiện thực. → Tổng kết ý trước, dẫn sang phần giới thiệu dịch vụ.\nDịch: ... Chúng tôi sẽ lắng nghe ý tưởng của bạn và đưa ra những gợi ý phù hợp với mong muốn làm vườn của bạn. Mục tiêu của Riessler Landscaping là biến tầm nhìn của bạn thành hiện thực..."},{"n":132,"opts":["years","space","beauty","moisture"],"ans":"C","xp":"Chọn C.\nCấu trúc add + NOUN + to. Ngữ cảnh ở trước có những từ như \"eye-catching colors\" (màu sắc bắt mắt), \"plants\" (cây cối), \"year-round\" (đẹp quanh năm) -> chọn C là phù hợp ngữ nghĩa nhất.\n(A) years (n) năm\n(B) space (n) không gian\n(C) beauty (n) vẻ đẹp\n(D) moisture (n) độ ẩm\nDịch: Bạn chắc chắn sẽ tìm được thứ gì đó có thể tăng thêm vẻ đẹp cho khu vườn của mình."},{"n":133,"opts":["also","rarely","somehow","nevertheless"],"ans":"A","xp":"Chọn A.\nCần một trạng từ bổ nghĩa cho equipped với nghĩa là \"ngoài ra / thêm nữa\" để tiếp nối nói về những lợi ích mà dịch vụ cung cấp.\n(A) also (adv) cũng\n(B) rarely (adv) hiếm khi\n(C) somehow (adv) bằng cách nào đó\n(D) nevertheless (adv liên kết) tuy nhiên\nUseful Structures: also equipped to + V\nDịch: Chúng tôi cũng được trang bị đầy đủ để xây dựng các hồ nước nhỏ hoặc các hạng mục cảnh quan liên quan đến nước khác."},{"n":134,"opts":["its","our","others","their"],"ans":"B","xp":"Chọn B.\nPhía sau chỗ trống là Danh từ expertise, do vậy cần 1 tính từ (sở hữu) đứng ở chỗ ô trống -> chọn our (công ty đang nói về chính mình: \"we\").\nDịch: Với hơn 40 năm hoạt động trong lĩnh vực thiết kế cảnh quan, chuyên môn của chúng tôi là vô song."}]},{"ns":[135,138],"head":"Questions 135-138 refer to the following letter.","passage":"<p>10 January</p><p>Cindy Mulligan<br>88 Manchester Road<br>HARROGATE<br>HG82 2MJ</p><p>Dear Ms. Mulligan,</p><p>We are delighted to celebrate your 30th anniversary with Brandrix Distribution Centre. <span class=\"blank\" data-n=\"135\">-------</span>. Your dedication, loyalty, and hard work have contributed greatly to our success over the years. We appreciate your commitment to excellence. Over the years, you <span class=\"blank\" data-n=\"136\">-------</span> great initiative, creativity, and leadership.</p><p>You will <span class=\"blank\" data-n=\"137\">-------</span> be receiving a commemorative plaque by post. We hope this token of our gratitude reminds you how much you mean to us.</p><p>Congratulations on reaching this <span class=\"blank\" data-n=\"138\">-------</span>. Thank you for being part of our Brandrix family.</p><p>Sincerely,</p><p>Lance Powar, Vice President of Human Resources<br>Brandrix Distribution Centre</p>","vi":"Ngày 10 tháng 1\n\nCindy Mulligan\n88 Manchester Road\nHARROGATE\nHG82 2MJ\n\nGửi bà Mulligan,\n\nChúng tôi rất vui mừng được kỷ niệm 30 năm ngày bà làm việc tại Trung tâm Phân phối Brandrix. Bà đã là một thành viên quý giá của đội ngũ chúng tôi. Sự tận tụy, lòng trung thành và sự làm việc chăm chỉ của bà đã đóng góp to lớn vào thành công của chúng tôi trong suốt những năm qua. Chúng tôi trân trọng cam kết của bà đối với sự xuất sắc. Trong suốt những năm qua, bà đã thể hiện tinh thần chủ động, sáng tạo và khả năng lãnh đạo tuyệt vời.\n\nBà sẽ sớm nhận được một tấm kỷ niệm chương qua đường bưu điện. Chúng tôi hy vọng biểu tượng của lòng biết ơn này sẽ nhắc nhở bà rằng bà có ý nghĩa như thế nào đối với chúng tôi.\n\nChúc mừng bà đã đạt được cột mốc này. Cảm ơn bà đã là một phần của gia đình Brandrix.\n\nTrân trọng,\n\nLance Powar, Phó Chủ tịch Nhân sự\nTrung tâm Phân phối Brandrix","qs":[{"n":135,"opts":["We especially value our long-term customers.","Please join our holiday celebration.","Our annual report will be released soon.","You have been a valuable member of our team."],"ans":"D","xp":"Chọn D.\n(A) Chúng tôi đặc biệt coi trọng những khách hàng lâu năm.\n(B) Vui lòng tham gia lễ kỷ niệm ngày lễ của chúng tôi.\n(C) Báo cáo thường niên của chúng tôi sẽ sớm được phát hành.\n(D) Bạn đã là một thành viên quý giá của đội ngũ chúng tôi.\nCâu trước đó nói về việc kỷ niệm 30 năm làm việc của bà Mulligan tại công ty. Câu sau đó khen ngợi sự tận tụy và làm việc chăm chỉ của bà. Đáp án (D) kết nối hoàn hảo giữa việc chúc mừng thâm niên làm việc và việc khen ngợi đóng góp cá nhân. Các đáp án A, B, C đều lạc đề (nói về khách hàng, ngày lễ hoặc báo cáo).\nUseful structures: Be delighted to do something: Rất vui mừng/hân hạnh được làm gì."},{"n":136,"opts":["will show","must show","have shown","are showing"],"ans":"C","xp":"Chọn C.\n(A) will show: sẽ cho thấy (Thì tương lai đơn)\n(B) must show: phải cho thấy (Động từ khuyết thiếu)\n(C) have shown: đã cho thấy (Thì hiện tại hoàn thành)\n(D) are showing: đang cho thấy (Thì hiện tại tiếp diễn)\nCụm từ \"Over the years\" (Trong suốt những năm qua) là dấu hiệu kinh điển của thì Hiện tại hoàn thành, diễn tả một hành động kéo dài từ quá khứ đến hiện tại. => C phù hợp với dấu hiệu thời gian và ý nghĩa là bà đã thể hiện sự sáng tạo và lãnh đạo trong suốt quá trình làm việc.\nUseful structures: Commitment to excellence: Cam kết hướng tới sự xuất sắc (Cụm từ hay gặp trong tuyên bố sứ mệnh công ty). Take initiative: Chủ động trong công việc."},{"n":137,"opts":["then","soon","instead","likewise"],"ans":"B","xp":"Chọn B.\n(A) then: sau đó\n(B) soon: sớm\n(C) instead: thay vào đó\n(D) likewise: tương tự như vậy\nNgữ cảnh ta có \"You will ------- be receiving...\" (Bạn sẽ ------- nhận được một tấm kỷ niệm chương qua đường bưu điện). -> chọn B. \"Will soon be receiving\" là một cấu trúc rất phổ biến trong thư từ thương mại để thông báo một việc sắp xảy ra trong tương lai gần.\nUseful structures: Commemorative plaque: Tấm kỷ niệm chương. Token of gratitude: Vật (quà) để bày tỏ lòng biết ơn."},{"n":138,"opts":["milestone","consensus","destination","understanding"],"ans":"A","xp":"Chọn A.\n(A) milestone: cột mốc quan trọng\n(B) consensus: sự đồng thuận\n(C) destination: điểm đến\n(D) understanding: sự thấu hiểu/hiểu biết\nTa có \"Congratulations on reaching this -------\" (Chúc mừng bạn đã đạt được ------- này). => chọn A vì việc làm việc 30 năm tại một công ty được coi là một \"cột mốc\" (milestone) lớn trong sự nghiệp. Các từ còn lại không phù hợp để nói về thâm niên làm việc."}]},{"ns":[139,142],"head":"Questions 139-142 refer to the following e-mail.","passage":"<div class=\"hdr\"><p><b>To:</b> Kay Berman &lt;kberman@xmail.com&gt;</p><p><b>From:</b> Ali Chaleby &lt;achaleby@ralenciadesign.com&gt;</p><p><b>Date:</b> August 21</p><p><b>Subject:</b> Plans for living room</p><p><b>Attachment:</b> Samples</p></div><p>Dear Ms. Berman,</p><p>My design team is in the process of <span class=\"blank\" data-n=\"139\">-------</span> the plans for your living room. Based on our last conversation, I have chosen different paints for the walls and borders. Please review the attached file and decide whether you like those new <span class=\"blank\" data-n=\"140\">-------</span>. If not, it is not too late to make a change. <span class=\"blank\" data-n=\"141\">-------</span>. Your review will help us refine the design before we start.</p><p>Please let <span class=\"blank\" data-n=\"142\">-------</span> know if you have any questions. I look forward to hearing from you.</p><p>Kind regards,</p><p>Ali Chaleby, Ralencia Design</p>","vi":"Người nhận: Kay Berman\nNgười gửi: Ali Chaleby\nNgày: 21 tháng 8\nTiêu đề: Kế hoạch cho phòng khách\nTệp đính kèm: Mẫu\n\nChào bà Berman,\n\nNhóm thiết kế của tôi đang trong quá trình hoàn thiện các bản kế hoạch cho phòng khách của bà. Dựa trên cuộc trò chuyện gần nhất của chúng ta, tôi đã chọn các loại sơn khác nhau cho các bức tường và phần viền. Vui lòng xem xét tệp đính kèm và quyết định xem bà có thích những màu sắc mới đó không. Nếu không, vẫn chưa quá muộn để thực hiện thay đổi. Chúng tôi chưa có kế hoạch bắt đầu công việc trong hai tuần tới. Sự xem xét của bà sẽ giúp chúng tôi tinh chỉnh bản thiết kế trước khi chúng tôi bắt đầu.\n\nVui lòng cho tôi biết nếu bà có bất kỳ câu hỏi nào. Tôi rất mong nhận được phản hồi từ bà.\n\nTrân trọng,\n\nAli Chaleby, Ralencia Design","qs":[{"n":139,"opts":["finalizing","finalize","finalized","finalizes"],"ans":"A","xp":"Chọn A.\n(A) finalizing: đang hoàn thiện (V-ing)\n(B) finalize: hoàn thiện (V nguyên thể)\n(C) finalized: đã hoàn thiện (V-ed)\n(D) finalizes: hoàn thiện (V-s)\nCụm từ cố định \"in the process of + V-ing\" (trong quá trình làm việc gì đó). Đằng sau giới từ \"of\" chúng ta luôn cần một danh động từ (Gerund). -> Chọn A: Chỉ có \"finalizing\" phù hợp với cấu trúc ngữ pháp này.\nUseful structures: In the process of doing something: Đang trong quá trình thực hiện điều gì."},{"n":140,"opts":["organizations","schedules","colors","times"],"ans":"C","xp":"Chọn C.\n(A) organizations: các tổ chức\n(B) schedules: các lịch trình\n(C) colors: các màu sắc\n(D) times: các thời điểm\nCâu trước đó đề cập đến: \"I have chosen different paints for the walls and borders\" (Tôi đã chọn các loại sơn khác nhau cho tường và viền). -> Trong thiết kế nội thất, khi nói đến sơn (paint), chúng ta đang nói về màu sắc (colors). \"Those new colors\" dùng để thay thế cho cụm \"different paints\" ở câu trước -> C là hợp lý nhất.\nUseful structures: Based on our last conversation: Dựa trên cuộc trò chuyện gần nhất của chúng ta (Cách dẫn dắt chuyên nghiệp)."},{"n":141,"opts":["I have already begun drawing up plans for your kitchen.","We are not planning to begin work for another two weeks.","Your living room is particularly spacious and airy.","We have not yet received your current payment."],"ans":"B","xp":"Chọn B.\n(A) Tôi đã bắt đầu lập kế hoạch cho nhà bếp của bạn.\n(B) Chúng tôi chưa có kế hoạch bắt đầu công việc trong hai tuần tới.\n(C) Phòng khách của bạn đặc biệt rộng rãi và thoáng đãng.\n(D) Chúng tôi vẫn chưa nhận được khoản thanh toán hiện tại của bạn.\nCâu ngay sau chỗ trống là: \"Your review will help us refine the design before we start\" (Sự xem xét của bạn sẽ giúp chúng tôi tinh chỉnh thiết kế trước khi chúng tôi bắt đầu). -> Câu (B) tạo ra sự logic về thời gian. Vì họ chưa định bắt đầu làm việc ngay (trong 2 tuần tới) nên khách hàng vẫn còn thời gian để xem xét và thay đổi thiết kế. Đáp án (A) lạc đề sang \"nhà bếp\", (C) khen phòng khách không liên quan đến việc \"tinh chỉnh thiết kế\", (D) nhắc đến thanh toán quá đột ngột.\nUseful structures: Refine the design: Tinh chỉnh/cải thiện thiết kế. Review the attached file: Xem xét tệp đính kèm (Xuất hiện liên tục trong Part 6 & 7)."},{"n":142,"opts":["them","ours","his","me"],"ans":"D","xp":"Chọn D.\n(A) them: họ/chúng (tân ngữ số nhiều)\n(B) ours: của chúng tôi (đại từ sở hữu)\n(C) his: của anh ấy (tính từ/đại từ sở hữu)\n(D) me: tôi (tân ngữ số ít)\nChọn me là phù hợp ngữ pháp và ý nghĩa nhất. Cấu trúc \"Please let me know\" (Vui lòng cho tôi biết) là một câu kết email cực kỳ kinh điển. Người viết đang yêu cầu khách hàng phản hồi trực tiếp cho mình."}]},{"ns":[143,146],"head":"Questions 143-146 refer to the following e-mail.","passage":"<div class=\"hdr\"><p><b>To:</b> Marsha Zalen &lt;mzalen@mansfield.com&gt;</p><p><b>From:</b> Kaymar PCP &lt;info@kaymarpcp.com&gt;</p><p><b>Date:</b> September 8</p><p><b>Subject:</b> Your recent office visit</p></div><p>Dear Ms. Zalen,</p><p>Thank you for your recent visit to Kaymar Primary Care Practice. We hope you found our services <span class=\"blank\" data-n=\"143\">-------</span>, and we welcome suggestions for improvement.</p><p>We have posted a <span class=\"blank\" data-n=\"144\">-------</span> of your consultation on our portal. Please take a moment to go through it and let us know if you have any questions.</p><p>As a reminder, you can log in to the portal for various activities. <span class=\"blank\" data-n=\"145\">-------</span>, you can make appointments and payments, view your medical history, review lab results, and request medication refills. <span class=\"blank\" data-n=\"146\">-------</span>. Rest assured that your personal information is safe and secure.</p><p>We thank you for your business and look forward to serving you again.</p><p>Kaymar Primary Care Practice</p>","vi":"Người nhận: Marsha Zalen\nNgười gửi: Kaymar PCP\nNgày: 8 tháng 9\nTiêu đề: Lần khám gần đây của bà\n\nThưa bà Zalen,\n\nCảm ơn bà đã đến khám gần đây tại Phòng khám Chăm sóc Sức khỏe Ban đầu Kaymar. Chúng tôi hy vọng bà thấy dịch vụ của chúng tôi vừa ý, và chúng tôi luôn hoan nghênh các góp ý để cải thiện.\n\nChúng tôi đã đăng một bản tóm tắt buổi tư vấn của bà lên cổng thông tin của chúng tôi. Vui lòng dành chút thời gian xem qua và cho chúng tôi biết nếu bà có bất kỳ câu hỏi nào.\n\nXin nhắc lại, bà có thể đăng nhập vào cổng thông tin để thực hiện nhiều hoạt động khác nhau. Ví dụ, bà có thể đặt lịch hẹn và thanh toán, xem tiền sử bệnh, xem kết quả xét nghiệm và yêu cầu cấp thêm thuốc theo đơn. Chúng tôi hy vọng bà sẽ sử dụng nguồn tài nguyên này để quản lý các nhu cầu chăm sóc sức khỏe của mình. Bà hãy yên tâm rằng thông tin cá nhân của bà được giữ an toàn và bảo mật.\n\nCảm ơn bà đã tin tưởng sử dụng dịch vụ và chúng tôi mong được phục vụ bà lần sau.\n\nPhòng khám Chăm sóc Sức khỏe Ban đầu Kaymar","qs":[{"n":143,"opts":["satisfied","satisfaction","satisfactory","satisfactorily"],"ans":"C","xp":"Chọn C.\n(A) satisfied (adj/V-ed): cảm thấy hài lòng (thường dùng cho người).\n(B) satisfaction (noun): sự hài lòng.\n(C) satisfactory (adj): thỏa đáng, vừa ý (dùng để miêu tả tính chất sự vật/dịch vụ).\n(D) satisfactorily (adv): một cách thỏa đáng.\nTa có \"found our services + [Adj]\". Sau động từ \"find\" cộng tân ngữ, chúng ta cần một tính từ để bổ nghĩa cho tân ngữ \"services\" đó. => \"Satisfactory\" miêu tả chất lượng của dịch vụ là tốt, vừa ý. Đáp án (A) sai vì \"satisfied\" thường dùng để diễn tả cảm xúc của con người.\nDịch: Chúng tôi hy vọng bà thấy dịch vụ của chúng tôi vừa ý, và chúng tôi luôn hoan nghênh các góp ý để cải thiện."},{"n":144,"opts":["photo","lecture","summary","schedule"],"ans":"C","xp":"Chọn C.\n(A) photo (noun): bức ảnh.\n(B) lecture (noun): bài giảng.\n(C) summary (noun): bản tóm tắt.\n(D) schedule (noun): lịch trình.\nNgữ cảnh có \"We have posted a ------- of your consultation on our portal.\" (Chúng tôi đã đăng một ------- về buổi tư vấn của bạn lên cổng thông tin của chúng tôi) -> Chọn C vì trong y tế, sau khi khám (consultation), phòng khám thường cung cấp một \"bản tóm tắt\" nội dung buổi khám để bệnh nhân theo dõi. Các từ như ảnh, bài giảng hay lịch trình đều không phù hợp logic trong ngữ cảnh này."},{"n":145,"opts":["To repeat","For instance","Otherwise","Consequently"],"ans":"B","xp":"Chọn B.\n(A) To repeat: để nhắc lại.\n(B) For instance: ví dụ như.\n(C) Otherwise: nếu không thì.\n(D) Consequently: hệ quả là.\nTa thấy câu trước nói về việc portal có \"various activities\" (nhiều hoạt động khác nhau). Vế sau liệt kê các hoạt động cụ thể như đặt lịch hẹn, thanh toán, xem lịch sử y tế… -> Chọn B \"For instance\" dùng để đưa ra các ví dụ cụ thể cho cụm \"various activities\" đã nêu trước đó.\nUseful phrases: Medical history: Lịch sử y tế/tiền sử bệnh án. Medication refills: Việc cấp thêm thuốc theo đơn cũ."},{"n":146,"opts":["We hope you will use this resource to manage your health-care needs.","The staff will close the office early on Friday afternoons.","Please be sure to come to our office fifteen minutes in advance.","We apologize for any confusion about your appointment time."],"ans":"A","xp":"Chọn A.\n(A) Chúng tôi hy vọng bạn sẽ sử dụng nguồn tài nguyên này để quản lý các nhu cầu chăm sóc sức khỏe của mình.\n(B) Nhân viên sẽ đóng cửa văn phòng sớm vào chiều thứ Sáu.\n(C) Hãy nhớ đến văn phòng của chúng tôi trước 15 phút.\n(D) Chúng tôi xin lỗi vì bất kỳ sự nhầm lẫn nào về thời gian hẹn của bạn.\nTa thấy ngữ cảnh cả đoạn văn đang giới thiệu về các tính năng của \"portal\" (cổng thông tin trực tuyến). Câu ngay sau chỗ trống là lời cam đoan về bảo mật thông tin cá nhân. -> Câu (A) tóm gọn lại mục đích của việc sử dụng portal (nguồn tài nguyên này) là để giúp bệnh nhân quản lý sức khỏe, rất phù hợp với mạch văn.\nUseful structures: Rest assured that...: Hãy yên tâm rằng..."}]}],"p7":[{"ns":[147,148],"head":"Questions 147-148 refer to the following notice.","passages":["<p>Dear High View Apartments Resident,</p><p>Riverside Paving Company is coming to High View Apartments on May 3 and 4 to resurface the parking area. All vehicles must be removed by 8 A.M. on May 3 for the work to commence. Residents may use the parking area again starting on May 5 at 8 A.M. We realize that trying to find another place to park is inconvenient, but it is necessary for the job to be completed in the two days scheduled. Note that all parking spaces will be widened, and some spaces could be moved during the work. You will receive an e-mail if your parking space is moved more than 20 meters from your previous one.</p><p>Thank you for your cooperation,<br>Judith Alvarez, Property Manager</p>"],"vi":"Thân gửi Cư dân Chung cư High View,\n\nCông ty Riverside Paving sẽ đến Chung cư High View vào ngày 3 và ngày 4 tháng 5 để trải nhựa lại khu vực bãi đậu xe. Tất cả các phương tiện phải được di dời trước 8 giờ sáng ngày 3 tháng 5 để công việc được bắt đầu. Cư dân có thể bắt đầu sử dụng lại bãi đậu xe từ 8 giờ sáng ngày 5 tháng 5. Chúng tôi hiểu rằng việc tìm chỗ đậu xe khác là một sự bất tiện, nhưng điều này là cần thiết để công việc được hoàn thành trong hai ngày theo đúng kế hoạch. Lưu ý rằng tất cả các chỗ đậu xe sẽ được mở rộng, và một số vị trí có thể bị thay đổi trong quá trình thi công. Bạn sẽ nhận được email nếu vị trí đậu xe của bạn bị thay đổi cách vị trí cũ quá 20 mét.\n\nCảm ơn sự hợp tác của quý vị,\nJudith Alvarez, Quản lý Tòa nhà","qs":[{"n":147,"q":"What is the purpose of the notice?","qvi":"Mục đích của thông báo là gì?","opts":["To invite residents to a meeting on May 3","To request feedback about parking facilities","To inform residents of an upcoming project","To announce an increase in parking fees"],"ans":"C","xp":"Đáp án: (C)\nCăn cứ: \"Công ty Riverside Paving sẽ đến Chung cư High View vào ngày 3 và ngày 4 tháng 5 để trải nhựa lại khu vực bãi đậu xe.\" → thông báo về dự án trải nhựa sắp tới.\n(A) Mời cư dân tham dự một cuộc họp vào ngày 3 tháng 5\n(B) Yêu cầu ý kiến phản hồi về khu vực đỗ xe\n(C) Thông báo cho cư dân về một dự án sắp diễn ra\n(D) Thông báo việc tăng phí đỗ xe"},{"n":148,"q":"What is suggested about High View Apartments?","qvi":"Điều gì được gợi ý về High View Apartments?","opts":["It charges residents a monthly maintenance fee.","It recently hired a new property manager.","It has the parking area repaved every year.","It assigns tenants specific parking spots."],"ans":"D","xp":"Đáp án: (D)\nCăn cứ: \"Bạn sẽ nhận được email nếu vị trí đậu xe của bạn bị thay đổi cách vị trí cũ quá 20 mét.\" → mỗi cư dân có chỗ đậu xe riêng.\n(A) Nơi này thu phí bảo trì hàng tháng từ cư dân\n(B) Gần đây đã thuê một người quản lý tòa nhà mới\n(C) Khu vực đỗ xe được trải nhựa lại hằng năm\n(D) Mỗi cư dân được phân công chỗ đỗ xe riêng"}]},{"ns":[149,150],"head":"Questions 149-150 refer to the following text-message chain.","passages":["<div class=\"msg\"><p><b>Carol Barger (10:45 A.M.)</b></p><p>Hello, Ms. Seang.</p></div><div class=\"msg\"><p><b>Leakhena Seang (10:55 A.M.)</b></p><p>Good morning!</p></div><div class=\"msg\"><p><b>Carol Barger (11:15 A.M.)</b></p><p>We have fifteen participants enrolled in your mosaic workshop tomorrow. That is five more than last summer. Your workshops get more popular every year! Do you have enough materials on hand for that many participants?</p></div><div class=\"msg\"><p><b>Leakhena Seang (11:23 A.M.)</b></p><p>I have plenty to go around. We'll be creating mosaic designs using bits of sea glass I collected on my vacation last summer. They are pieces of brown, green, and blue bottles that have washed up on the beach. The sand has smoothed all the sharp edges, so they're perfectly safe for everyone to use.</p></div><div class=\"msg\"><p><b>Carol Barger (11:30 A.M.)</b></p><p>Sounds good. See you tomorrow at breakfast.</p></div>"],"vi":"Carol Barger (10:45 sáng): Chào cô Seang.\n\nLeakhena Seang (10:55 sáng): Chào buổi sáng!\n\nCarol Barger (11:15 sáng): Chúng tôi đã có mười lăm người đăng ký tham gia hội thảo nghệ thuật mosaic (ghép mảnh) của cô vào ngày mai. Con số đó nhiều hơn năm người so với mùa hè năm ngoái. Các buổi hội thảo của cô ngày càng được yêu thích hơn qua mỗi năm! Cô có đủ nguyên vật liệu sẵn có cho số lượng người tham gia đông như vậy không?\n\nLeakhena Seang (11:23 sáng): Tôi có đủ cho tất cả mọi người. Chúng ta sẽ tạo ra các thiết kế mosaic bằng những mảnh thủy tinh biển mà tôi đã thu thập trong kỳ nghỉ hè năm ngoái. Đó là những mảnh chai lọ màu nâu, xanh lá và xanh dương dạt vào bờ biển. Cát đã mài nhẵn tất cả các cạnh sắc nhọn, vì vậy chúng hoàn toàn an toàn cho mọi người sử dụng.\n\nCarol Barger (11:30 sáng): Nghe tuyệt đấy. Hẹn gặp cô vào bữa sáng ngày mai nhé.","qs":[{"n":149,"q":"What most likely is Ms. Seang's job?","qvi":"Công việc của cô Seang có khả năng cao nhất là gì?","opts":["Glassmaker","Art instructor","Beach lifeguard","Program administrator"],"ans":"B","xp":"Đáp án: (B)\nCăn cứ: \"Chúng tôi đã có mười lăm người đăng ký tham gia hội thảo nghệ thuật mosaic của cô vào ngày mai.\" và \"Chúng ta sẽ tạo ra các thiết kế mosaic bằng những mảnh thủy tinh biển...\" → cô Seang dạy hội thảo nghệ thuật.\n(A) Thợ làm đồ thủy tinh\n(B) Giảng viên nghệ thuật\n(C) Nhân viên cứu hộ bãi biển\n(D) Điều phối viên chương trình"},{"n":150,"q":"At 11:23 A.M., what does Ms. Seang imply when she writes, \"I have plenty to go around\"?","qvi":"Vào lúc 11:23 sáng, khi cô Seang viết \"I have plenty to go around\" (Tôi có rất nhiều để chia cho mọi người), cô ấy ngụ ý điều gì?","opts":["She intends to create an extra-large mosaic.","She has been collecting sea glass for many years.","She can share her sea glass with all the workshop participants.","She does not think she will use much of her sea glass."],"ans":"C","xp":"Đáp án: (C)\nCăn cứ: Câu hỏi trước đó: \"Cô có đủ nguyên vật liệu cho số lượng người tham gia đông như vậy không?\" → \"Tôi có đủ cho tất cả mọi người. Chúng ta sẽ tạo ra các thiết kế mosaic bằng những mảnh thủy tinh biển mà tôi đã thu thập...\" → cô ấy có đủ thủy tinh biển để chia cho tất cả học viên.\n(A) Cô ấy dự định tạo ra một bức tranh khảm cỡ rất lớn.\n(B) Cô ấy đã sưu tầm thủy tinh biển trong nhiều năm.\n(C) Cô ấy có thể chia sẻ thủy tinh biển của mình với tất cả những người tham gia hội thảo.\n(D) Cô ấy nghĩ rằng mình sẽ không sử dụng nhiều thủy tinh biển."}]},{"ns":[151,152],"head":"Questions 151-152 refer to the following e-mail.","passages":["<div class=\"hdr\"><p><b>To:</b> Sales Team</p><p><b>From:</b> Laura Correa</p><p><b>Date:</b> 5 October</p><p><b>Subject:</b> Updates</p></div><p>Dear Team,</p><p>As announced in the Brighter Sails September newsletter, our performance has been consistently strong this year. This is an accomplishment we can all be proud of. Please take a moment to congratulate each other. We will continue to dream up new and exciting plans for the future!</p><p>In other news, Jasen Norton will transfer to our Kingston headquarters next month. We are sad to lose Mr. Norton, but we gratefully acknowledge his excellent work and wish him continued success in his new role.</p><p>There will be a farewell luncheon for Mr. Norton on 28 October at 1:00 P.M. in the second-floor conference room. Bring your good cheer and perhaps a story to share. The company will supply lunch, a cake, and decorations. Let me know by 12 October whether you will be able to attend.</p><p>Sincerely,</p><p>Laura Correa, Sales Manager<br>Brighter Sails Ltd.</p>"],"vi":"Tới: Đội ngũ Bán hàng\nTừ: Laura Correa\nNgày: 5 tháng 10\nChủ đề: Cập nhật\n\nThân gửi cả đội,\n\nNhư đã thông báo trong bản tin tháng 9 của Brighter Sails, hiệu suất làm việc của chúng ta đã duy trì ở mức mạnh mẽ và ổn định trong năm nay. Đây là một thành tựu mà tất cả chúng ta đều có thể tự hào. Các bạn hãy dành chút thời gian để chúc mừng lẫn nhau nhé. Chúng ta sẽ tiếp tục cùng nhau xây dựng những kế hoạch mới đầy thú vị cho tương lai!\n\nTrong một tin tức khác, Jasen Norton sẽ chuyển công tác đến trụ sở chính tại Kingston vào tháng tới. Chúng tôi rất buồn khi phải chia tay ông Norton, nhưng chúng tôi chân thành ghi nhận những đóng góp xuất sắc của ông và chúc ông tiếp tục thành công trong vai trò mới.\n\nSẽ có một bữa trưa chia tay ông Norton vào lúc 1 giờ chiều ngày 28 tháng 10 tại phòng họp tầng hai. Hãy mang theo tinh thần vui vẻ và có lẽ là một vài câu chuyện để cùng chia sẻ. Công ty sẽ cung cấp bữa trưa, bánh ngọt và đồ trang trí. Vui lòng cho tôi biết trước ngày 12 tháng 10 liệu bạn có thể tham dự hay không.\n\nTrân trọng,\nLaura Correa, Quản lý Bán hàng\nBrighter Sails Ltd.","qs":[{"n":151,"q":"What is mentioned about Mr. Norton?","qvi":"Điều gì được đề cập về ông Norton?","opts":["He will be attending a sales conference.","He sent Ms. Correa an office supply request.","He wrote an article in the September newsletter.","He will be moving to another company location."],"ans":"D","xp":"Đáp án: (D)\nCăn cứ: \"Jasen Norton sẽ chuyển công tác đến trụ sở chính tại Kingston vào tháng tới.\" → ông ấy chuyển đến một địa điểm khác của công ty.\n(A) Ông ấy sẽ tham dự một hội nghị bán hàng.\n(B) Ông ấy đã gửi cho cô Correa một yêu cầu về vật dụng văn phòng.\n(C) Ông ấy đã viết một bài báo trong bản tin tháng Chín.\n(D) Ông ấy sẽ chuyển đến làm việc tại một chi nhánh khác của công ty."},{"n":152,"q":"What does Ms. Correa ask members of the sales team to do?","qvi":"Cô Correa yêu cầu các thành viên trong nhóm bán hàng làm gì?","opts":["Send her stories for a newsletter","Give her names of potential new hires","Inform her of plans to attend an event","Help her decorate the office"],"ans":"C","xp":"Đáp án: (C)\nCăn cứ: \"Sẽ có một bữa trưa chia tay ông Norton... Vui lòng cho tôi biết trước ngày 12 tháng 10 liệu bạn có thể tham dự hay không.\"\n(A) Gửi cho cô ấy các câu chuyện/bài viết cho bản tin\n(B) Cung cấp cho cô ấy tên của những ứng viên tiềm năng\n(C) Thông báo cho cô ấy kế hoạch tham dự một sự kiện\n(D) Giúp cô ấy trang trí văn phòng"}]},{"ns":[153,154],"head":"Questions 153-154 refer to the following article.","passages":["<h3>Refurbished Theater Gives Town a Boost</h3><p>BEACHVILLE (February 24)—Beachville residents and tourists have a good reason to celebrate. The 40-year-old Crown Coastal Theater is scheduled to reopen in June. Many were saddened when the former theater owners decided to close the venue over a year ago, citing the cost of needed renovations. Fortunately, the theater has new owners who have spent the last year updating the interior and the projection system.</p><p>Christine Lafferty said that she and her childhood friend Morgan Flanagan spent plenty of time at the theater while growing up. “Going to the movies is the thing to do on a rainy day in a seaside town. We were sorry to see it close.” The friends, who also own the popular Blue Bay Bistro, decided to buy the theater and make the necessary repairs to keep it a thriving business. For more information about the theater and its upcoming events, visit www.crowncoastaltheater.com.</p>"],"vi":"Nhà hát được tân trang mang lại sức sống mới cho thị trấn\n\nBEACHVILLE (Ngày 24 tháng 2) — Cư dân và khách du lịch tại Beachville có một lý do chính đáng để ăn mừng. Nhà hát Crown Coastal 40 năm tuổi dự kiến sẽ mở cửa trở lại vào tháng 6. Nhiều người đã rất buồn khi những người chủ cũ của nhà hát quyết định đóng cửa địa điểm này hơn một năm trước, với lý do chi phí cải tạo cần thiết quá cao. May mắn thay, nhà hát đã có những người chủ mới, những người đã dành cả năm qua để cập nhật nội thất và hệ thống máy chiếu.\n\nChristine Lafferty cho biết cô và người bạn thời thơ ấu Morgan Flanagan đã dành rất nhiều thời gian tại nhà hát khi còn nhỏ. \"Đi xem phim là việc nên làm vào một ngày mưa ở một thị trấn ven biển. Chúng tôi rất tiếc khi thấy nó đóng cửa.\" Đôi bạn này, cũng là chủ sở hữu của nhà hàng Blue Bay Bistro nổi tiếng, đã quyết định mua lại nhà hát và thực hiện các sửa chữa cần thiết để duy trì hoạt động kinh doanh phát triển. Để biết thêm thông tin về nhà hát và các sự kiện sắp tới, hãy truy cập www.crowncoastaltheater.com.","qs":[{"n":153,"q":"What is the purpose of the article?","qvi":"Mục đích của bài báo là gì?","opts":["To report on beach conditions","To announce a business reopening","To promote a movie premiere","To advertise a new restaurant"],"ans":"B","xp":"Đáp án: (B)\nCăn cứ: \"Nhà hát Crown Coastal 40 năm tuổi dự kiến sẽ mở cửa trở lại vào tháng 6.\"\n(A) Báo cáo về tình trạng bãi biển\n(B) Thông báo việc một doanh nghiệp mở cửa trở lại\n(C) Quảng bá buổi ra mắt một bộ phim\n(D) Quảng cáo một nhà hàng mới"},{"n":154,"q":"Who is Ms. Flanagan?","qvi":"Bà Flanagan là ai?","opts":["A town council member","An event coordinator","Ms. Lafferty's business partner","The writer of the article"],"ans":"C","xp":"Đáp án: (C)\nCăn cứ: \"Christine Lafferty cho biết cô và người bạn thời thơ ấu Morgan Flanagan... Đôi bạn này, cũng là chủ sở hữu của nhà hàng Blue Bay Bistro..., đã quyết định mua lại nhà hát\" → hai người cùng kinh doanh.\n(A) Một thành viên hội đồng thị trấn\n(B) Một điều phối viên sự kiện\n(C) Đối tác kinh doanh của bà Lafferty\n(D) Tác giả của bài viết"}]},{"ns":[155,157],"head":"Questions 155-157 refer to the following e-mail.","passages":["<div class=\"hdr\"><p><b>To:</b> Randi Longfellow &lt;rlongfellow@sapphiremail.com.au&gt;</p><p><b>From:</b> Deon Welman &lt;deonwelman@skyviewscopes.com.au&gt;</p><p><b>Date:</b> 27 March</p><p><b>Subject:</b> Makatasi model METX-33948</p></div><p>Dear Ms. Longfellow,</p><p>Thank you for ordering the Makatasi ETX-Triple Refracting Telescope, model METX-33948. Unfortunately, the item you requested is on back order. — <span class=\"pos\">[1]</span> —. If you would prefer not to wait, we have a similar telescope made by another manufacturer, Belter Telescopes. Like the Makatasi model you ordered, the Belter BTR-1483 has a 120 mm aperture and a retractable lens hood. — <span class=\"pos\">[2]</span> —. In addition, all Belter telescopes include a padded carrying case. The Belter BTR-1483 costs $200 less than the Makatasi METX-33948.</p><p>If you wish to revise your order, simply reply to this e-mail within 48 hours or go to our Web site to chat with a representative at http://www.skyviewscopes.com.au. We will then change your order, refund $200 to your credit card, and ship your new telescope overnight at no extra charge. — <span class=\"pos\">[3]</span> —. Otherwise, we will notify you when the Makatasi model METX-33948 is back in stock and provide delivery information at that point. — <span class=\"pos\">[4]</span> —.</p><p>Best regards,</p><p>Deon Welman<br>Sales Representative, Skyview Scopes</p>"],"vi":"Người nhận: Randi Longfellow <rlongfellow@sapphiremail.com.au>\nNgười gửi: Deon Welman <deonwelman@skyviewscopes.com.au>\nNgày: 27 tháng 3\nChủ đề: Mẫu Makatasi METX-33948\n\nThưa bà Longfellow,\n\nCảm ơn bà đã đặt mua Kính thiên văn khúc xạ Triple ETX của Makatasi, mẫu METX-33948. Rất tiếc, mặt hàng bà yêu cầu hiện đang bị chậm đơn hàng (hết hàng tạm thời) — [1] —. Nếu bà không muốn chờ đợi, chúng tôi có một mẫu kính thiên văn tương tự từ một nhà sản xuất khác là Belter Telescopes. Giống như mẫu Makatasi mà bà đã đặt, mẫu Belter BTR-1483 có khẩu độ 120 mm và loa che nắng có thể thu gọn — [2] —. Ngoài ra, tất cả kính thiên văn của Belter đều bao gồm một túi đựng có lớp đệm lót. Mẫu Belter BTR-1483 có giá thấp hơn 200 đô la so với mẫu Makatasi METX-33948.\n\nNếu bà muốn điều chỉnh đơn hàng của mình, chỉ cần trả lời email này trong vòng 48 giờ hoặc truy cập trang web của chúng tôi để trò chuyện với đại diện tại http://www.skyviewscopes.com.au. Sau đó, chúng tôi sẽ thay đổi đơn hàng của bà, hoàn trả 200 đô la vào thẻ tín dụng và giao kính thiên văn mới của bà qua đêm mà không tính thêm phí — [3] —. Nếu không, chúng tôi sẽ thông báo cho bà khi mẫu Makatasi METX-33948 có hàng trở lại và cung cấp thông tin giao hàng tại thời điểm đó — [4] —.\n\nTrân trọng,\nDeon Welman\nĐại diện bán hàng, Skyview Scopes","qs":[{"n":155,"q":"What is the purpose of the e-mail?","qvi":"Mục đích của email là gì?","opts":["To request payment","To provide operating instructions","To advertise a new product","To offer a substitute item"],"ans":"D","xp":"Đáp án: (D)\nCăn cứ: \"Rất tiếc, mặt hàng bà yêu cầu hiện đang bị chậm đơn hàng... Nếu bà không muốn chờ đợi, chúng tôi có một mẫu kính thiên văn tương tự từ một nhà sản xuất khác\" → đề nghị sản phẩm thay thế.\n(A) Yêu cầu thanh toán\n(B) Cung cấp hướng dẫn sử dụng\n(C) Quảng cáo một sản phẩm mới\n(D) Đề nghị một sản phẩm thay thế"},{"n":156,"q":"What is mentioned about the Belter BTR-1483 telescope?","qvi":"Điều gì được đề cập về kính thiên văn Belter BTR-1483?","opts":["It can only be ordered online.","It will ship directly from the manufacturer.","It includes a protective case.","It is the most expensive telescope of its type."],"ans":"C","xp":"Đáp án: (C)\nCăn cứ: \"Ngoài ra, tất cả kính thiên văn của Belter đều bao gồm một túi đựng có lớp đệm lót (padded carrying case).\" → padded carrying case = protective case.\n(A) Chỉ có thể đặt mua trực tuyến.\n(B) Sẽ được vận chuyển trực tiếp từ nhà sản xuất.\n(C) Có kèm theo hộp bảo vệ.\n(D) Là kính thiên văn đắt nhất trong cùng loại."},{"n":157,"q":"In which of the positions marked [1], [2], [3], and [4] does the following sentence best belong?\n\"You can see a full list of specifications on our Web site.\"","qvi":"Câu sau đây nên được đặt ở vị trí nào trong các vị trí [1], [2], [3], [4]?\n\"Bạn có thể xem danh sách đầy đủ các thông số kỹ thuật trên trang web của chúng tôi.\"","opts":["[1]","[2]","[3]","[4]"],"ans":"B","xp":"Đáp án: (B)\nCăn cứ: Câu ngay trước vị trí [2] nêu các thông số của mẫu Belter BTR-1483: \"có khẩu độ 120 mm và loa che nắng có thể thu gọn\" → câu \"Bạn có thể xem danh sách đầy đủ các thông số kỹ thuật trên trang web\" nối tiếp hợp lý."}]},{"ns":[158,160],"head":"Questions 158-160 refer to the following e-mail.","passages":["<div class=\"hdr\"><p><b>To:</b> Sun-Hi Myo &lt;shmyo@sunmail.co.nz&gt;</p><p><b>From:</b> Jan Delpit &lt;jdelpit@hamerkoptech.co.nz&gt;</p><p><b>Date:</b> 8 March</p><p><b>Subject:</b> RE: Inquiry about job opening</p></div><p>Hello,</p><p>Thank you for your e-mail. I am currently on holiday and will return to the office on 15 March. I will respond to your message as soon as possible after I return.</p><p>If you require general assistance during my absence or have questions about the open position in our sales department, please contact my assistant Sita Viswan at 04 555 0193 or sviswan@hamerkoptech.co.nz. For questions about specific Hamerkoptech software products, contact the customer service department at customerservice@hamerkoptech.co.nz.</p><p>Additionally, I am happy to announce that our new graphic design software program will be released on 2 April. You can read more about the program at Hamerkoptech’s newly redesigned Web site, www.hamerkoptech.co.nz. There, you may also sign up to receive our weekly newsletter by following the instructions on the home page.</p><p>Sincerely,</p><p>Jan Delpit</p>"],"vi":"Người nhận: Sun-Hi Myo <shmyo@sunmail.co.nz>\nNgười gửi: Jan Delpit <jdelpit@hamerkoptech.co.nz>\nNgày: 8 tháng 3\nChủ đề: RE: Hỏi về vị trí công việc đang tuyển dụng\n\nXin chào,\n\nCảm ơn email của bạn. Tôi hiện đang đi nghỉ và sẽ quay trở lại văn phòng vào ngày 15 tháng 3. Tôi sẽ phản hồi tin nhắn của bạn sớm nhất có thể sau khi tôi quay lại.\n\nNếu bạn cần hỗ trợ chung trong thời gian tôi vắng mặt hoặc có thắc mắc về vị trí đang tuyển dụng trong bộ phận bán hàng của chúng tôi, vui lòng liên hệ với trợ lý của tôi, Sita Viswan, tại số điện thoại 04 555 0193 hoặc email sviswan@hamerkoptech.co.nz. Đối với các câu hỏi về các sản phẩm phần mềm cụ thể của Hamerkoptech, vui lòng liên hệ với bộ phận dịch vụ khách hàng tại customerservice@hamerkoptech.co.nz.\n\nNgoài ra, tôi rất vui mừng thông báo rằng chương trình phần mềm thiết kế đồ họa mới của chúng tôi sẽ được ra mắt vào ngày 2 tháng 4. Bạn có thể đọc thêm về chương trình này tại trang web mới được thiết kế lại của Hamerkoptech, www.hamerkoptech.co.nz. Tại đó, bạn cũng có thể đăng ký nhận bản tin hàng tuần của chúng tôi bằng cách làm theo hướng dẫn trên trang chủ.\n\nTrân trọng,\nJan Delpit","qs":[{"n":158,"q":"What is one purpose of the e-mail?","qvi":"Một mục đích của email là gì?","opts":["To explain how to use a software program","To request Ms. Myo's assistance with a project","To introduce a new staff member","To indicate that Mr. Delpit is out of the office"],"ans":"D","xp":"Đáp án: (D)\nCăn cứ: \"Tôi hiện đang đi nghỉ và sẽ quay trở lại văn phòng vào ngày 15 tháng 3.\"\n(A) Giải thích cách sử dụng một phần mềm\n(B) Yêu cầu cô Myo hỗ trợ một dự án\n(C) Giới thiệu một nhân viên mới\n(D) Thông báo rằng ông Delpit đang vắng mặt khỏi văn phòng"},{"n":159,"q":"What will happen on April 2?","qvi":"Điều gì sẽ xảy ra vào ngày 2 tháng 4?","opts":["A job opening will be filled.","A product will be launched.","A client meeting will take place.","A Web site redesign will begin."],"ans":"B","xp":"Đáp án: (B)\nCăn cứ: \"chương trình phần mềm thiết kế đồ họa mới của chúng tôi sẽ được ra mắt vào ngày 2 tháng 4.\"\n(A) Một vị trí công việc sẽ được tuyển xong\n(B) Một sản phẩm sẽ được ra mắt\n(C) Một cuộc họp với khách hàng sẽ diễn ra\n(D) Việc thiết kế lại trang web sẽ bắt đầu"},{"n":160,"q":"How can people subscribe to a newsletter?","qvi":"Mọi người có thể đăng ký nhận bản tin bằng cách nào?","opts":["By calling Ms. Viswan","By replying to Mr. Delpit's e-mail","By visiting Hamerkoptech's Web site","By contacting the customer service department"],"ans":"C","xp":"Đáp án: (C)\nCăn cứ: \"Bạn có thể đọc thêm về chương trình này tại trang web... www.hamerkoptech.co.nz. Tại đó, bạn cũng có thể đăng ký nhận bản tin hàng tuần của chúng tôi bằng cách làm theo hướng dẫn trên trang chủ.\"\n(A) Gọi điện cho cô Viswan\n(B) Trả lời email của ông Delpit\n(C) Truy cập trang web của Hamerkoptech\n(D) Liên hệ bộ phận chăm sóc khách hàng"}]},{"ns":[161,163],"head":"Questions 161-163 refer to the following article.","passages":["<h3>Vimalo Brands Enters a New Era</h3><p>By Yvette Maurer</p><p>VANCOUVER (2 August)—Vimalo Brands, the large consumer goods company that markets popular nutritional-support and personal-care products, including Powerburst breakfast drinks and Honeysoft soaps and lotions, will soon offer something new for its customers: frozen foods. “Our new Nutridinna line is not just about convenience,” CEO Danitza Martens said during a press conference earlier today. “Frozen foods are not a new concept, but our method of flash-freezing fresh produce and meats ensures that our products retain their texture and flavour as well as their healthy vitamins and minerals. Now our customers can enjoy the convenience of frozen food without sacrificing quality.”</p><p>Vimalo Brands has partnered with Vancouver-area farms to obtain produce and meat for the Nutridinna line. “By keeping our operations local, we avoid shipping delays and can flash-freeze freshly harvested vegetables at their peak of ripeness,” Martens said. “Our customers benefit further, since our products can be kept in the freezer for up to six months.” Nutridinna foods will be available in supermarkets beginning in November. Frozen fish and other seafood will be added early next year.</p>"],"vi":"Vimalo Brands Bước Sang Một Kỷ Nguyên Mới\nBởi Yvette Maurer\n\nVANCOUVER (Ngày 2 tháng 8) — Vimalo Brands, công ty hàng tiêu dùng lớn chuyên kinh doanh các sản phẩm chăm sóc cá nhân và hỗ trợ dinh dưỡng phổ biến, bao gồm đồ uống cho bữa sáng Powerburst cùng xà phòng và sữa dưỡng thể Honeysoft, sẽ sớm cung cấp một dòng sản phẩm mới cho khách hàng: thực phẩm đông lạnh. \"Dòng sản phẩm Nutridinna mới của chúng tôi không chỉ đơn thuần là sự tiện lợi,\" CEO Danitza Martens phát biểu trong một cuộc họp báo diễn ra sớm ngày hôm nay. \"Thực phẩm đông lạnh không phải là một khái niệm mới, nhưng phương pháp cấp đông nhanh nông sản và thịt tươi của chúng tôi đảm bảo rằng các sản phẩm vẫn giữ được kết cấu và hương vị cũng như các vitamin và khoáng chất có lợi cho sức khỏe. Giờ đây, khách hàng của chúng tôi có thể tận hưởng sự tiện lợi của thực phẩm đông lạnh mà không phải hy sinh chất lượng.\"\n\nVimalo Brands đã hợp tác với các trang trại ở khu vực Vancouver để thu mua nông sản và thịt cho dòng sản phẩm Nutridinna. \"Bằng cách duy trì các hoạt động tại địa phương, chúng tôi tránh được việc vận chuyển chậm trễ và có thể cấp đông nhanh các loại rau củ vừa thu hoạch ở thời điểm chín muồi nhất,\" bà Martens cho biết. \"Khách hàng của chúng tôi còn được hưởng lợi thêm vì các sản phẩm có thể được bảo quản trong ngăn đá lên đến sáu tháng.\" Thực phẩm Nutridinna sẽ có mặt tại các siêu thị bắt đầu từ tháng 11. Cá và các loại hải sản đông lạnh khác sẽ được bổ sung vào đầu năm tới.","qs":[{"n":161,"q":"What is one purpose of the article?","qvi":"Mục đích của bài viết là gì?","opts":["To discuss a cooking technique","To report on a corporate merger","To announce a new product line","To introduce a recently hired executive"],"ans":"C","xp":"Đáp án: (C)\nCăn cứ: \"Vimalo Brands... sẽ sớm cung cấp một dòng sản phẩm mới cho khách hàng: thực phẩm đông lạnh.\"\n(A) Thảo luận về một kỹ thuật nấu ăn\n(B) Báo cáo về một vụ sáp nhập doanh nghiệp\n(C) Thông báo về một dòng sản phẩm mới\n(D) Giới thiệu một giám đốc điều hành mới được tuyển dụng"},{"n":162,"q":"The word \"just\" in paragraph 1, line 8, is closest in meaning to","qvi":"Từ \"just\" ở đoạn 1, dòng 8, gần nghĩa nhất với từ nào?","opts":["recently","exactly","slightly","only"],"ans":"D","xp":"Đáp án: (D)\nCăn cứ: \"Our new Nutridinna line is not just about convenience\" = \"Dòng sản phẩm Nutridinna mới của chúng tôi không chỉ đơn thuần là sự tiện lợi\" → just = only (chỉ).\n(A) Gần đây\n(B) Chính xác\n(C) Hơi / một chút\n(D) Chỉ"},{"n":163,"q":"What does Ms. Martens suggest about flash-frozen food?","qvi":"Bà Martens gợi ý điều gì về thực phẩm đông lạnh nhanh?","opts":["It is less expensive than fresh food.","It is as nutritious as fresh food.","It is as easy to ship as fresh food.","It is less flavorful than fresh food."],"ans":"B","xp":"Đáp án: (B)\nCăn cứ: \"phương pháp cấp đông nhanh nông sản và thịt tươi của chúng tôi đảm bảo rằng các sản phẩm vẫn giữ được kết cấu và hương vị cũng như các vitamin và khoáng chất có lợi cho sức khỏe\" → giàu dinh dưỡng như thực phẩm tươi.\n(A) Rẻ hơn thực phẩm tươi\n(B) Có giá trị dinh dưỡng tương đương thực phẩm tươi\n(C) Dễ vận chuyển như thực phẩm tươi\n(D) Ít hương vị hơn thực phẩm tươi"}]},{"ns":[164,167],"head":"Questions 164-167 refer to the following advertisement.","passages":["<p>Are you ready to work hard as part of a team of like-minded individuals? Are you willing to put your education, your experience, and your imagination to great use? If so, then we have the job for you. Karning Creative Designs is expanding, and with our success comes your opportunity.</p><p>Karning Creative Designs began ten years ago as a two-person operation set up in the home of our current CEO and founder Shirin Navani. Now located in a beautiful loft in downtown Hollinson, our firm currently employs 25 full-time staff members. At Karning, we design paper-based brochures, catalogs, ads, and posters for our clients. We are currently seeking qualified designers and artists who will shine in a fast-paced, collaborative environment.</p><h4>The ideal candidate</h4><ul><li>Holds a degree in design, advertising, or graphic art—although several years of direct experience may substitute for a degree</li><li>Demonstrates a strong ability to work closely with colleagues</li><li>Maintains a critical eye for detail and precision</li><li>Consistently meets deadlines and can flourish under pressure</li></ul><p>Graphic design or related experience is a plus but not strictly necessary.</p><p>If you are ready to join our team, we want to meet you! Contact Salvador Tomassin at 608-555-0144 for further details. All applications must be received by March 31.</p>"],"vi":"Bạn đã sẵn sàng làm việc chăm chỉ trong một đội ngũ gồm những cá nhân cùng chí hướng chưa? Bạn có sẵn lòng vận dụng kiến thức, kinh nghiệm và trí tưởng tượng của mình một cách hiệu quả nhất không? Nếu có, chúng tôi có công việc dành cho bạn. Karning Creative Designs đang mở rộng, và cùng với sự thành công của chúng tôi là cơ hội dành cho bạn.\n\nKarning Creative Designs bắt đầu từ mười năm trước với quy mô hoạt động chỉ hai người, được thiết lập ngay tại nhà của CEO kiêm người sáng lập hiện tại, Shirin Navani. Hiện nay, đặt tại một căn hộ cao cấp (loft) tuyệt đẹp ở trung tâm thành phố Hollinson, công ty chúng tôi đang sở hữu 25 nhân viên toàn thời gian. Tại Karning, chúng tôi thiết kế các loại tờ gấp (brochure), danh mục sản phẩm (catalog), quảng cáo và áp phích trên chất liệu giấy cho khách hàng. Chúng tôi hiện đang tìm kiếm những nhà thiết kế và nghệ sĩ có năng lực, những người sẽ tỏa sáng trong một môi trường cộng tác với nhịp độ nhanh.\n\nỨng viên lý tưởng\n• Có bằng cấp về thiết kế, quảng cáo hoặc nghệ thuật đồ họa — mặc dù vài năm kinh nghiệm trực tiếp có thể thay thế cho bằng cấp.\n• Thể hiện khả năng làm việc chặt chẽ với các đồng nghiệp.\n• Duy trì cái nhìn khắt khe về chi tiết và sự chính xác.\n• Luôn hoàn thành đúng hạn và có thể phát triển tốt dưới áp lực.\n\nKinh nghiệm về thiết kế đồ họa hoặc các lĩnh vực liên quan là một điểm cộng nhưng không bắt buộc.\n\nNếu bạn đã sẵn sàng gia nhập đội ngũ của chúng tôi, chúng tôi muốn gặp bạn! Hãy liên hệ với Salvador Tomassin tại số 608-555-0144 để biết thêm chi tiết. Tất cả hồ sơ ứng tuyển phải được gửi trước ngày 31 tháng 3.","qs":[{"n":164,"q":"According to the advertisement, who most likely is Ms. Navani?","qvi":"Theo quảng cáo, bà Navani có khả năng cao là ai?","opts":["A Karning Creative Designs client","A business owner","A photographer","A real estate agent"],"ans":"B","xp":"Đáp án: (B)\nCăn cứ: \"Karning Creative Designs bắt đầu từ mười năm trước... tại nhà của CEO kiêm người sáng lập hiện tại, Shirin Navani.\" → bà là chủ doanh nghiệp.\n(A) Một khách hàng của Karning Creative Designs\n(B) Một chủ doanh nghiệp\n(C) Một nhiếp ảnh gia\n(D) Một nhân viên môi giới bất động sản"},{"n":165,"q":"What is indicated about Karning Creative Designs?","qvi":"Điều gì được đề cập về Karning Creative Designs?","opts":["Its primary focus is Web design.","It initially employed two people.","It was founded by Mr. Tomassin.","Its staff are permitted to work from home."],"ans":"B","xp":"Đáp án: (B)\nCăn cứ: \"Karning Creative Designs bắt đầu từ mười năm trước với quy mô hoạt động chỉ hai người (a two-person operation)\".\n(A) Trọng tâm chính của công ty là thiết kế web\n(B) Ban đầu công ty có hai nhân viên\n(C) Công ty được thành lập bởi ông Tomassin\n(D) Nhân viên được phép làm việc tại nhà"},{"n":166,"q":"What is required of job applicants?","qvi":"Ứng viên xin việc cần đáp ứng yêu cầu gì?","opts":["Skill in working with others","Previous design experience","A willingness to work on weekends","An ability to use certain software applications"],"ans":"A","xp":"Đáp án: (A)\nCăn cứ: \"Thể hiện khả năng làm việc chặt chẽ với các đồng nghiệp (Demonstrates a strong ability to work closely with colleagues).\" (Kinh nghiệm thiết kế chỉ là điểm cộng, không bắt buộc → loại B.)\n(A) Có kỹ năng làm việc nhóm\n(B) Có kinh nghiệm thiết kế trước đó\n(C) Sẵn sàng làm việc vào cuối tuần\n(D) Có khả năng sử dụng một số phần mềm nhất định"},{"n":167,"q":"What will happen on March 31?","qvi":"Điều gì sẽ xảy ra vào ngày 31 tháng 3?","opts":["A project will begin.","A deadline will occur.","A graphic designer will relocate.","An application form will be made available."],"ans":"B","xp":"Đáp án: (B)\nCăn cứ: \"Tất cả hồ sơ ứng tuyển phải được gửi trước ngày 31 tháng 3.\" → hạn chót nộp hồ sơ.\n(A) Một dự án sẽ bắt đầu\n(B) Một hạn chót sẽ diễn ra\n(C) Một nhà thiết kế đồ họa sẽ chuyển nơi làm việc\n(D) Mẫu đơn đăng ký sẽ được công bố"}]},{"ns":[168,171],"head":"Questions 168-171 refer to the following article.","passages":["<p>NEW HAVEN (June 1)—Marco’s Italian Restaurant on Frontage Road will be reopening in late June. It closed three months ago after a water leak caused extensive damage to the kitchen. A significant amount of work needed to be done in the kitchen and dining areas. — <span class=\"pos\">[1]</span> —. The restaurant will accommodate larger parties when it reopens.</p><p>During the past three months, many of the restaurant’s employees were able to work at Marco’s Italian Market, which is located on the opposite side of the street. — <span class=\"pos\">[2]</span> —. “The leak happened right before the market’s busy season started,” said Tom Marco, who owns both businesses. “We needed to add staff there temporarily, and I was happy to keep my restaurant crew employed.” Most of those employees have now returned to work in the restaurant. — <span class=\"pos\">[3]</span> —.</p><p>Mr. Marco has planned a grand reopening for June 25. Guests will enjoy live music and a new tasting menu. — <span class=\"pos\">[4]</span> —. Reservations are required for the day of the celebration and can be made by calling 203-555-0124. “We are excited to be able to prepare our traditional dishes and welcome the community back again,” stated Mr. Marco.</p>"],"vi":"NEW HAVEN (Ngày 1 tháng 6) — Nhà hàng Ý Marco’s trên đường Frontage sẽ mở cửa trở lại vào cuối tháng 6. Nhà hàng đã đóng cửa ba tháng trước sau khi một sự cố rò rỉ nước gây ra hư hại trên diện rộng cho khu vực bếp. Một khối lượng công việc đáng kể cần phải thực hiện ở cả khu vực bếp và khu vực ăn uống. — [1] —. Nhà hàng sẽ có thể phục vụ các nhóm khách lớn hơn khi mở cửa trở lại.\n\nTrong ba tháng qua, nhiều nhân viên của nhà hàng đã có thể làm việc tại Chợ Ý Marco’s, nằm ở phía đối diện của con phố. — [2] —. “Sự cố rò rỉ xảy ra ngay trước khi mùa cao điểm của khu chợ bắt đầu,” ông Tom Marco, chủ sở hữu của cả hai cơ sở kinh doanh, cho biết. “Chúng tôi cần thêm nhân viên tạm thời ở đó, và tôi rất vui khi vẫn có thể duy trì việc làm cho đội ngũ nhân viên nhà hàng của mình.” Hầu hết những nhân viên đó hiện đã quay trở lại làm việc tại nhà hàng. — [3] —.\n\nÔng Marco đã lên kế hoạch cho một buổi đại lễ khai trương trở lại vào ngày 25 tháng 6. Khách mời sẽ được thưởng thức nhạc sống và một thực đơn dùng thử mới. — [4] —. Yêu cầu phải đặt chỗ trước cho ngày lễ kỷ niệm và có thể thực hiện bằng cách gọi số 203-555-0124. “Chúng tôi rất hào hứng khi có thể chuẩn bị những món ăn truyền thống của mình và chào đón cộng đồng quay trở lại một lần nữa,” ông Marco phát biểu.","qs":[{"n":168,"q":"What does the article mention about Marco's Italian Restaurant?","qvi":"Bài viết đề cập điều gì về Nhà hàng Ý Marco?","opts":["It is the oldest restaurant in New Haven.","It is looking for a chef who can cook traditional dishes.","It needed major renovations.","It opened in a new location."],"ans":"C","xp":"Đáp án: (C)\nCăn cứ: \"Nhà hàng đã đóng cửa ba tháng trước sau khi một sự cố rò rỉ nước gây ra hư hại trên diện rộng cho khu vực bếp. Một khối lượng công việc đáng kể cần phải thực hiện...\" → cần cải tạo lớn.\n(A) Đây là nhà hàng lâu đời nhất ở New Haven.\n(B) Nhà hàng đang tìm một đầu bếp có thể nấu các món truyền thống.\n(C) Nhà hàng đã cần được cải tạo lớn.\n(D) Nhà hàng đã mở tại một địa điểm mới."},{"n":169,"q":"What is indicated about Marco's Italian Market?","qvi":"Điều gì được cho biết về Marco’s Italian Market?","opts":["It supplies ingredients to Marco's Italian Restaurant.","It occasionally hires temporary workers.","It is scheduled to close in three months.","It is located next door to Marco's Italian Restaurant."],"ans":"B","xp":"Đáp án: (B)\nCăn cứ: \"Chúng tôi cần thêm nhân viên tạm thời ở đó (We needed to add staff there temporarily)\" → khu chợ có lúc thuê nhân viên tạm thời. (Chợ nằm ở phía đối diện con phố, không phải ngay cạnh → loại D.)\n(A) Cung cấp nguyên liệu cho Nhà hàng Ý Marco.\n(B) Thỉnh thoảng thuê nhân viên thời vụ.\n(C) Dự kiến sẽ đóng cửa trong ba tháng tới.\n(D) Nằm ngay cạnh Nhà hàng Ý Marco."},{"n":170,"q":"What will happen during the event on June 25?","qvi":"Điều gì sẽ diễn ra trong sự kiện vào ngày 25 tháng 6?","opts":["The restaurant will reduce its menu prices.","The restaurant will offer special menu items.","Mr. Marco will celebrate his retirement.","The New Haven business community will honor Mr. Marco."],"ans":"B","xp":"Đáp án: (B)\nCăn cứ: \"Ông Marco đã lên kế hoạch cho một buổi đại lễ khai trương trở lại vào ngày 25 tháng 6. Khách mời sẽ được thưởng thức nhạc sống và một thực đơn dùng thử mới (a new tasting menu).\"\n(A) Nhà hàng sẽ giảm giá thực đơn.\n(B) Nhà hàng sẽ giới thiệu các món ăn đặc biệt.\n(C) Ông Marco sẽ tổ chức lễ nghỉ hưu.\n(D) Cộng đồng doanh nghiệp New Haven sẽ vinh danh ông Marco."},{"n":171,"q":"In which of the positions marked [1], [2], [3], and [4] does the following sentence best belong?\n\"During repairs, some additional dining space was added.\"","qvi":"Câu sau nên được đặt ở vị trí nào trong các vị trí [1], [2], [3], và [4]?\n\"Trong quá trình sửa chữa, một số không gian ăn uống bổ sung đã được thêm vào.\"","opts":["[1]","[2]","[3]","[4]"],"ans":"A","xp":"Đáp án: (A)\nCăn cứ: Trước [1]: \"Một khối lượng công việc đáng kể cần phải thực hiện ở cả khu vực bếp và khu vực ăn uống.\" Sau [1]: \"Nhà hàng sẽ có thể phục vụ các nhóm khách lớn hơn khi mở cửa trở lại.\" → thêm không gian ăn uống giải thích vì sao phục vụ được nhóm khách lớn hơn."}]},{"ns":[172,175],"head":"Questions 172-175 refer to the following online chat discussion.","passages":["<div class=\"msg\"><p><b>Marlys Barry (10:17 A.M.)</b></p><p>This is Ms. Barry from the data analysis department. I have included my colleague, Ms. Choi. We’re contacting you about your data request for the e-mail addresses of all account holders, sorted by age.</p></div><div class=\"msg\"><p><b>Alexander Kubelski (10:17 A.M.)</b></p><p>Yes, how soon can you complete the request?</p></div><div class=\"msg\"><p><b>Marlys Barry (10:18 A.M.)</b></p><p>I have a question for you first. Do you really need the e-mail addresses of all account holders? That would be a huge file. Or do you need the e-mail addresses of account holders only within a certain age-group?</p></div><div class=\"msg\"><p><b>Alexander Kubelski (10:19 A.M.)</b></p><p>I see what you mean. I want to e-mail account holders aged 55 to 65 to invite them to meet with a retirement planning expert. Do I have to submit a new project request form?</p></div><div class=\"msg\"><p><b>Bora Choi (10:21 A.M.)</b></p><p>That’s not necessary, Mr. Kubelski. We can update your current request form for you. You do not want to lose your place in the queue.</p></div><div class=\"msg\"><p><b>Alexander Kubelski (10:21 A.M.)</b></p><p>Great, thank you! Is it possible for you to get me that list right away?</p></div><div class=\"msg\"><p><b>Marlys Barry (10:22 A.M.)</b></p><p>There are several projects ahead of yours.</p></div><div class=\"msg\"><p><b>Alexander Kubelski (10:23 A.M.)</b></p><p>I was hoping to send out the e-mail invitations tomorrow.</p></div><div class=\"msg\"><p><b>Marlys Barry (10:24 A.M.)</b></p><p>We will get to it as soon as we can.</p></div>"],"vi":"Marlys Barry (10:17 sáng): Tôi là cô Barry từ bộ phận phân tích dữ liệu. Tôi đã thêm đồng nghiệp của mình là cô Choi vào cuộc trò chuyện. Chúng tôi liên hệ với ông về yêu cầu dữ liệu địa chỉ email của tất cả các chủ tài khoản, được phân loại theo độ tuổi.\n\nAlexander Kubelski (10:17 sáng): Vâng, các bạn có thể hoàn thành yêu cầu này sớm nhất là khi nào?\n\nMarlys Barry (10:18 sáng): Trước tiên tôi có một câu hỏi cho ông. Ông có thực sự cần địa chỉ email của tất cả các chủ tài khoản không? Đó sẽ là một tệp dữ liệu khổng lồ. Hay ông chỉ cần địa chỉ email của các chủ tài khoản trong một nhóm tuổi nhất định?\n\nAlexander Kubelski (10:19 sáng): Tôi hiểu ý cô. Tôi muốn gửi email cho các chủ tài khoản từ 55 đến 65 tuổi để mời họ gặp gỡ chuyên gia lập kế hoạch nghỉ hưu. Tôi có phải gửi một mẫu yêu cầu dự án mới không?\n\nBora Choi (10:21 sáng): Việc đó không cần thiết đâu, ông Kubelski. Chúng tôi có thể cập nhật mẫu yêu cầu hiện tại cho ông. Ông chắc hẳn không muốn mất vị trí của mình trong hàng đợi yêu cầu đâu.\n\nAlexander Kubelski (10:21 sáng): Tuyệt quá, cảm ơn cô! Liệu các cô có thể gửi cho tôi danh sách đó ngay lập tức được không?\n\nMarlys Barry (10:22 sáng): Hiện có vài dự án đang xếp hàng trước yêu cầu của ông.\n\nAlexander Kubelski (10:23 sáng): Tôi đã hy vọng có thể gửi email mời vào ngày mai.\n\nMarlys Barry (10:24 sáng): Chúng tôi sẽ xử lý ngay khi có thể.","qs":[{"n":172,"q":"Why did Ms. Barry begin an online chat with Mr. Kubelski?","qvi":"Vì sao cô Barry bắt đầu cuộc trò chuyện trực tuyến với ông Kubelski?","opts":["To refer him to a different department","To decline an invitation","To issue an apology","To ask for clarification about a request"],"ans":"D","xp":"Đáp án: (D)\nCăn cứ: \"Chúng tôi liên hệ với ông về yêu cầu dữ liệu địa chỉ email của tất cả các chủ tài khoản...\" và \"Trước tiên tôi có một câu hỏi cho ông. Ông có thực sự cần địa chỉ email của tất cả các chủ tài khoản không?\" → hỏi rõ về yêu cầu.\n(A) Để giới thiệu ông ấy sang một bộ phận khác\n(B) Để từ chối một lời mời\n(C) Để đưa ra lời xin lỗi\n(D) Để hỏi rõ hơn về một yêu cầu"},{"n":173,"q":"Who will receive an e-mail from Mr. Kubelski?","qvi":"Ai sẽ nhận được email từ ông Kubelski?","opts":["Account holders in one age-group","Data analysis team members","Financial planners","All Mr. Kubelski's clients"],"ans":"A","xp":"Đáp án: (A)\nCăn cứ: \"Tôi muốn gửi email cho các chủ tài khoản từ 55 đến 65 tuổi để mời họ gặp gỡ chuyên gia lập kế hoạch nghỉ hưu.\"\n(A) Những người có tài khoản trong cùng một nhóm tuổi\n(B) Các thành viên của nhóm phân tích dữ liệu\n(C) Các chuyên viên tư vấn tài chính\n(D) Tất cả khách hàng của ông Kubelski"},{"n":174,"q":"What does Ms. Choi offer to do?","qvi":"Cô Choi đề nghị làm gì?","opts":["Write an e-mail","Make a change to a form","Open an account","Revise a policy"],"ans":"B","xp":"Đáp án: (B)\nCăn cứ: \"Chúng tôi có thể cập nhật mẫu yêu cầu hiện tại cho ông (We can update your current request form for you).\"\n(A) Viết một email\n(B) Chỉnh sửa một biểu mẫu\n(C) Mở một tài khoản\n(D) Sửa đổi một chính sách"},{"n":175,"q":"At 10:22 A.M., what does Ms. Barry most likely mean when she writes, \"There are several projects ahead of yours\"?","qvi":"Vào lúc 10:22 sáng, khi cô Barry viết \"There are several projects ahead of yours\" (Có một vài dự án đang xếp trước của ông), cô ấy có ý gì?","opts":["Ms. Barry will move Mr. Kubelski's request to the end of the queue.","Ms. Barry will not be able to send out the invitations for Mr. Kubelski.","Mr. Kubelski's request will not be the first job Ms. Barry completes.","Mr. Kubelski will need to assist with other projects first."],"ans":"C","xp":"Đáp án: (C)\nCăn cứ: Ông Kubelski hỏi: \"Liệu các cô có thể gửi cho tôi danh sách đó ngay lập tức được không?\" → \"Hiện có vài dự án đang xếp hàng trước yêu cầu của ông.\" → yêu cầu của ông chưa được xử lý ngay, phải chờ các dự án trước.\n(A) Cô Barry sẽ đưa yêu cầu của ông Kubelski xuống cuối danh sách xử lý\n(B) Cô Barry sẽ không thể gửi lời mời thay cho ông Kubelski\n(C) Yêu cầu của ông Kubelski sẽ không phải là công việc đầu tiên cô Barry thực hiện\n(D) Ông Kubelski sẽ cần hỗ trợ các dự án khác trước"}]},{"ns":[176,180],"head":"Questions 176-180 refer to the following article and e-mail.","passages":["<h3><i>Tips for designing a Web site for a food-truck business</i></h3><p>Owners of food trucks move from place to place, within and between cities, as they carry out their business, so they often rely on word of mouth or social media to attract customers. As a result, they may not build a Web site of their own. But in fact, by the very nature of their business, it is crucial that food truck owners have a fixed place for the public to learn about them, order from them, contact them, etc. Furthermore, market research shows that a Web site can help build a loyal customer base. So, here are some tips for developing a great Web site for your food truck.</p><p>The Home page should have bold graphics with your food truck's name. The text must prominently display key information, such as your truck's locations and operating hours. Online forms with fields to fill out, such as reservation requests for special events or services, give new visitors too much visual information. They are better incorporated as links or pop-up windows.</p><p>The Food Menu page needs attractive, high-definition images along with vivid and precise text that describes each menu item in detail. Remember that your photos should be big enough to look appealing on larger computer monitors.</p><p>The About Us page should include some text explaining your food truck's theme and concept, and some biographical data detailing your background in the food industry.</p><p>The News page can include text informing visitors about seasonal food items and upcoming promotions or special events such as food festivals.</p>","<div class=\"hdr\"><p><b>To:</b> Doug Abruzzo &lt;dabruzzo@dzacreative.com&gt;</p><p><b>From:</b> Ed Vale &lt;evale@saffronmail.com&gt;</p><p><b>Date:</b> March 29</p><p><b>Subject:</b> Feedback</p></div><p>Dear Mr. Abruzzo,</p><p>Thank you again for creating the prototype Web site for my food-truck business. I just wanted to reiterate that it has gotten positive feedback from customers who have tested it. I am so glad we followed the advice in that article you sent me about Web site design for food trucks!</p><p>As we discussed in our phone call yesterday, we will move forward with the prototype Web site and launch it as the official site on April 5. However, I still do not see the information I sent about our new promotion that will begin in mid-April, a free dessert with any sandwich purchase. Please be sure to add this important information before we launch the site.</p><p>Regards,</p><p>Ed</p>"],"vi":"BÀI BÁO\nCác mẹo thiết kế trang web cho doanh nghiệp xe đồ ăn lưu động\n\nChủ sở hữu các xe đồ ăn lưu động thường di chuyển từ nơi này sang nơi khác, trong phạm vi một thành phố hoặc giữa các thành phố khác nhau khi họ kinh doanh, vì vậy họ thường dựa vào truyền miệng hoặc mạng xã hội để thu hút khách hàng. Kết quả là, họ có thể không xây dựng một trang web riêng cho mình. Tuy nhiên, thực tế là do bản chất của loại hình kinh doanh này, việc chủ xe đồ ăn có một địa điểm cố định để công chúng tìm hiểu về họ, đặt hàng, liên hệ, v.v. là vô cùng quan trọng. Hơn nữa, nghiên cứu thị trường cho thấy một trang web có thể giúp xây dựng một lượng khách hàng trung thành. Vì vậy, đây là một số mẹo để phát triển một trang web tuyệt vời cho xe đồ ăn của bạn.\n\nTrang chủ (Home page) nên có đồ họa táo bạo cùng với tên xe đồ ăn của bạn. Văn bản phải hiển thị nổi bật các thông tin chính, chẳng hạn như địa điểm xe đậu và giờ hoạt động. Các biểu mẫu trực tuyến với các ô trống để điền vào, như yêu cầu đặt chỗ cho các sự kiện hoặc dịch vụ đặc biệt, thường cung cấp quá nhiều thông tin thị giác cho khách truy cập mới. Tốt hơn là nên kết hợp chúng dưới dạng các liên kết hoặc cửa sổ bật lên (pop-up).\n\nTrang Thực đơn (Food Menu) cần những hình ảnh hấp dẫn, độ phân giải cao cùng với văn bản sinh động và chính xác mô tả chi tiết từng món trong thực đơn. Hãy nhớ rằng ảnh của bạn nên đủ lớn để trông bắt mắt trên các màn hình máy tính lớn hơn.\n\nTrang Về chúng tôi (About Us) nên bao gồm một số văn bản giải thích về chủ đề và khái niệm của xe đồ ăn, cùng một số dữ liệu tiểu sử chi tiết về kinh nghiệm của bạn trong ngành thực phẩm.\n\nTrang Tin tức (News) có thể bao gồm văn bản thông báo cho khách truy cập về các món ăn theo mùa và các chương trình khuyến mãi sắp tới hoặc các sự kiện đặc biệt như lễ hội ẩm thực.\n\nEMAIL\nNgười nhận: Doug Abruzzo <dabruzzo@dzacreative.com>\nNgười gửi: Ed Vale <evale@saffronmail.com>\nNgày: 29 tháng 3\nChủ đề: Phản hồi\n\nThưa ông Abruzzo,\n\nCảm ơn ông một lần nữa vì đã tạo ra trang web mẫu cho doanh nghiệp xe đồ ăn lưu động của tôi. Tôi chỉ muốn nhắc lại rằng nó đã nhận được những phản hồi tích cực từ những khách hàng đã dùng thử. Tôi rất vui vì chúng ta đã làm theo lời khuyên trong bài báo mà ông đã gửi cho tôi về thiết kế trang web cho xe đồ ăn!\n\nNhư chúng ta đã thảo luận trong cuộc điện thoại ngày hôm qua, chúng tôi sẽ tiến hành với trang web mẫu này và chính thức ra mắt vào ngày 5 tháng 4. Tuy nhiên, tôi vẫn chưa thấy thông tin tôi đã gửi về chương trình khuyến mãi mới sẽ bắt đầu vào giữa tháng 4: tặng một món tráng miệng miễn phí khi mua bất kỳ loại bánh sandwich nào. Vui lòng đảm bảo thêm thông tin quan trọng này trước khi chúng ta ra mắt trang web.\n\nTrân trọng,\nEd","qs":[{"n":176,"q":"According to the article, what is one way that food truck owners traditionally attract customers?","qvi":"Theo bài viết, một cách truyền thống mà các chủ xe bán đồ ăn thu hút khách hàng là gì?","opts":["By word of mouth","From highway billboards","Through newspaper advertisements","From signs at food festivals"],"ans":"A","xp":"Đáp án: (A)\nCăn cứ: Bài báo, đoạn 1: \"they often rely on word of mouth or social media to attract customers\" (họ thường dựa vào truyền miệng hoặc mạng xã hội để thu hút khách hàng).\n(A) Truyền miệng\n(B) Qua bảng quảng cáo trên đường cao tốc\n(C) Thông qua quảng cáo trên báo\n(D) Từ các biển hiệu tại lễ hội ẩm thực"},{"n":177,"q":"According to the article, what information does not need to appear on the Home page?","qvi":"Theo bài viết, thông tin nào không cần xuất hiện trên trang chủ?","opts":["Truck locations","Hours of operation","Company name","Seasonal food items"],"ans":"D","xp":"Đáp án: (D)\nCăn cứ: Bài báo, đoạn 2: Trang chủ cần tên xe (C), địa điểm (A) và giờ hoạt động (B). Món ăn theo mùa (seasonal food items) thuộc trang News (đoạn 5), không cần ở trang chủ.\n(A) Địa điểm của xe bán đồ ăn\n(B) Giờ hoạt động\n(C) Tên công ty\n(D) Các món ăn theo mùa"},{"n":178,"q":"In what field does Mr. Abruzzo most likely work?","qvi":"Ông Abruzzo có khả năng làm việc trong lĩnh vực nào?","opts":["Market research","Catering","Web design","Package delivery"],"ans":"C","xp":"Đáp án: (C)\nCăn cứ: Email: \"Thank you again for creating the prototype Web site for my food-truck business.\" (Cảm ơn ông một lần nữa vì đã tạo ra trang web mẫu...) → ông Abruzzo làm thiết kế web.\n(A) Nghiên cứu thị trường\n(B) Dịch vụ ăn uống\n(C) Thiết kế website\n(D) Giao hàng"},{"n":179,"q":"In which section of the Web site will information most likely be added?","qvi":"Thông tin nhiều khả năng sẽ được thêm vào phần nào của trang web?","opts":["The Home page","The Food Menu page","The About Us page","The News page"],"ans":"D","xp":"Đáp án: (D)\nCăn cứ: Kết hợp 2 bài: Email: \"I still do not see the information I sent about our new promotion... Please be sure to add this\" (thông tin khuyến mãi mới cần được thêm). Bài báo: \"The News page can include text informing visitors about ... upcoming promotions\" → thông tin sẽ được thêm vào trang News.\n(A) Trang chủ\n(B) Trang thực đơn\n(C) Trang Giới thiệu\n(D) Trang Tin tức"},{"n":180,"q":"According to the e-mail, when will the Web site launch?","qvi":"Theo email, khi nào trang web sẽ được ra mắt?","opts":["On March 28","On March 29","On April 5","On April 15"],"ans":"C","xp":"Đáp án: (C)\nCăn cứ: Email: \"we will move forward with the prototype Web site and launch it as the official site on April 5\" (chính thức ra mắt vào ngày 5 tháng 4).\n(A) Ngày 28 tháng 3\n(B) Ngày 29 tháng 3\n(C) Ngày 5 tháng 4\n(D) Ngày 15 tháng 4"}]},{"ns":[181,185],"head":"Questions 181-185 refer to the following e-mail and press release.","passages":["<div class=\"hdr\"><p><b>To:</b> Manny Green &lt;mgreen@rhba.com&gt;</p><p><b>From:</b> John LaRose &lt;jlarose@rilamore.edu&gt;</p><p><b>Date:</b> May 18</p><p><b>Subject:</b> Drilling notice</p></div><p>Dear Mr. Green:</p><p>As a courtesy, I am writing to you at the Red Hills Business Association, asking you to help me get the word out to your membership. It was announced in last month's <i>Daily Gazette</i> that Rilamore University is moving forward with its Net Zero Initiative. Within three years, we expect to have geothermal wells installed and operational for the heating and cooling of our entire campus. Limiting the institution's reliance on fossil fuels has long been a goal, and the new system is a significant step toward achieving that goal.</p><p>Over the next month, we will conduct test drilling in several campus locations. If all goes according to schedule, the crew will be drilling adjacent to the Red Hills Business District and Oak Street Apartments starting Wednesday, June 5. We want to tell business owners and residents near the campus to expect a higher-than-usual noise level during the two weeks we estimate it will take to complete the work. The work hours for the drilling crew are 10 A.M. to 3 P.M. each day, Monday through Friday.</p><p>We apologize in advance for the inconvenience this may cause to our neighbors. Any questions or concerns should be directed to me at 813-555-0123.</p><p>John LaRose<br>Community Liaison, Rilamore University Office of Communications</p>","<p><b>FOR IMMEDIATE RELEASE</b></p><p><b>Contact:</b> Manny Green, mgreen@rhba.com</p><p>RED HILLS (May 25)—The Red Hills Business Association is shifting the dates of its much-anticipated Lunch Hour Concert Series. Normally presented each Thursday in June, the four free concerts will instead take place each Thursday in July. The lineup of artists remains unchanged—the Jaystone Jazz Trio will open the series on July 4, followed on successive Thursdays by Joss and the Jaybirds, Ray Starform, and the Barklay Bass Quintet.</p><p>As usual, all three blocks of Oak Street will be closed to traffic, restaurants will serve lunch at outdoor tables, and local arts-and-crafts vendors will display their work on the lawn of the Cultural Center. It is a beautiful celebration in the heart of a popular Red Hills neighborhood. We hope to see you there!</p>"],"vi":"EMAIL\nNgười nhận: Manny Green <mgreen@rhba.com>\nNgười gửi: John LaRose <jlarose@rilamore.edu>\nNgày: 18 tháng 5\nChủ đề: Thông báo về việc khoan\n\nThưa ông Green,\n\nVới tư cách là một lời chào xã giao, tôi viết thư này gửi tới ông tại Hiệp hội Doanh nghiệp Red Hills để nhờ ông giúp tôi thông báo rộng rãi đến các thành viên của hiệp hội. Tờ Daily Gazette tháng trước đã đưa tin rằng Đại học Rilamore đang tiến hành Sáng kiến Net Zero (Phát thải ròng bằng không). Trong vòng ba năm tới, chúng tôi dự kiến sẽ lắp đặt và vận hành các giếng địa nhiệt để sưởi ấm và làm mát cho toàn bộ khuôn viên trường. Việc hạn chế sự phụ thuộc của tổ chức vào nhiên liệu hóa thạch từ lâu đã là một mục tiêu, và hệ thống mới này là một bước tiến đáng kể hướng tới việc đạt được mục tiêu đó.\n\nTrong tháng tới, chúng tôi sẽ tiến hành khoan thử nghiệm tại một số vị trí trong khuôn viên trường. Nếu mọi việc diễn ra theo đúng kế hoạch, đội thi công sẽ bắt đầu khoan tại khu vực giáp ranh với Khu Kinh doanh Red Hills và Chung cư Oak Street từ thứ Tư, ngày 5 tháng 6. Chúng tôi muốn thông báo cho các chủ doanh nghiệp và cư dân gần trường để họ chuẩn bị cho mức độ tiếng ồn cao hơn bình thường trong vòng hai tuần mà chúng tôi ước tính để hoàn thành công việc. Thời gian làm việc của đội khoan là từ 10 giờ sáng đến 3 giờ chiều mỗi ngày, từ thứ Hai đến thứ Sáu.\n\nChúng tôi xin lỗi trước vì sự bất tiện này có thể gây ra cho những người hàng xóm của mình. Mọi thắc mắc hoặc lo ngại xin vui lòng liên hệ trực tiếp với tôi theo số 813-555-0123.\n\nJohn LaRose\nLiên lạc viên Cộng đồng, Văn phòng Truyền thông Đại học Rilamore\n\nTHÔNG CÁO BÁO CHÍ\nTHÔNG TIN CÔNG BỐ NGAY LẬP TỨC\nLiên hệ: Manny Green, mgreen@rhba.com\n\nRED HILLS (Ngày 25 tháng 5) — Hiệp hội Doanh nghiệp Red Hills đang thay đổi ngày tổ chức Chuỗi Hòa nhạc Giờ trưa (Lunch Hour Concert Series) rất được mong đợi của mình. Thay vì được tổ chức vào mỗi thứ Năm trong tháng Sáu như thường lệ, bốn buổi hòa nhạc miễn phí này sẽ diễn ra vào mỗi thứ Năm trong tháng Bảy. Danh sách các nghệ sĩ biểu diễn vẫn không thay đổi — nhóm Jaystone Jazz Trio sẽ mở màn chuỗi chương trình vào ngày 4 tháng 7, tiếp theo vào các thứ Năm kế tiếp là Joss and the Jaybirds, Ray Starform, và Barklay Bass Quintet.\n\nNhư thường lệ, cả ba dãy phố của đường Oak Street sẽ cấm các phương tiện giao thông qua lại, các nhà hàng sẽ phục vụ bữa trưa tại các bàn ngoài trời, và các đơn vị bán hàng thủ công mỹ nghệ địa phương sẽ trưng bày sản phẩm của họ trên thảm cỏ của Trung tâm Văn hóa. Đây là một lễ hội tuyệt vời ngay tại trung tâm của khu dân cư Red Hills sầm uất. Chúng tôi hy vọng sẽ được gặp các bạn ở đó!","qs":[{"n":181,"q":"What is indicated about the Net Zero Initiative?","qvi":"Điều gì được đề cập về Sáng kiến Net Zero?","opts":["It is being funded by the Red Hills Business Association.","It was inspired by similar initiatives in other cities.","It will use geothermal energy to power a city.","It will change the way an institution heats its buildings."],"ans":"D","xp":"Đáp án: (D)\nCăn cứ: Email, đoạn 1: \"Within three years, we expect to have geothermal wells installed and operational for the heating and cooling of our entire campus.\" (lắp giếng địa nhiệt để sưởi ấm và làm mát toàn bộ khuôn viên trường) → thay đổi cách trường đại học sưởi ấm các tòa nhà. (C) sai vì chỉ dùng cho khuôn viên trường, không phải cả thành phố.\n(A) Dự án được tài trợ bởi Hiệp hội Doanh nghiệp Red Hills.\n(B) Dự án được lấy cảm hứng từ các sáng kiến tương tự ở những thành phố khác.\n(C) Dự án sẽ sử dụng năng lượng địa nhiệt để cung cấp điện cho cả thành phố.\n(D) Dự án sẽ thay đổi cách một tổ chức làm nóng các tòa nhà của mình."},{"n":182,"q":"In the e-mail, the word \"conduct\" in paragraph 2, line 1, is closest in meaning to","qvi":"Trong email, từ \"conduct\" ở đoạn 2, dòng 1, gần nghĩa nhất với từ nào?","opts":["behave","accompany","transmit","carry out"],"ans":"D","xp":"Đáp án: (D)\nCăn cứ: \"we will conduct test drilling in several campus locations\" = chúng tôi sẽ tiến hành khoan thử nghiệm → conduct = carry out (tiến hành, thực hiện).\n(A) cư xử\n(B) đi cùng\n(C) truyền tải\n(D) tiến hành / thực hiện"},{"n":183,"q":"What can be concluded about the Red Hills Business District?","qvi":"Có thể kết luận điều gì về Khu Thương mại Red Hills?","opts":["It is located near a university campus.","It hosts an arts festival every July.","It includes the Oak Street Apartments.","It is home to the offices of the Daily Gazette."],"ans":"A","xp":"Đáp án: (A)\nCăn cứ: Email, đoạn 2: \"the crew will be drilling adjacent to the Red Hills Business District\" (khoan tại khu vực giáp ranh với Khu Kinh doanh Red Hills) và người gửi là liên lạc viên của Đại học Rilamore → Khu Red Hills nằm gần khuôn viên trường đại học.\n(A) Nằm gần khuôn viên trường đại học\n(B) Tổ chức một lễ hội nghệ thuật vào mỗi tháng 7\n(C) Bao gồm khu căn hộ Oak Street\n(D) Là nơi đặt văn phòng của tờ Daily Gazette"},{"n":184,"q":"Why most likely did the Red Hills Business Association change the dates of its concert series?","qvi":"Vì sao Hiệp hội Doanh nghiệp Red Hills nhiều khả năng đã thay đổi ngày tổ chức chuỗi hòa nhạc?","opts":["To take advantage of a new power source","To accommodate students' schedules","To avoid noise from nearby construction","To prevent a conflict with a similar event"],"ans":"C","xp":"Đáp án: (C)\nCăn cứ: Kết hợp 2 bài: Email: việc khoan bắt đầu từ ngày 5/6, kéo dài khoảng hai tuần, gây \"a higher-than-usual noise level\" (tiếng ồn cao hơn bình thường). Thông cáo: chuỗi hòa nhạc thường tổ chức vào các thứ Năm tháng 6 nay chuyển sang tháng 7 → để tránh tiếng ồn từ việc khoan gần đó.\n(A) Để tận dụng một nguồn năng lượng mới\n(B) Để phù hợp với lịch học của sinh viên\n(C) Để tránh tiếng ồn từ công trình xây dựng gần đó\n(D) Để tránh trùng với một sự kiện tương tự"},{"n":185,"q":"What is mentioned in the press release about the Cultural Center?","qvi":"Thông cáo báo chí đề cập điều gì về Trung tâm Văn hóa?","opts":["It will provide lunch for musicians.","It will have artwork for sale on its property.","It will offer arts-and-crafts workshops.","It will provide the stage for performers."],"ans":"B","xp":"Đáp án: (B)\nCăn cứ: Thông cáo, đoạn 2: \"local arts-and-crafts vendors will display their work on the lawn of the Cultural Center\" (các đơn vị bán hàng thủ công mỹ nghệ sẽ trưng bày sản phẩm trên thảm cỏ của Trung tâm Văn hóa) → có tác phẩm nghệ thuật được bày bán tại khuôn viên trung tâm.\n(A) Sẽ cung cấp bữa trưa cho các nhạc sĩ\n(B) Sẽ có các tác phẩm nghệ thuật được bày bán tại khuôn viên\n(C) Sẽ tổ chức các lớp học thủ công – mỹ thuật\n(D) Sẽ cung cấp sân khấu cho các nghệ sĩ biểu diễn"}]},{"ns":[186,190],"head":"Questions 186-190 refer to the following advertisement, form, and review.","passages":["<h3>Lawal Home Service: Serving Southern California for over 40 years</h3><p>Lawal Home Service provides roofing and solar solutions for Southern California residents in Inglewood and the surrounding areas. In addition to roof replacement, we offer a wide array of services, from attic insulation and gutter restoration to fixing leaks and installing solar panels.</p><p>Lawal Home Service prides itself on transparent communication and attention to detail. Our project supervisors are always on-site to answer client questions, provide updates, and ensure a safe and clean worksite. To request a free roofing diagnosis, visit www.lawalhomeservice.com or call our booking agent at 310-555-0108.</p>","<h3>Lawal Home Service Contact Form</h3><p>Trust the experts at Lawal Home Service to diagnose your roofing needs promptly and professionally. Please take a few minutes to complete the form with as much detail as possible. Remember, all roofs installed by Lawal have a 25-year warranty.</p><table><tr><td>Name</td><td>Drew Gerson</td></tr><tr><td>Date</td><td>December 12</td></tr><tr><td>E-mail</td><td>dgerson95@onyxmail.com</td></tr><tr><td>Phone</td><td>310-555-0192</td></tr><tr><td>Address</td><td>820 North Acacia Street<br>Inglewood, CA 90301</td></tr><tr><td>How may we help you?</td><td>During last week's windstorm, several roof shingles were torn loose and need replacing. I am considering replacing the entire roof as it is over 30 years old, and water has begun to drip through the section over the patio. I would appreciate talking to someone who could tell me my options and provide an estimate.</td></tr></table>","<h3>Neighborhood Reviews: Lawal Home Service</h3><p>★★★★★</p><p><i>\"I was very pleased with the thoroughness of their work.\"</i></p><p>I left a description of my problem with Lawal Home Service, and one of the company's estimators came to inspect my roof the very next day. After I decided to replace the roof, the Lawal Home Service crew was able to get to work the following week. Diana Perez was on-site for the whole job as promised and answered all my questions. Work was started on December 19, and it was finished on December 20. Once the roofing was finished, the crew did a great job cleaning up. They used two magnetic devices resembling lawnmowers and swept over my entire lawn to find any dropped roofing nails. I had never seen anything like that! I was very pleased with the thoroughness of their work.</p><p>— Drew Gerson, Inglewood, CA</p>"],"vi":"QUẢNG CÁO\nLawal Home Service: Phục vụ khu vực Nam California trong hơn 40 năm\n\nLawal Home Service cung cấp các giải pháp về mái nhà và năng lượng mặt trời cho cư dân Nam California tại Inglewood và các khu vực lân cận. Ngoài việc thay thế mái nhà, chúng tôi còn cung cấp một loạt các dịch vụ, từ cách nhiệt tầng áp mái và phục hồi máng xối đến sửa chữa rò rỉ và lắp đặt các tấm pin năng lượng mặt trời.\n\nLawal Home Service tự hào về sự giao tiếp minh bạch và sự chú trọng đến từng chi tiết. Các giám sát viên dự án của chúng tôi luôn có mặt tại hiện trường để giải đáp các thắc mắc của khách hàng, cung cấp các cập nhật và đảm bảo một công trường an toàn và sạch sẽ. Để yêu cầu chẩn đoán mái nhà miễn phí, hãy truy cập www.lawalhomeservice.com hoặc gọi cho nhân viên đặt lịch của chúng tôi theo số 310-555-0108.\n\nMẪU LIÊN HỆ CỦA LAWAL HOME SERVICE\nHãy tin tưởng vào các chuyên gia tại Lawal Home Service để chẩn đoán các nhu cầu về mái nhà của bạn một cách nhanh chóng và chuyên nghiệp. Vui lòng dành ít phút để hoàn thành mẫu đơn với càng nhiều chi tiết càng tốt. Hãy nhớ rằng, tất cả các mái nhà được lắp đặt bởi Lawal đều được bảo hành 25 năm.\n\nHọ tên: Drew Gerson\nNgày: 12 tháng 12\nEmail: dgerson95@onyxmail.com\nĐiện thoại: 310-555-0192\nĐịa chỉ: 820 North Acacia Street, Inglewood, CA 90301\nChúng tôi có thể giúp gì cho bạn? Trong trận bão gió tuần trước, một vài tấm lợp mái đã bị bung ra và cần được thay thế. Tôi đang cân nhắc việc thay thế toàn bộ mái nhà vì nó đã hơn 30 năm tuổi, và nước đã bắt đầu nhỏ giọt qua phần mái phía trên hiên. Tôi rất mong được trao đổi với ai đó có thể cho tôi biết các lựa chọn của mình và cung cấp một bản ước tính chi phí.\n\nĐÁNH GIÁ TỪ KHU LÂN CẬN: LAWAL HOME SERVICE\n★★★★★ \"Tôi rất hài lòng với sự tỉ mỉ trong công việc của họ.\"\n\nTôi đã để lại mô tả về vấn đề của mình cho Lawal Home Service, và một trong những nhân viên ước tính của công ty đã đến kiểm tra mái nhà của tôi ngay ngày hôm sau. Sau khi tôi quyết định thay mái nhà, đội ngũ Lawal Home Service đã có thể bắt đầu công việc vào tuần kế tiếp. Diana Perez đã có mặt tại hiện trường trong suốt quá trình thực hiện như đã hứa và trả lời mọi câu hỏi của tôi. Công việc được bắt đầu vào ngày 19 tháng 12 và hoàn thành vào ngày 20 tháng 12. Sau khi lợp mái xong, đội ngũ đã dọn dẹp rất tốt. Họ đã sử dụng hai thiết bị từ tính trông giống như máy cắt cỏ và quét qua toàn bộ bãi cỏ của tôi để tìm bất kỳ chiếc đinh lợp mái nào bị rơi rớt. Tôi chưa bao giờ thấy bất cứ điều gì giống như vậy! Tôi rất hài lòng với sự tỉ mỉ trong công việc của họ.\n\n— Drew Gerson, Inglewood, CA","qs":[{"n":186,"q":"According to the advertisement, what is one type of work performed by Lawal Home Service?","qvi":"Theo quảng cáo, một trong những dịch vụ mà Lawal Home Service cung cấp là gì?","opts":["Planting trees","Repairing gutters","Building home additions","Replacing heating systems"],"ans":"B","xp":"Đáp án: (B)\nCăn cứ: Quảng cáo, đoạn 1: \"we offer a wide array of services, from attic insulation and gutter restoration to fixing leaks...\" → gutter restoration (phục hồi máng xối) = repairing gutters.\n(A) Trồng cây\n(B) Sửa chữa máng xối\n(C) Xây thêm phần mở rộng cho ngôi nhà\n(D) Thay thế hệ thống sưởi"},{"n":187,"q":"What does Mr. Gerson indicate on the form about his roof?","qvi":"Ông Gerson cho biết điều gì về mái nhà của mình trong biểu mẫu?","opts":["It has developed a leak.","It was recently replaced.","It was not expensive to install.","It is under warranty for 30 years."],"ans":"A","xp":"Đáp án: (A)\nCăn cứ: Biểu mẫu: \"water has begun to drip through the section over the patio\" (nước đã bắt đầu nhỏ giọt qua phần mái phía trên hiên) → mái nhà bị dột.\n(A) Mái nhà đã bị dột\n(B) Mái nhà mới được thay gần đây\n(C) Việc lắp đặt không tốn kém\n(D) Mái nhà được bảo hành trong 30 năm"},{"n":188,"q":"When did Lawal Home Service inspect Mr. Gerson's roof?","qvi":"Lawal Home Service đã kiểm tra mái nhà của ông Gerson vào ngày nào?","opts":["On December 12","On December 13","On December 19","On December 20"],"ans":"B","xp":"Đáp án: (B)\nCăn cứ: Kết hợp 2 bài: Biểu mẫu được gửi ngày December 12. Bài đánh giá: \"one of the company's estimators came to inspect my roof the very next day\" (đến kiểm tra ngay ngày hôm sau) → ngày 13 tháng 12.\n(A) Ngày 12 tháng 12\n(B) Ngày 13 tháng 12\n(C) Ngày 19 tháng 12\n(D) Ngày 20 tháng 12"},{"n":189,"q":"Who most likely is Ms. Perez?","qvi":"Bà Perez nhiều khả năng là ai?","opts":["A project supervisor","A roofing estimator","An interior decorator","A booking agent"],"ans":"A","xp":"Đáp án: (A)\nCăn cứ: Kết hợp 2 bài: Bài đánh giá: \"Diana Perez was on-site for the whole job as promised and answered all my questions.\" Quảng cáo: \"Our project supervisors are always on-site to answer client questions\" → bà Perez là giám sát dự án.\n(A) Giám sát dự án\n(B) Nhân viên ước tính chi phí sửa mái nhà\n(C) Nhà thiết kế nội thất\n(D) Nhân viên đặt lịch"},{"n":190,"q":"According to the review, what surprised Mr. Gerson about the crew from Lawal Home Service?","qvi":"Theo bài đánh giá, điều gì khiến ông Gerson ngạc nhiên về đội ngũ của Lawal Home Service?","opts":["The price they charged","The warranty they offered","The quality of their materials","The tools they used for a job"],"ans":"D","xp":"Đáp án: (D)\nCăn cứ: Bài đánh giá: \"They used two magnetic devices resembling lawnmowers... I had never seen anything like that!\" (Họ dùng hai thiết bị từ tính giống máy cắt cỏ... Tôi chưa bao giờ thấy điều gì như vậy!) → ngạc nhiên về công cụ họ dùng.\n(A) Mức giá họ đưa ra\n(B) Chế độ bảo hành mà họ cung cấp\n(C) Chất lượng vật liệu họ sử dụng\n(D) Những công cụ họ dùng để làm việc"}]},{"ns":[191,195],"head":"Questions 191-195 refer to the following e-mails and form.","passages":["<div class=\"hdr\"><p><b>To:</b> Omar Balaji &lt;obalaji@darbourycompany.com&gt;</p><p><b>From:</b> Juanita Pereira &lt;jpereira@bunbunbooks.com&gt;</p><p><b>Date:</b> May 10</p><p><b>Subject:</b> Notebook inquiry</p></div><p>Dear Mr. Balaji,</p><p>We are expanding our office supply section at Bun Bun Books and would like to offer a selection of blank notebooks with lined pages. We would like your help creating the following cover designs.</p><table><tr><th>Cover Design Name</th><th>Central Image</th><th>Background Color</th></tr><tr><td>Great Thoughts</td><td>Lightbulb, lightning bolt, and star icons</td><td>Blue</td></tr><tr><td>World Suitcase</td><td>Suitcase with country name travel stickers</td><td>Black</td></tr><tr><td>Lavender Bouquet</td><td>Large bunch of lavender on tall, pale green stems</td><td>Yellow</td></tr><tr><td>Sail Away</td><td>Sun setting in the sky above a sailboat on a lake</td><td>White</td></tr></table><p>We need to have notebooks in stock in time for our annual sale starting August 1. After approving the sample covers, when would we need to place our order?</p><p>Thank you,</p><p>Juanita Pereira</p>","<div class=\"hdr\"><p><b>To:</b> Juanita Pereira &lt;jpereira@bunbunbooks.com&gt;</p><p><b>From:</b> Omar Balaji &lt;obalaji@darbourycompany.com&gt;</p><p><b>Date:</b> May 25</p><p><b>Subject:</b> Re: Notebook inquiry</p></div><p>Hello, Ms. Pereira,</p><p>I have shipped some sample notebook covers for your inspection. Unfortunately, I was not able to include one of the designs for your approval because it needed a late-stage change to the background color. The sticker art did not show up well against the original black background. We are testing a light-beige color, and I will send the updated sample cover to you after it has been approved internally.</p><p>I should have the last sample to you by the end of this week. As long as you send your approval of all covers by June 11, we will be able to ship your entire order of bound notebooks before July 20. You will have everything before your sale that begins on August 1. Please contact me if you have any questions.</p><p>Best regards,</p><p>Omar Balaji, Darboury Company</p>","<h3>Darboury Company</h3><h4>Order Form</h4><p><b>Customer:</b> Bun Bun Books<br><b>Ship by:</b> July 15<br><b>Shipping method:</b> Standard<br><b>Requested delivery date:</b> July 20</p><table><tr><th>Item code</th><th>Product Description</th><th>Cover Design</th><th>Amount</th></tr><tr><td>N3-GT</td><td>Standard-size spiral notebook</td><td>Great Thoughts</td><td>200</td></tr><tr><td>N3-WS</td><td>Standard-size spiral notebook</td><td>World Suitcase</td><td>200</td></tr><tr><td>H3-LB</td><td>Small hardbound journal notebook</td><td>Lavender Bouquet</td><td>150</td></tr><tr><td>H3-SA</td><td>Small hardbound journal notebook</td><td>Sail Away</td><td>150</td></tr><tr><td>D1</td><td>Large metal display rack<br>(holds standard-size spiral notebooks)</td><td>—</td><td>1</td></tr></table>"],"vi":"EMAIL 1\nNgười nhận: Omar Balaji <obalaji@darbourycompany.com>\nNgười gửi: Juanita Pereira <jpereira@bunbunbooks.com>\nNgày: 10 tháng 5\nChủ đề: Yêu cầu về sổ tay\n\nThưa ông Balaji,\n\nChúng tôi đang mở rộng khu vực đồ dùng văn phòng tại Bun Bun Books và muốn bày bán một số mẫu sổ tay trơn có dòng kẻ. Chúng tôi rất mong nhận được sự hỗ trợ của ông trong việc thiết kế các mẫu bìa sau.\n\nTên mẫu bìa | Hình ảnh trung tâm | Màu nền\nGreat Thoughts | Biểu tượng bóng đèn, tia sét và ngôi sao | Xanh dương\nWorld Suitcase | Vali với các nhãn dán du lịch ghi tên các quốc gia | Đen\nLavender Bouquet | Bó hoa oải hương lớn trên những cành cao màu xanh lá nhạt | Vàng\nSail Away | Mặt trời lặn trên bầu trời phía trên một chiếc thuyền buồm trên hồ | Trắng\n\nChúng tôi cần có sẵn các cuốn sổ này trong kho kịp cho đợt giảm giá thường niên bắt đầu ngày 1 tháng 8. Sau khi phê duyệt các mẫu bìa, khi nào chúng tôi cần đặt hàng?\n\nXin cảm ơn ông,\nJuanita Pereira\n\nEMAIL 2\nNgười nhận: Juanita Pereira <jpereira@bunbunbooks.com>\nNgười gửi: Omar Balaji <obalaji@darbourycompany.com>\nNgày: 25 tháng 5\nChủ đề: Phản hồi: Yêu cầu về sổ tay\n\nChào cô Pereira,\n\nTôi đã gửi một số mẫu bìa sổ tay để cô xem xét. Tuy nhiên, rất tiếc tôi không thể gửi kèm một trong các thiết kế để cô phê duyệt vì nó cần thay đổi màu nền vào giai đoạn cuối. Hình nhãn dán không hiển thị rõ trên nền đen ban đầu. Hiện chúng tôi đang thử nghiệm màu be nhạt và tôi sẽ gửi mẫu bìa cập nhật cho cô sau khi được phê duyệt nội bộ.\n\nTôi dự kiến sẽ gửi mẫu cuối cùng cho cô vào cuối tuần này. Miễn là cô gửi phê duyệt tất cả các bìa trước ngày 11 tháng 6, chúng tôi sẽ có thể giao toàn bộ đơn hàng sổ tay đã đóng gáy trước ngày 20 tháng 7. Cô sẽ có mọi thứ trước đợt giảm giá bắt đầu vào ngày 1 tháng 8. Xin vui lòng liên hệ với tôi nếu cô có bất kỳ câu hỏi nào.\n\nTrân trọng,\nOmar Balaji, Darboury Company\n\nPHIẾU ĐẶT HÀNG\nDarboury Company – Phiếu đặt hàng\nKhách hàng: Bun Bun Books\nGửi hàng trước ngày: 15 tháng 7\nPhương thức giao hàng: Tiêu chuẩn\nNgày yêu cầu giao hàng: 20 tháng 7\n\nMã hàng | Mô tả sản phẩm | Thiết kế bìa | Số lượng\nN3-GT | Sổ gáy xoắn khổ tiêu chuẩn | Great Thoughts | 200\nN3-WS | Sổ gáy xoắn khổ tiêu chuẩn | World Suitcase | 200\nH3-LB | Sổ bìa cứng nhỏ | Lavender Bouquet | 150\nH3-SA | Sổ bìa cứng nhỏ | Sail Away | 150\nD1 | Kệ trưng bày kim loại lớn (đựng sổ gáy xoắn khổ tiêu chuẩn) | — | 1","qs":[{"n":191,"q":"What is one service that Darboury Company most likely provides?","qvi":"Darboury Company có khả năng cung cấp dịch vụ nào?","opts":["Travel booking","Textbook publishing","Flower delivery","Graphic design"],"ans":"D","xp":"Đáp án: (D)\nCăn cứ: Email 1: \"We would like your help creating the following cover designs.\" (nhờ ông giúp thiết kế các mẫu bìa) → Darboury Company làm thiết kế đồ họa.\n(A) Đặt vé du lịch\n(B) Xuất bản sách giáo khoa\n(C) Giao hoa\n(D) Thiết kế đồ họa"},{"n":192,"q":"What sample was delayed?","qvi":"Mẫu nào đã bị giao trễ?","opts":["Great Thoughts","World Suitcase","Lavender Bouquet","Sail Away"],"ans":"B","xp":"Đáp án: (B)\nCăn cứ: Kết hợp 2 bài: Email 2: một mẫu chưa gửi được vì \"The sticker art did not show up well against the original black background\" (hình nhãn dán không rõ trên nền đen ban đầu). Email 1: mẫu có nhãn dán (travel stickers) và nền đen (Black) là World Suitcase.\n(A) Great Thoughts\n(B) World Suitcase\n(C) Lavender Bouquet\n(D) Sail Away"},{"n":193,"q":"When is the deadline for Ms. Pereira to approve samples?","qvi":"Hạn chót để cô Pereira phê duyệt các mẫu là khi nào?","opts":["May 25","June 11","July 20","August 1"],"ans":"B","xp":"Đáp án: (B)\nCăn cứ: Email 2: \"As long as you send your approval of all covers by June 11, we will be able to ship your entire order...\" (miễn là cô gửi phê duyệt tất cả các bìa trước ngày 11/6).\n(A) Ngày 25 tháng 5\n(B) Ngày 11 tháng 6\n(C) Ngày 20 tháng 7\n(D) Ngày 1 tháng 8"},{"n":194,"q":"What does the form indicate about the Bun Bun Books order?","qvi":"Biểu mẫu cho biết điều gì về đơn hàng của Bun Bun Books?","opts":["It will include a display stand.","It will ship overnight.","It will be paid upon delivery.","It will arrive late."],"ans":"A","xp":"Đáp án: (A)\nCăn cứ: Phiếu đặt hàng: mã D1 \"Large metal display rack\" (kệ trưng bày kim loại lớn), số lượng 1 → đơn hàng có một kệ trưng bày. (B) sai vì phương thức giao là Standard (tiêu chuẩn).\n(A) Sẽ bao gồm một kệ trưng bày\n(B) Sẽ được giao trong đêm (giao nhanh qua đêm)\n(C) Sẽ được thanh toán khi nhận hàng\n(D) Sẽ bị giao trễ"},{"n":195,"q":"What is the background color on the cover of item N3-GT?","qvi":"Màu nền trên bìa của sản phẩm N3-GT là gì?","opts":["Blue","Black","Yellow","White"],"ans":"A","xp":"Đáp án: (A)\nCăn cứ: Kết hợp 2 bài: Phiếu đặt hàng: N3-GT có thiết kế bìa Great Thoughts. Email 1: Great Thoughts có màu nền Blue (xanh dương).\n(A) Xanh dương\n(B) Đen\n(C) Vàng\n(D) Trắng"}]},{"ns":[196,200],"head":"Questions 196-200 refer to the following e-mail, review, and notice.","passages":["<div class=\"hdr\"><p><b>To:</b> Managers</p><p><b>From:</b> Charlotte Black</p><p><b>Date:</b> August 16</p><p><b>Subject:</b> Employee of the month</p></div><p>Dear Managers,</p><p>It is time to vote for the Wilson Autos Employee of the Month for September. Here are the nominees.</p><p><b>Erica Boyd</b> has been with us for only a few months but has already shown great promise and is eager to learn new things.</p><p><b>Lauren Almahdi</b> is very proactive. If something needs to be done, she will point it out to a manager and volunteer to take care of it herself.</p><p><b>Nick Salehi</b> found a glitch in our computer system and stopped us from incorrectly ordering unnecessary inventory (thus saving us money).</p><p><b>Max Rhodes</b> has been especially helpful with training new hires. He is calm and patient and explains our procedures well.</p><p>Please respond to this e-mail by Friday with your vote. The winner must receive at least three votes. The winner will be posted at our front desk and on our Web site next Monday.</p><p>Thanks,</p><p>Charlotte Black<br>General Manager, Wilson Autos</p>","<p>https://www.westchesterreviews.com</p><h3>Wilson Autos (Westchester)</h3><p>★★★★★</p><p>My wife and I just bought a new Excelera truck at the Wilson Autos Westchester location with the help of Erica Boyd. Even though she was new, she was very knowledgeable about all the trucks on the lot that we wanted to test drive. The few questions she was unable to answer were quickly addressed by her mentor, Max. We were very pleased with the customer service and even more delighted when the general manager agreed to sell us the Excelera for the same price that a competing dealership was advertising. I highly recommend Wilson Autos if you are in the market for a new vehicle!</p><p>—Henry Riggs, August 22</p>","<h3>The employee of the month for September is ERICA BOYD!</h3><p>In her three months at Wilson Autos, Erica has picked up new skills quickly and is always trying to learn more. She has become very knowledgeable about our inventory and is able to share her knowledge with customers to complete sales. She has also been instrumental in encouraging satisfied customers to post comments on our social media pages. We received more great reviews in the past month than we did in the four previous months combined!</p><p>Erica has received a $50 gift card to Alonzo's Restaurant as a thank-you for her excellent work. Congratulations, Erica!</p>"],"vi":"EMAIL\nNgười nhận: Các quản lý\nNgười gửi: Charlotte Black\nNgày: 16 tháng 8\nChủ đề: Nhân viên xuất sắc của tháng\n\nThưa các anh/chị quản lý,\n\nĐã đến lúc bình chọn Nhân viên xuất sắc của tháng 9 tại Wilson Autos. Dưới đây là các ứng viên được đề cử.\n\nErica Boyd mới làm việc với chúng ta vài tháng nhưng đã cho thấy nhiều triển vọng và rất ham học hỏi những điều mới.\n\nLauren Almahdi rất chủ động. Khi có việc cần làm, cô ấy sẽ chỉ ra cho quản lý và tự nguyện đảm nhận việc đó.\n\nNick Salehi đã phát hiện ra một lỗi trong hệ thống máy tính của chúng ta và ngăn chúng ta đặt hàng nhầm những hàng tồn kho không cần thiết (nhờ đó tiết kiệm tiền cho công ty).\n\nMax Rhodes đặc biệt hữu ích trong việc đào tạo nhân viên mới. Anh ấy điềm tĩnh, kiên nhẫn và giải thích các quy trình của chúng ta rất rõ ràng.\n\nVui lòng phản hồi email này trước thứ Sáu với phiếu bầu của anh/chị. Người chiến thắng phải nhận được ít nhất ba phiếu bầu. Người chiến thắng sẽ được công bố tại quầy lễ tân và trên trang web của chúng ta vào thứ Hai tuần tới.\n\nCảm ơn,\nCharlotte Black\nTổng Giám đốc, Wilson Autos\n\nBÀI ĐÁNH GIÁ\nhttps://www.westchesterreviews.com\nWilson Autos (Westchester)\n★★★★★\n\nVợ tôi và tôi vừa mua một chiếc xe tải Excelera mới tại chi nhánh Wilson Autos Westchester với sự giúp đỡ của Erica Boyd. Mặc dù là nhân viên mới, cô ấy rất am hiểu về tất cả các xe tải trong bãi mà chúng tôi muốn lái thử. Một vài câu hỏi cô ấy không trả lời được đã nhanh chóng được người hướng dẫn của cô, anh Max, giải đáp. Chúng tôi rất hài lòng với dịch vụ khách hàng và còn vui hơn nữa khi tổng giám đốc đồng ý bán cho chúng tôi chiếc Excelera với cùng mức giá mà một đại lý cạnh tranh đang quảng cáo. Tôi rất khuyến khích Wilson Autos nếu bạn đang có ý định mua một chiếc xe mới!\n\n— Henry Riggs, ngày 22 tháng 8\n\nTHÔNG BÁO\nNHÂN VIÊN XUẤT SẮC THÁNG 9 LÀ ERICA BOYD!\n\nTrong ba tháng làm việc tại Wilson Autos, Erica đã học được các kỹ năng mới rất nhanh và luôn cố gắng học hỏi thêm. Cô ấy đã trở nên rất am hiểu về kho xe của chúng ta và có thể chia sẻ kiến thức đó với khách hàng để hoàn tất việc bán hàng. Cô ấy cũng đóng vai trò quan trọng trong việc khuyến khích những khách hàng hài lòng đăng bình luận trên các trang mạng xã hội của chúng ta. Trong tháng qua, chúng ta đã nhận được nhiều đánh giá tốt hơn cả bốn tháng trước đó cộng lại!\n\nErica đã nhận được một thẻ quà tặng trị giá 50 đô la tại nhà hàng Alonzo's như lời cảm ơn cho sự làm việc xuất sắc của cô. Xin chúc mừng, Erica!","qs":[{"n":196,"q":"What is the purpose of the e-mail?","qvi":"Mục đích của email là gì?","opts":["To share a list of job candidates","To ask for opinions from managers","To summarize a managers' meeting","To nominate a manager for an award"],"ans":"B","xp":"Đáp án: (B)\nCăn cứ: Email: \"It is time to vote for the Wilson Autos Employee of the Month... Please respond to this e-mail by Friday with your vote.\" (đề nghị các quản lý bình chọn) → xin ý kiến (phiếu bầu) từ các quản lý. (A) sai vì đây là danh sách nhân viên được đề cử, không phải ứng viên xin việc.\n(A) Chia sẻ danh sách các ứng viên xin việc\n(B) Xin ý kiến từ các quản lý\n(C) Tóm tắt một cuộc họp của các quản lý\n(D) Đề cử một quản lý cho một giải thưởng"},{"n":197,"q":"According to the e-mail, who identified a technical problem?","qvi":"Theo email, ai là người phát hiện ra một vấn đề kỹ thuật?","opts":["Mr. Salehi","Ms. Almahdi","Mr. Rhodes","Ms. Black"],"ans":"A","xp":"Đáp án: (A)\nCăn cứ: Email: \"Nick Salehi found a glitch in our computer system\" (phát hiện ra một lỗi trong hệ thống máy tính) → glitch = technical problem.\n(A) Ông Salehi\n(B) Bà Almahdi\n(C) Ông Rhodes\n(D) Bà Black"},{"n":198,"q":"What can be concluded about Mr. Riggs?","qvi":"Có thể kết luận điều gì về ông Riggs?","opts":["His previous vehicle was an Excelera truck.","He is a neighbor of Ms. Boyd's.","He has purchased a vehicle from Wilson Autos in the past.","He negotiated with Ms. Black for a lower price."],"ans":"D","xp":"Đáp án: (D)\nCăn cứ: Kết hợp 2 bài: Bài đánh giá: \"the general manager agreed to sell us the Excelera for the same price that a competing dealership was advertising\" (tổng giám đốc đồng ý bán với giá bằng đại lý cạnh tranh). Email: Charlotte Black là \"General Manager, Wilson Autos\" → ông Riggs đã thương lượng giá thấp hơn với bà Black.\n(A) Chiếc xe trước đây của ông là xe tải Excelera\n(B) Ông là hàng xóm của bà Boyd\n(C) Ông đã từng mua xe từ Wilson Autos trước đây\n(D) Ông đã thương lượng với bà Black để được giá thấp hơn"},{"n":199,"q":"What is indicated in the notice about Ms. Boyd?","qvi":"Thông báo cho biết điều gì về bà Boyd?","opts":["She eats regularly at Alonzo's Restaurant.","She manages social media sites for Wilson Autos.","She is responsible for an increase in customer feedback.","She recently completed a sales training course."],"ans":"C","xp":"Đáp án: (C)\nCăn cứ: Thông báo: \"She has also been instrumental in encouraging satisfied customers to post comments on our social media pages. We received more great reviews in the past month than we did in the four previous months combined!\" → Erica giúp tăng lượng phản hồi/đánh giá của khách hàng.\n(A) Bà ấy thường xuyên ăn tại nhà hàng Alonzo's\n(B) Bà ấy quản lý các trang mạng xã hội cho Wilson Autos\n(C) Bà ấy góp phần làm tăng phản hồi của khách hàng\n(D) Bà ấy vừa hoàn thành một khóa đào tạo bán hàng"},{"n":200,"q":"What is most likely true about Ms. Boyd?","qvi":"Điều gì có khả năng đúng nhất về bà Boyd?","opts":["She received votes from at least three managers.","She was the top salesperson in August.","She has years of experience in the auto industry.","She was hired by Wilson Autos in April."],"ans":"A","xp":"Đáp án: (A)\nCăn cứ: Kết hợp 2 bài: Email: \"The winner must receive at least three votes.\" (người thắng phải có ít nhất ba phiếu). Thông báo: Erica Boyd là nhân viên xuất sắc tháng 9 → bà ấy đã nhận được phiếu bầu từ ít nhất ba quản lý. (C) sai vì bà mới làm được ba tháng.\n(A) Bà ấy nhận được phiếu bầu từ ít nhất ba quản lý\n(B) Bà ấy là nhân viên bán hàng giỏi nhất tháng Tám\n(C) Bà ấy có nhiều năm kinh nghiệm trong ngành ô tô\n(D) Bà ấy được Wilson Autos tuyển dụng vào tháng Tư"}]}]}};
